import * as THREE from 'three';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js';
import { meshRotationToDataDegrees } from '../utils/transformMath.js';
import { resolveExtrusionBasis, resolveSingleAxis } from '../objects/PrimitiveObject.js';

// Encapsula o TransformControls do Three.js: troca de modo (mover/rotacionar/
// escalar), respeito ao estado "fixado" (locked) e sincronizacao das
// transformacoes de volta para o store correspondente (referencia ou
// primitiva - por isso `onTransformChange` recebe o tipo do objeto atual).
export class TransformControlsManager {
  constructor({ sceneManager, selectionManager, onTransformChange }) {
    this.sceneManager = sceneManager;
    this.selectionManager = selectionManager;
    this.onTransformChange = onTransformChange;
    this.mode = 'translate';
    this.currentMesh = null;
    this.currentType = null;
    this.currentId = null;

    this.controls = new TransformControls(sceneManager.camera, sceneManager.renderer.domElement);
    this.controls.setMode(this.mode);
    this.controls.addEventListener('dragging-changed', (event) => {
      sceneManager.controls.enabled = !event.value;
      selectionManager.setSuspended(event.value);
    });
    this.controls.addEventListener('objectChange', () => this._onObjectChange());

    // Em versoes recentes o TransformControls e ele mesmo um Object3D auxiliar
    // que precisa ser adicionado a cena para renderizar os gizmos.
    sceneManager.scene.add(this.controls.getHelper ? this.controls.getHelper() : this.controls);

    this.controls.enabled = false;
  }

  setMode(mode) {
    this.mode = mode;
    this.controls.setMode(mode);
  }

  attach(mesh, data, type) {
    this.currentMesh = mesh;
    this.currentType = type;
    this.currentId = data?.id ?? null;
    this.currentData = data ?? null;
    if (!mesh || data?.locked) {
      this.controls.detach();
      this.controls.enabled = false;
      return;
    }
    this.controls.attach(mesh);
    this.controls.enabled = true;
  }

  detach() {
    this.currentMesh = null;
    this.currentType = null;
    this.currentId = null;
    this.currentData = null;
    this.controls.detach();
    this.controls.enabled = false;
  }

  refreshLockState(data) {
    if (!this.currentMesh) return;
    if (data.locked) {
      this.controls.detach();
      this.controls.enabled = false;
    } else {
      this.controls.attach(this.currentMesh);
      this.controls.enabled = true;
    }
  }

  _onObjectChange() {
    const mesh = this.currentMesh;
    if (!mesh || !this.currentType) return;

    // Cilindro nao tem posicao livre (PAXI+PDIS+PHEI+PDIA, sem PX/PY/PZ -
    // ver core/PrimitiveStore.js e PrimitiveObject.resolveCylinderOrigin) -
    // arrastar o gizmo desliza o cilindro AO LONGO do proprio eixo (projecao
    // do arrasto na reta do eixo), escrevendo de volta so a distancia
    // (PDIS); qualquer componente do arrasto perpendicular ao eixo e
    // ignorada, ja que nao ha atributo nenhum pra guarda-la.
    if (this.currentType === 'primitive' && this.currentData?.type === 'cylinder') {
      const { axis, originPoint } = resolveSingleAxis(this.currentData);
      const base = originPoint ?? new THREE.Vector3(0, 0, 0);
      const distance = mesh.position.clone().sub(base).dot(axis);
      this.onTransformChange(this.currentType, this.currentId, { distance: roundToString(distance) });
      return;
    }

    // Extrusao com PAAX/PBAX referenciando um P-point (ver
    // objects/PrimitiveObject.js: resolveExtrusionBasis) guarda em
    // `data.position` um DESLOCAMENTO a partir da posicao desse P-point, nao
    // a posicao absoluta de mundo - arrastar o gizmo (que so conhece a
    // posicao de mundo do mesh) precisa subtrair essa origem antes de
    // escrever de volta no store, senao o solido "pularia" a cada arrasto
    // (origem somada 2x no proximo sync).
    let worldPos = mesh.position;
    if (this.currentType === 'primitive' && this.currentData?.type === 'extrusion') {
      const { originPoint } = resolveExtrusionBasis(this.currentData);
      if (originPoint) worldPos = mesh.position.clone().sub(originPoint);
    }

    this.onTransformChange(this.currentType, this.currentId, {
      // Posicao e sempre string (expressao - ver utils/expressionEvaluator.js);
      // um arrasto do gizmo escreve um numero literal, arredondado para nao
      // acumular ruido de ponto flutuante (123.45600000000002 -> "123.456").
      position: { x: roundToString(worldPos.x), y: roundToString(worldPos.y), z: roundToString(worldPos.z) },
      rotation: meshRotationToDataDegrees(mesh),
      scale: { x: mesh.scale.x, y: mesh.scale.y, z: mesh.scale.z }
    });
  }
}

function roundToString(value) {
  return String(Math.round(value * 1000) / 1000);
}
