import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Estrutura de dados central de uma DEFINICAO de parametro de catalogo -
// equivalente a uma linha da tabela "Parameter Definitions" do PARAGON
// (numero + descricao). Ver
// REFERENCIAS/172166728-Catalogues-and-Specifications-Reference-Manual.pdf,
// capitulo 7/8, e o exemplo REFERENCIAS/SUPORTE_SDE-37-005.pmlmac.
//
// IMPORTANTE: uma definicao de parametro NAO tem valor proprio. O valor de
// cada parametro e especifico de cada VARIANTE/Componente (ver
// VariantStore.js) - a definicao aqui e so o "cabecalho da coluna" (numero +
// descricao) que a grade de variantes usa para montar suas colunas PA1..PAn.
// Isso corresponde exatamente a tela do PARAGON: "Parameter Definitions"
// (numero/descricao) em cima, e a grade de Componentes (um valor por
// parametro, por componente) embaixo.
//
// Parametros nao tem posicao/representacao 3D - sao dados puros, editados
// diretamente na lista (sem selecao/gizmo/TransformControls).
export function createDefaultParameterData(overrides = {}) {
  return {
    id: createId(),
    number: 1, // No - numero do parametro (PARA[n]/PARAM n)
    description: '', // Descricao (ex.: 'DIAM NOMINAL')
    ...overrides
  };
}

export class ParameterStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  addParameter(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('parameter:added', data);
    return data;
  }

  updateParameter(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('parameter:updated', updated);
    return updated;
  }

  removeParameter(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('parameter:removed', id);
  }

  clear() {
    [...this.order].forEach((id) => this.removeParameter(id));
  }
}
