import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Uma Cota e uma anotacao de medida (distancia entre 2 pontos) - ferramenta
// de conferencia visual do proprio app, SEM equivalente no catalogo real do
// E3D. Guardada na cena (JSON) para persistir entre sessoes, mas marcada
// para NUNCA entrar num futuro export de DATAL para o E3D (essa exportacao
// ainda nao existe neste app - isso e so uma marca de intencao para quando
// existir).
//
// Cada ponta (pointA/pointB) e sempre uma referencia a um "ponto colavel"
// de outro objeto da cena - nunca uma coordenada solta - guardando o TIPO/ID
// do objeto e uma CHAVE identificando qual ponto dele (ver
// objects/SnapPoints.js para a lista de chaves por tipo/forma). Isso e o
// que faz a Cota "acompanhar" quando a geometria de origem muda: a posicao
// nunca fica congelada, e sempre recalculada contra o estado atual do
// objeto referenciado.
//
// { objectType: 'reference'|'primitive'|'ppoint', objectId, anchorKey }
export function createDefaultCotaData(overrides = {}) {
  return {
    id: createId(),
    name: 'Cota',
    pointA: null,
    pointB: null,
    visible: true,
    ...overrides
  };
}

export class CotaStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  addCota(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('cota:added', data);
    return data;
  }

  updateCota(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('cota:updated', updated);
    return updated;
  }

  removeCota(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('cota:removed', id);
  }

  // Uma Cota que aponta pra um objeto que acabou de ser apagado fica
  // "orfa" e sem sentido - remove junto (chamado pelos handlers de
  // primitive:removed/point:removed/reference:removed em main.js).
  removeCotasReferencing(objectType, objectId) {
    const toRemove = this.list().filter(
      (cota) =>
        (cota.pointA?.objectType === objectType && cota.pointA?.objectId === objectId) ||
        (cota.pointB?.objectType === objectType && cota.pointB?.objectId === objectId)
    );
    toRemove.forEach((cota) => this.removeCota(cota.id));
  }

  clear() {
    [...this.order].forEach((id) => this.removeCota(id));
  }
}
