import { renderEntityList } from './EntityTree.js';
import { createCollapsibleSection } from './CollapsibleSection.js';

// Painel lateral esquerdo: lista de P-points (pontos geometricos de conexao)
// da cena - equivalentes aos PTAXI/PTMIX de um PTSET do catalogo do E3D.
export class PointsPanel {
  constructor({ container, store, selectionModel, onAddPoint }) {
    this.container = container;
    this.store = store;
    this.selectionModel = selectionModel;
    this.onAddPoint = onAddPoint;
    this.renamingId = null;

    this._buildStaticLayout();
    store.on('point:added', () => this.render());
    store.on('point:removed', () => this.render());
    store.on('point:updated', () => this.render());
    selectionModel.on('changed', () => this.render());

    this.render();
  }

  _buildStaticLayout() {
    const { bodyEl } = createCollapsibleSection({
      container: this.container,
      title: 'Pontos (P-points)',
      defaultExpanded: false
    });
    this.container = bodyEl;
    this.container.innerHTML = `
      <button id="add-point-btn" class="add-entity-btn full-add-btn">+ Adicionar ponto</button>
      <ul id="points-tree" class="entity-tree"></ul>
    `;
    this.treeEl = this.container.querySelector('#points-tree');
    this.container.querySelector('#add-point-btn').addEventListener('click', () => this.onAddPoint());
  }

  render() {
    renderEntityList({
      treeEl: this.treeEl,
      items: this.store.list(),
      isSelected: (id) => this.selectionModel.isSelected('ppoint', id),
      iconFor: (item) => `P${item.number}`,
      renamingId: this.renamingId,
      onSelect: (id) => this.selectionModel.select('ppoint', id),
      onStartRename: (id) => {
        this.renamingId = id;
        this.render();
      },
      onCommitRename: (id, value) => this._commitRename(id, value),
      onCancelRename: () => {
        this.renamingId = null;
        this.render();
      },
      onToggleVisible: (item) => this.store.updatePoint(item.id, { visible: !item.visible }),
      onDuplicate: (id) => {
        const copy = this.store.duplicatePoint(id);
        if (copy) this.selectionModel.select('ppoint', copy.id);
      },
      onDelete: (id) => this.store.removePoint(id),
      emptyMessage: 'Nenhum ponto na cena. Use "Adicionar ponto" para comecar.'
    });
  }

  _commitRename(id, value) {
    this.renamingId = null;
    const name = value.trim();
    if (name) {
      this.store.updatePoint(id, { name });
    } else {
      this.render();
    }
  }
}
