import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';
import { evaluateExpression } from '../utils/expressionEvaluator.js';

// Estrutura de dados de uma entrada de Dataset (DTSET/DATA do catalogo real -
// ver REFERENCIAS/172166728-Catalogues-and-Specifications-Reference-Manual.pdf,
// capitulo 8 "Creating Datasets in PARAGON", e o exemplo real em
// REFERENCIAS/SUPORTE_SDE-37-005.pmlmac (NEW DTSET /AGT_SDE-37-005-DTS).
//
// Um Dataset e uma colecao de elementos DATA que guardam propriedades do
// catalogo consultaveis pelo DESIGN/DRAFT. Cada DATA tem uma expressao
// (PPRO) que define seu valor "de bastidores" - o pulo do gato (capitulo 8.3
// "Real Properties") e que QUALQUER campo de expressao (dimensao, posicao,
// PCON/PBOR, distancia de PTAXI) pode referenciar uma entrada por um pseudo-
// atributo em vez de repetir a expressao: em vez de "PARAM 3" em varios
// lugares, usa-se "RPRO <dkey>" uma vez em cada lugar e "PARAM 3" so uma vez,
// dentro do PPRO daquela entrada - editar o Dataset muda todo mundo que
// referencia aquele dkey de uma vez so. Isso e o que da:
//   - "a geometria tem um parametro default" -> PPRO (pode ser so um
//     numero, ou referenciar PARAM n da variante ativa)
//   - "o usuario altera esse parametro" -> editar o Dataset (este painel)
//     muda o valor em todo lugar que usa aquele dkey, sem tocar a geometria
//
// Simplificacao deliberada: so o CAMINHO NUMERICO e suportado (RPRO sempre
// vira um numero na hora de resolver a expressao) - o catalogo real tambem
// permite PPRO em texto para uso fora de Pointset/Geomset (Q PROP), o que
// esta fora do escopo por enquanto. DPRO (valor padrao) so entra se PPRO
// estiver vazio ou nao resolver - ver DatasetStore.resolveDkey.
export function createDefaultDatasetEntryData(overrides = {}) {
  return {
    id: createId(),
    dkey: 'A', // DKEY - palavra que identifica esta entrada (usada em "RPRO <dkey>")
    ptyp: 'DIST', // PTYP - tipo da propriedade (DIST, BORE, TEXT, ANGL, DATA - livre, so documentacao)
    dtit: '', // DTIT - titulo/descricao exibido ao "projetista" (designer)
    // PPRO e DPRO sao expressoes (mesma regra de dimensao/posicao - ver
    // utils/expressionEvaluator.js): aceitam numero literal, "PARAM n",
    // aritmetica, ou ate outro "RPRO <dkey>" (uma unica camada de indirecao).
    ppro: '', // PPRO - expressao que define o valor
    dpro: '', // DPRO - valor padrao, usado se PPRO estiver vazio/nao resolver
    purp: 'DATA', // PURP - PARA (parametro de catalogo) | DESP (parametro de projetista) | DATA (generico)
    number: null, // NUMB - numero identificador adicional (ex.: o numero do PARAM/DESP correspondente)
    ...overrides
  };
}

// PPRO auto-gerado de uma entrada PURP=DESP (ver createDefaultDatasetEntryData
// acima e o comentario em ui/DatasetsPanel.js: `_applyPproDespHint`) -
// exportado daqui (em vez de so existir como `_despPproFor` na UI) pra
// `resolveDkey` conseguir detectar esse padrao especifico sem duplicar a
// formula, e pra UI/store nunca dessincronizarem sobre o que conta como
// "PPRO gerado" vs "PPRO digitado a mao".
export function despPproFor(number) {
  return number === null || number === undefined || number === '' ? '' : `ATTRIB DESP[${number} ]`;
}

export function isAutoGeneratedDespPpro(entry) {
  return entry.purp === 'DESP' && String(entry.ppro ?? '').trim() === despPproFor(entry.number);
}

export class DatasetStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  addEntry(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('dataset:added', data);
    return data;
  }

  updateEntry(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('dataset:updated', updated);
    return updated;
  }

  removeEntry(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('dataset:removed', id);
  }

  clear() {
    [...this.order].forEach((id) => this.removeEntry(id));
  }

  // Resolve "RPRO <dkey>" (ver utils/expressionEvaluator.js): devolve
  // `{ expr, error }` - a expressao a usar no lugar do token (PPRO, OU DPRO
  // se PPRO estiver vazio OU nao resolver pra um numero de verdade - decisao
  // explicita do usuario, confirmada contra o E3D real: uma entrada PURP=DESP
  // tem PPRO SEMPRE preenchido com o texto PML bruto gerado a partir de NUMB
  // - "ATTRIB DESP[n ]", ver ui/DatasetsPanel.js - que precisa ir pro DATAL
  // exportado tal como esta, mas NAO e uma expressao que este app consiga
  // calcular; nesse caso o app deve ignorar PPRO e usar DPRO, que fica sendo
  // o valor de PREVIEW de verdade), OU a mensagem de erro mais especifica
  // disponivel quando nada resolve. `resolveParam` (repassado por
  // utils/expressionEvaluator.js) e necessario pra TESTAR se PPRO resolve
  // (chama `evaluateExpression` nele mesmo, sem afetar/gravar nada).
  // `dkeyUpper` ja vem em maiusculas (DKEY nao diferencia caixa, igual
  // PARAM). BUG REAL evitado aqui: um retorno mais simples (so a string ou
  // uma string vazia gaenerica) perdia a mensagem de erro REAL do PPRO
  // quando ele existe mas nao resolve por um motivo especifico (ex.: PPRO=
  // "PARAM 3" sem variante ativa) - o chamador mostrava "Dataset X existe
  // mas nao tem PPRO nem DPRO preenchido", enganoso (PPRO ESTAVA preenchido,
  // so nao resolvia agora). Devolvendo `error` explicito, o chamador sempre
  // mostra o motivo mais especifico disponivel.
  //
  // CASO ESPECIAL (`isAutoGeneratedDespPpro`, ver acima - confirmado pelo
  // usuario contra REFERENCIAS/dataset1.pmlmac): uma entrada PURP=DESP com
  // DPRO vazio NAO E UM ERRO DE CONFIGURACAO - e um padrao legitimo e comum
  // no catalogo real (parametro so INFORMATIVO/documental, sem "valor
  // padrao" nenhum - o usuario confirmou: "nao possui valor default, embora
  // essa nao seja uma boa pratica... era feito assim no passado"). Sem essa
  // deteccao, o erro mostrado seria o retorno cru de `evaluateExpression`
  // tentando calcular o texto "ATTRIB DESP[n ]" (nunca foi pra ser
  // calculavel - vira algo tecnico tipo `Funcao desconhecida: "ATTRIB"`,
  // confuso e nao-acionavel). Mensagem clara em vez disso, propagada
  // automaticamente pra QUALQUER lugar que use "RPRO <dkey>" (posicao/
  // dimensao de primitiva ou P-point via utils/expressionEvaluator.js) - um
  // UNICO ponto de mudanca, sem duplicar por chamador.
  resolveDkey(dkeyUpper, resolveParam) {
    const entry = this.list().find((item) => item.dkey.trim().toUpperCase() === dkeyUpper);
    if (!entry) return { expr: null, error: `Dataset ${dkeyUpper} nao encontrado` };
    const ppro = String(entry.ppro ?? '').trim();
    const dpro = String(entry.dpro ?? '').trim();
    let pproError = null;
    if (ppro !== '') {
      const { error } = evaluateExpression(ppro, resolveParam);
      if (!error) return { expr: ppro, error: null };
      pproError = error;
    }
    if (dpro !== '') return { expr: dpro, error: null };
    if (isAutoGeneratedDespPpro(entry)) {
      return {
        expr: null,
        error: `Dataset ${dkeyUpper}: parametro informativo, preenchido pelo projetista no design real (sem valor padrao) - preencha o DPRO no painel Datasets se quiser um preview 3D aqui`
      };
    }
    return {
      expr: null,
      error: pproError
        ? `Dataset ${dkeyUpper}: ${pproError}`
        : `Dataset ${dkeyUpper} existe mas nao tem PPRO nem DPRO preenchido`
    };
  }
}
