import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Estrutura de dados central de um P-point (ponto geometrico de conexao) -
// ver REFERENCIAS/172166728-Catalogues-and-Specifications-Reference-Manual.pdf,
// capitulo 7.1 (3D Pointsets/PTSET) e capitulo 5.5 (exemplos de uso). O
// catalogo real tem 4 subtipos de P-point, cada um definindo posicao/direcao
// de um jeito diferente - `pointType` escolhe qual:
//   PTCAR (Cartesiano) - posicao explicita (PX/PY/PZ) + direcao via
//                        expressao de eixo estilo AVEVA/PTCDIR ("Y45X", "X",
//                        "Z30X" - ver utils/axisExpression.js)
//   PTAXI (Axial)      - posicao DERIVADA de um eixo (PAXI) + distancia ao
//                        longo dele (PDIS); a direcao e o proprio eixo
//   PTMIX (Misto)      - posicao explicita (PX/PY/PZ) como o Cartesiano, mas
//                        direcao restrita a um eixo (PAXI) como o Axial
//   PTPOS (Posicao)    - posicao/direcao definidas por expressoes PML livres
//                        (PTCPOS/PTCD); o app nao interpreta PML, entao esses
//                        2 campos ficam como texto livre/documentacao e a
//                        posicao/direcao reais no viewport usam PX/PY/PZ +
//                        rotacao livre (mesma UI do Cartesiano de antes) -
//                        simplificacao deliberada
//
// PTAXI/PTMIX/PTCAR usam TODOS o mesmo campo `axis` (expressao de eixo
// composta, ver utils/axisExpression.js) em vez de uma rotacao livre - no
// catalogo real, PTCDIR (do PTCAR) e PAXI (do PTAXI/PTMIX) sao a MESMA
// "Defining a Direction" do capitulo 5.5.8, so com nome de atributo
// diferente (ver persistence/DatalExporter.js: cada subtipo emite a palavra
// certa). A posicao/direcao derivadas sao calculadas so na hora de
// renderizar (objects/PPointObject.js), a partir de `axis`(/`distance` no
// caso do PTAXI), do mesmo jeito que dimensoes de primitiva sao resolvidas
// so na hora de construir a geometria - por isso os 3 guardam `rotation`
// tambem (fica sem uso: so o PTPOS ainda usa rotacao livre de verdade).
//
// P-points nao tem atributo de escala no catalogo real, entao nao ha `scale`
// aqui (main.js descarta qualquer `scale` vindo do TransformControls antes
// de aplicar o patch).
export function createDefaultPointData(overrides = {}) {
  return {
    id: createId(),
    name: 'Ponto P',
    pointType: 'PTCAR', // PTCAR | PTAXI | PTMIX | PTPOS
    number: 1, // NUMB - numero do P-point (identificacao/ordem de conectividade)
    // Posicao tambem e expressao (mesma regra de PCON/PBOR abaixo). Usada
    // por PTCAR/PTMIX/PTPOS - ignorada (derivada) em PTAXI.
    position: { x: '0', y: '0', z: '0' }, // PX/PY/PZ
    // graus; eixo Z local = direcao. Usada so por PTPOS (rotacao livre de
    // verdade) - ignorada (derivada de `axis`) em PTAXI/PTMIX/PTCAR.
    rotation: { x: 0, y: 0, z: 0 },
    axis: 'Y', // PAXI/PTCDIR - usado por PTAXI (posicao+direcao), PTMIX e PTCAR (so direcao). Default "Y" (ver manual, 5.5.5)
    distance: '0', // PDIS - distancia ao longo do eixo (expressao), usado so por PTAXI
    positionExpr: '', // PTCPOS - usado so por PTPOS (texto livre, nao interpretado)
    directionExpr: '', // PTCD - usado so por PTPOS (texto livre, nao interpretado)
    // PCON/PBOR sao STRINGs avaliadas por utils/expressionEvaluator.js: um
    // texto literal ('WELD') ou numero literal ('50') e so uma expressao
    // trivial; tambem aceitam referencia a parametro da variante ativa,
    // como "PARAM 3" (ver P-point real do REFERENCIAS/SUPORTE_SDE-37-005.pmlmac:
    // `PCON PARAM 3` / `PBOR PARAM 1`).
    connectionType: '', // PCON - tipo de conexao (ex.: WELD, SCRD, ou "PARAM 3")
    bore: '', // PBOR - diametro/bore do ponto (mm), opcional
    pskey: 'NULL', // PSKEY - condicao de extremidade p/ ISODRAFT (5.5.11 do manual)
    description: '', // DESC
    purpose: '', // PURP
    visible: true,
    locked: false,
    parameters: {}, // reservado para uso futuro
    ...overrides
  };
}

export class PointStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  // NUMB (numero do P-point) precisa ser unico na cena (identifica
  // conectividade no E3D) - usado por quem cria um ponto novo (main.js) e por
  // duplicatePoint abaixo, pra nunca repetir o numero de um ponto existente.
  nextAvailableNumber() {
    const numbers = this.list().map((p) => p.number);
    return numbers.length === 0 ? 1 : Math.max(...numbers) + 1;
  }

  addPoint(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('point:added', data);
    return data;
  }

  updatePoint(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('point:updated', updated);
    return updated;
  }

  removePoint(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('point:removed', id);
  }

  duplicatePoint(id) {
    const source = this.items.get(id);
    if (!source) return null;
    // Nasce na MESMA posicao do original (sem deslocar) - reposicionar fica a
    // cargo de quem modela.
    const copy = createDefaultPointData({
      ...structuredClone(source),
      id: createId(),
      // Sem espacos/parenteses: nomes no E3D nao aceitam esses caracteres.
      name: `${source.name}_copy`,
      number: this.nextAvailableNumber()
    });
    return this.addPoint(copy);
  }

  clear() {
    [...this.order].forEach((id) => this.removePoint(id));
  }
}
