// Processamento de pixel usado pela opcao "fundo branco transparente":
// converte branco em alpha (transparente) e qualquer outra cor em preto
// solido, preservando gradacoes (bordas suavizadas / anti-aliasing) como
// alpha parcial em vez de um corte binario.
export function loadImageElement(dataURL) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('Falha ao carregar imagem para processamento de textura.'));
    img.src = dataURL;
  });
}

export function applyWhiteAsAlpha(ctx, width, height) {
  const imageData = ctx.getImageData(0, 0, width, height);
  const d = imageData.data;
  for (let i = 0; i < d.length; i += 4) {
    const luminance = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
    const alpha = (255 - luminance) * (d[i + 3] / 255);
    d[i] = 0;
    d[i + 1] = 0;
    d[i + 2] = 0;
    d[i + 3] = alpha;
  }
  ctx.putImageData(imageData, 0, 0);
}
