import * as pdfjsLib from 'pdfjs-dist';
// Importando a URL do worker via Vite (`?url`) o arquivo e copiado para o bundle
// local durante o build, entao nao ha nenhuma dependencia de CDN em runtime.
import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';

pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;

const POINTS_TO_MM = 25.4 / 72;

export async function loadPdfDocument(file) {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  return pdf;
}

// Renderiza uma pagina do PDF em um canvas e devolve os dados prontos para
// virar a textura do plano, incluindo o tamanho real da pagina em mm.
export async function renderPdfPageToDataURL(pdf, pageNumber, renderScale = 2) {
  const page = await pdf.getPage(pageNumber);

  const baseViewport = page.getViewport({ scale: 1 });
  const widthMM = baseViewport.width * POINTS_TO_MM;
  const heightMM = baseViewport.height * POINTS_TO_MM;

  const viewport = page.getViewport({ scale: renderScale });
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(viewport.width);
  canvas.height = Math.ceil(viewport.height);
  const ctx = canvas.getContext('2d');

  await page.render({ canvasContext: ctx, viewport }).promise;

  return {
    dataURL: canvas.toDataURL('image/png'),
    pixelWidth: canvas.width,
    pixelHeight: canvas.height,
    widthMM,
    heightMM
  };
}
