import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import {
  POINT_MARKER_BASE_ARROW_LENGTH,
  POINT_MARKER_SCREEN_FRACTION,
  POINT_MARKER_MIN_SCALE,
  POINT_MARKER_MAX_SCALE
} from '../utils/pointMarkerSize.js';
import {
  COTA_LABEL_BASE_WIDTH,
  COTA_LABEL_SCREEN_FRACTION,
  COTA_LABEL_MIN_SCALE,
  COTA_LABEL_MAX_SCALE,
  COTA_POINT_MARKER_BASE_RADIUS,
  COTA_POINT_MARKER_SCREEN_FRACTION
} from '../utils/cotaLabelSize.js';
import { SNAP_MARKER_MIN_SCALE, SNAP_MARKER_MAX_SCALE } from '../utils/snapMarkerSize.js';

// Vistas padrao (mundo Z-up): `dir` e a direcao do alvo ate a camera (a
// camera fica em target + dir*raio, olhando para -dir); `up` e o vetor
// "para cima" na tela nessa vista. Em Topo/Baixo, `dir` e paralelo ao eixo Z
// (mundo), entao nao da pra usar Z como `up` (THREE.Matrix4.lookAt fica
// degenerado) - usamos Y (Norte) como "para cima" so nessas duas vistas.
const WORLD_UP = new THREE.Vector3(0, 0, 1);
const NORTH_UP = new THREE.Vector3(0, 1, 0);

const NAMED_VIEWS = {
  front: { dir: new THREE.Vector3(0, -1, 0), up: WORLD_UP },
  back: { dir: new THREE.Vector3(0, 1, 0), up: WORLD_UP },
  right: { dir: new THREE.Vector3(1, 0, 0), up: WORLD_UP },
  left: { dir: new THREE.Vector3(-1, 0, 0), up: WORLD_UP },
  top: { dir: new THREE.Vector3(0, 0, 1), up: NORTH_UP },
  bottom: { dir: new THREE.Vector3(0, 0, -1), up: NORTH_UP }
};

// As 4 vistas isometricas (um canto de cada vez) - o botao "Isometrica" da
// barra de ferramentas e o handle "ISO" do gizmo alternam entre elas a cada
// clique (ver goToView('iso') abaixo).
const ISO_VIEWS = [
  new THREE.Vector3(1, -1, 1).normalize(),
  new THREE.Vector3(-1, -1, 1).normalize(),
  new THREE.Vector3(-1, 1, 1).normalize(),
  new THREE.Vector3(1, 1, 1).normalize()
];

const VIEW_ANIMATION_DURATION = 0.45; // segundos

// Fundo em degrade (azul claro no topo, azul escuro na base). Como e um
// THREE.Texture (nao um CubeTexture), o three.js o desenha preenchendo a
// tela toda em espaco de tela - o degrade fica sempre fixo verticalmente,
// independente de para onde a camera esta olhando.
function createSkyGradientTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 2;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0, '#bfe3f7'); // azul claro (topo)
  gradient.addColorStop(1, '#0b2947'); // azul escuro (base)
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

// Responsavel apenas pela infraestrutura da cena 3D: camera, renderer, grid,
// eixos, gizmo de orientacao e o loop de renderizacao. Nao conhece nada sobre
// o modelo de dados das referencias.
export class SceneManager {
  constructor(container) {
    this.container = container;

    this.scene = new THREE.Scene();
    this.scene.background = createSkyGradientTexture();

    // Camera ortografica (sem perspectiva/distorcao), como nos viewports de
    // CAD/E3D - linhas paralelas continuam paralelas na tela, o que facilita
    // interpretar desenhos tecnicos. `viewSize` e a metade da altura visivel
    // (em mm) no zoom padrao; o frustum esquerda/direita/cima/baixo e
    // recalculado em handleResize() para acompanhar a proporcao do viewport.
    this.viewSize = 2500;
    this.camera = new THREE.OrthographicCamera(-this.viewSize, this.viewSize, this.viewSize, -this.viewSize, 0.1, 100000);
    // Convencao CAD/E3D (SolidWorks, CATIA, AVEVA): Z e o eixo vertical, nao Y
    // (o padrao do three.js). Precisa ser definido antes do OrbitControls,
    // que le camera.up na construcao para orbitar em torno do eixo certo.
    this.camera.up.set(0, 0, 1);
    this.camera.position.set(1800, 1800, 1400);

    this.renderer = new THREE.WebGLRenderer({ antialias: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(this.renderer.domElement);

    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.target.set(0, 0, 0);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.08;
    // Convencao pedida: esquerdo so seleciona (SelectionManager cuida disso
    // de forma independente - aqui so precisamos TIRAR o botao esquerdo do
    // OrbitControls, senao um arrasto com ele orbitaria a camera ao mesmo
    // tempo que o SelectionManager decide se foi clique ou arrasto). Meio =
    // rotacionar (orbita), direito = pan. A roda do mouse continua dando
    // zoom independente disso (evento de wheel separado, nao passa por
    // `mouseButtons`).
    this.controls.mouseButtons = {
      LEFT: null,
      MIDDLE: THREE.MOUSE.ROTATE,
      RIGHT: THREE.MOUSE.PAN
    };
    this.controls.update();

    this.planesGroup = new THREE.Group();
    this.planesGroup.name = 'reference-planes';
    this.scene.add(this.planesGroup);

    this.primitivesGroup = new THREE.Group();
    this.primitivesGroup.name = 'primitives';
    this.scene.add(this.primitivesGroup);

    this.pointsGroup = new THREE.Group();
    this.pointsGroup.name = 'points';
    this.scene.add(this.pointsGroup);

    this.cotasGroup = new THREE.Group();
    this.cotasGroup.name = 'cotas';
    this.scene.add(this.cotasGroup);

    // Marcadores de hover/confirmado da ferramenta de Cota (ver
    // core/CotaPickTool.js) vivem aqui, nao soltos na scene, pra poderem ser
    // reescalados junto no loop de renderizacao (ver _syncPickMarkerScale).
    this.pickMarkersGroup = new THREE.Group();
    this.pickMarkersGroup.name = 'cota-pick-markers';
    this.scene.add(this.pickMarkersGroup);

    this._setupLights();
    this._setupGrid();
    this._setupGizmo();

    this._resizeObserver = new ResizeObserver(() => this.handleResize());
    this._resizeObserver.observe(container);
    this.handleResize();

    // Estado da animacao de troca de vista (ver goToView/_updateViewAnimation)
    // e do ciclo das 4 isometricas.
    this._clock = new THREE.Clock();
    this._viewAnimation = null;
    this._isoIndex = -1;

    this.renderer.setAnimationLoop(() => this._renderFrame());
  }

  // Anima a camera ate a vista nomeada ('front'/'back'/'left'/'right'/'top'/
  // 'bottom') ou 'iso' (alterna entre as 4 vistas isometricas a cada
  // chamada). Mantem a distancia atual ate o alvo (nao mexe no zoom),
  // so reorienta a camera - o mesmo mecanismo usado pelo gizmo clicavel
  // no canto do viewport (ver _setupGizmo).
  goToView(name) {
    if (name === 'iso') {
      this._isoIndex = (this._isoIndex + 1) % ISO_VIEWS.length;
      this._animateToDirection(ISO_VIEWS[this._isoIndex], WORLD_UP);
      return;
    }
    const preset = NAMED_VIEWS[name];
    if (!preset) return;
    this._isoIndex = -1; // fora do ciclo de isometricas ate o usuario clicar em "Isometrica" de novo
    this._animateToDirection(preset.dir, preset.up);
  }

  _animateToDirection(dir, up) {
    const target = this.controls.target;
    const radius = this.camera.position.distanceTo(target) || this.viewSize * 1.2;
    const eye = target.clone().addScaledVector(dir, radius);
    const lookMatrix = new THREE.Matrix4().lookAt(eye, target, up);

    this._viewAnimation = {
      fromQuat: this.camera.quaternion.clone(),
      toQuat: new THREE.Quaternion().setFromRotationMatrix(lookMatrix),
      target: target.clone(),
      radius,
      elapsed: 0
    };
    this.controls.enabled = false;
  }

  _updateViewAnimation(delta) {
    const anim = this._viewAnimation;
    anim.elapsed += delta;
    const t = Math.min(anim.elapsed / VIEW_ANIMATION_DURATION, 1);
    const eased = t * t * (3 - 2 * t); // smoothstep: comeca/termina suave
    this.camera.quaternion.slerpQuaternions(anim.fromQuat, anim.toQuat, eased);
    // Mantem a camera na esfera de raio `radius` ao redor do alvo: o eixo Z
    // local da camera aponta para o observador, entao essa e a posicao
    // correta para qualquer orientacao (nao depende da convencao de up).
    this.camera.position
      .set(0, 0, 1)
      .applyQuaternion(this.camera.quaternion)
      .multiplyScalar(anim.radius)
      .add(anim.target);

    if (t >= 1) {
      this._viewAnimation = null;
      this.controls.enabled = true;
    }
  }

  _setupLights() {
    // Os planos de referencia usam MeshBasicMaterial (nao depende de luz),
    // mas as primitivas (Caixa/Cilindro) usam MeshStandardMaterial para dar
    // volume/sombreamento real aos solidos - por isso ha luz direcional
    // alem da ambiente (so ambiente deixaria os solidos com aparencia chapada).
    this.scene.add(new THREE.AmbientLight(0xffffff, 0.6));

    const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
    keyLight.position.set(1200, -800, 2000);
    this.scene.add(keyLight);

    const fillLight = new THREE.DirectionalLight(0xffffff, 0.4);
    fillLight.position.set(-1000, 1200, 800);
    this.scene.add(fillLight);
  }

  _setupGrid() {
    // Tons de azul-acinzentado escolhidos para manter contraste tanto contra
    // o azul claro do topo do degrade quanto contra o azul escuro da base.
    this.grid = new THREE.GridHelper(10000, 100, 0x6f8fab, 0x3d5670);
    this.grid.visible = false; // desativado por padrao
    // GridHelper nasce deitado no plano XZ (convencao Y-up do three.js);
    // giramos 90 graus em X para deitar no plano XY (chao no mundo Z-up).
    this.grid.rotation.x = Math.PI / 2;
    this.scene.add(this.grid);

    const axes = new THREE.AxesHelper(1500);
    this.scene.add(axes);
  }

  setGridVisible(visible) {
    this.grid.visible = visible;
  }

  isGridVisible() {
    return this.grid.visible;
  }

  _setupGizmo() {
    // Mini eixo no canto do viewport, sincronizado com a orientacao da
    // camera - alem de indicador, os 6 discos nas pontas dos eixos sao
    // clicaveis e trocam a vista (mesmo destino das vistas nomeadas de
    // goToView), como um "view cube" simplificado.
    this.gizmoScene = new THREE.Scene();
    this.gizmoCamera = new THREE.OrthographicCamera(-2, 2, 2, -2, 0.1, 10);
    this.gizmoCamera.position.set(0, 0, 4);
    this.gizmoScene.add(new THREE.AxesHelper(1.4));
    this.gizmoSize = 100;
    this.gizmoPadding = 12;

    const specs = [
      { dir: new THREE.Vector3(0, -1, 0), color: '#5fb85f', label: 'FR', view: 'front' },
      { dir: new THREE.Vector3(0, 1, 0), color: '#5fb85f', label: 'TR', view: 'back', dim: true },
      { dir: new THREE.Vector3(1, 0, 0), color: '#d9584f', label: 'DI', view: 'right' },
      { dir: new THREE.Vector3(-1, 0, 0), color: '#d9584f', label: 'ES', view: 'left', dim: true },
      { dir: new THREE.Vector3(0, 0, 1), color: '#4a90d9', label: 'TO', view: 'top' },
      { dir: new THREE.Vector3(0, 0, -1), color: '#4a90d9', label: 'BX', view: 'bottom', dim: true }
    ];

    this._gizmoHandles = specs.map((spec) => {
      const sprite = new THREE.Sprite(this._createGizmoHandleMaterial(spec.color, spec.label, spec.dim));
      sprite.position.copy(spec.dir).multiplyScalar(1.7);
      sprite.scale.setScalar(0.62);
      sprite.userData.view = spec.view;
      this.gizmoScene.add(sprite);
      return sprite;
    });

    this._gizmoRaycaster = new THREE.Raycaster();
    this._gizmoPointer = new THREE.Vector2();
    this._gizmoDownInside = false;
    this._gizmoDownPos = null;

    // Listeners em fase de captura: se o clique comecar dentro do quadrado
    // do gizmo, paramos a propagacao para que o OrbitControls (orbita) e o
    // SelectionManager (selecao por clique) nunca vejam esse gesto.
    this.renderer.domElement.addEventListener('pointerdown', this._onGizmoPointerDown, true);
    this.renderer.domElement.addEventListener('pointerup', this._onGizmoPointerUp, true);
  }

  _createGizmoHandleMaterial(color, label, dim) {
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');
    ctx.beginPath();
    ctx.arc(32, 32, dim ? 20 : 24, 0, Math.PI * 2);
    ctx.globalAlpha = dim ? 0.45 : 0.95;
    ctx.fillStyle = color;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = dim ? 'rgba(255,255,255,0.85)' : '#0b1a26';
    ctx.font = 'bold 20px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, 32, 34);

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return new THREE.SpriteMaterial({ map: texture, toneMapped: false });
  }

  _isInsideGizmoBox(clientX, clientY) {
    const rect = this.renderer.domElement.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    return x >= this.gizmoPadding && x <= this.gizmoPadding + this.gizmoSize && y >= this.gizmoPadding && y <= this.gizmoPadding + this.gizmoSize;
  }

  _onGizmoPointerDown = (event) => {
    if (event.button !== 0 || !this._isInsideGizmoBox(event.clientX, event.clientY)) {
      this._gizmoDownInside = false;
      return;
    }
    this._gizmoDownInside = true;
    this._gizmoDownPos = { x: event.clientX, y: event.clientY };
    event.stopPropagation();
  };

  _onGizmoPointerUp = (event) => {
    if (!this._gizmoDownInside) return;
    event.stopPropagation();
    this._gizmoDownInside = false;

    const dx = event.clientX - this._gizmoDownPos.x;
    const dy = event.clientY - this._gizmoDownPos.y;
    if (Math.hypot(dx, dy) > 5) return; // foi um arrasto dentro do gizmo, nao um clique

    const rect = this.renderer.domElement.getBoundingClientRect();
    const x = event.clientX - rect.left - this.gizmoPadding;
    const y = event.clientY - rect.top - this.gizmoPadding;
    this._gizmoPointer.x = (x / this.gizmoSize) * 2 - 1;
    this._gizmoPointer.y = -(y / this.gizmoSize) * 2 + 1;

    this._gizmoRaycaster.setFromCamera(this._gizmoPointer, this.gizmoCamera);
    const hit = this._gizmoRaycaster.intersectObjects(this._gizmoHandles)[0];
    if (hit) this.goToView(hit.object.userData.view);
  };

  handleResize() {
    const width = this.container.clientWidth || 1;
    const height = this.container.clientHeight || 1;
    const aspect = width / height;
    this.camera.left = -this.viewSize * aspect;
    this.camera.right = this.viewSize * aspect;
    this.camera.top = this.viewSize;
    this.camera.bottom = -this.viewSize;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height);
  }

  add(object3d) {
    this.planesGroup.add(object3d);
  }

  remove(object3d) {
    this.planesGroup.remove(object3d);
  }

  addPrimitive(object3d) {
    this.primitivesGroup.add(object3d);
  }

  removePrimitive(object3d) {
    this.primitivesGroup.remove(object3d);
  }

  addPoint(object3d) {
    this.pointsGroup.add(object3d);
  }

  removePoint(object3d) {
    this.pointsGroup.remove(object3d);
  }

  addCota(object3d) {
    this.cotasGroup.add(object3d);
  }

  removeCota(object3d) {
    this.cotasGroup.remove(object3d);
  }

  // Posicao + zoom (distancia/tamanho visivel) + target (pra onde o
  // OrbitControls orbita, ou seja, pra onde a camera "esta olhando") - o
  // suficiente pra reconstruir o enquadramento exato ao salvar/carregar uma
  // cena. Rotacao/orientacao da camera fica implicita na posicao+target (uma
  // camera sempre olha pro target via OrbitControls, entao nao precisa
  // salvar quaternion/up separado).
  getCameraState() {
    return {
      position: { x: this.camera.position.x, y: this.camera.position.y, z: this.camera.position.z },
      target: { x: this.controls.target.x, y: this.controls.target.y, z: this.controls.target.z },
      zoom: this.camera.zoom
    };
  }

  setCameraState(state) {
    if (!state) return;
    if (state.position) this.camera.position.set(state.position.x, state.position.y, state.position.z);
    if (state.target) this.controls.target.set(state.target.x, state.target.y, state.target.z);
    if (typeof state.zoom === 'number' && state.zoom > 0) this.camera.zoom = state.zoom;
    this.camera.updateProjectionMatrix();
    this.controls.update();
  }

  _renderFrame() {
    const delta = this._clock.getDelta();
    if (this._viewAnimation) this._updateViewAnimation(delta);
    this.controls.update();
    this._syncPointMarkerScale();
    this._syncCotaScale();
    this._syncPickMarkerScale();
    this.renderer.render(this.scene, this.camera);
    this._renderGizmo();
  }

  // Fator de escala pra um elemento construido num "tamanho de projeto"
  // (baseSize, na escala 1) que deve ocupar sempre a mesma FRACAO da altura
  // visivel do viewport ortografico atual (que muda com o zoom) - como um
  // gizmo de CAD, nao como o tamanho real de uma peca. minScale/maxScale sao
  // so limite de seguranca contra estados degenerados de camera (zoom
  // extremo), nao o mecanismo principal de dimensionamento.
  _viewportScale(baseSize, screenFraction, minScale, maxScale) {
    const visibleHeight = (this.camera.top - this.camera.bottom) / this.camera.zoom;
    return THREE.MathUtils.clamp((visibleHeight * screenFraction) / baseSize, minScale, maxScale);
  }

  // P-points sao construidos num tamanho fixo em mm (ver
  // objects/PPointObject.js + utils/pointMarkerSize.js), o que fica enorme
  // perto de pecas pequenas e minusculo perto de desenhos grandes. Aqui a
  // escala do mesh e recalculada a cada frame para o marcador manter um
  // tamanho de tela aproximadamente constante.
  _syncPointMarkerScale() {
    if (this.pointsGroup.children.length === 0) return;
    const scale = this._viewportScale(
      POINT_MARKER_BASE_ARROW_LENGTH,
      POINT_MARKER_SCREEN_FRACTION,
      POINT_MARKER_MIN_SCALE,
      POINT_MARKER_MAX_SCALE
    );
    this.pointsGroup.children.forEach((mesh) => mesh.scale.setScalar(scale));
  }

  // Mesma ideia de _syncPointMarkerScale, mas pro rotulo de texto e pros
  // marcadores das 2 pontas de cada Cota (ver objects/CotaObject.js) - NAO
  // escala o grupo inteiro, porque a linha da Cota usa coordenadas de MUNDO
  // reais nos seus vertices (as 2 pontas medidas); escalar o grupo
  // distorceria a linha pra longe da posicao certa. So os filhos "cota-label"
  // /"cota-point-a"/"cota-point-b" sao escalados individualmente.
  _syncCotaScale() {
    if (this.cotasGroup.children.length === 0) return;
    const labelScale = this._viewportScale(
      COTA_LABEL_BASE_WIDTH,
      COTA_LABEL_SCREEN_FRACTION,
      COTA_LABEL_MIN_SCALE,
      COTA_LABEL_MAX_SCALE
    );
    const markerScale = this._viewportScale(
      COTA_POINT_MARKER_BASE_RADIUS,
      COTA_POINT_MARKER_SCREEN_FRACTION,
      COTA_LABEL_MIN_SCALE,
      COTA_LABEL_MAX_SCALE
    );
    this.cotasGroup.children.forEach((group) => {
      const sprite = group.getObjectByName('cota-label');
      if (sprite) sprite.scale.set(COTA_LABEL_BASE_WIDTH * labelScale, COTA_LABEL_BASE_WIDTH * (72 / 256) * labelScale, 1);
      const pointA = group.getObjectByName('cota-point-a');
      if (pointA) pointA.scale.setScalar(markerScale);
      const pointB = group.getObjectByName('cota-point-b');
      if (pointB) pointB.scale.setScalar(markerScale);
    });
  }

  // Marcadores de hover/confirmado da ferramenta de Cota (ver
  // core/CotaPickTool.js) - cada um guarda seu proprio raio/fracao de projeto
  // em userData porque hover e confirmado tem tamanhos-alvo diferentes (ver
  // utils/snapMarkerSize.js).
  _syncPickMarkerScale() {
    if (this.pickMarkersGroup.children.length === 0) return;
    this.pickMarkersGroup.children.forEach((mesh) => {
      const { baseRadius, screenFraction } = mesh.userData;
      mesh.scale.setScalar(this._viewportScale(baseRadius, screenFraction, SNAP_MARKER_MIN_SCALE, SNAP_MARKER_MAX_SCALE));
    });
  }

  _renderGizmo() {
    const dir = this.camera.position.clone().sub(this.controls.target).normalize();
    this.gizmoCamera.position.copy(dir.multiplyScalar(4));
    this.gizmoCamera.up.copy(this.camera.up);
    this.gizmoCamera.lookAt(0, 0, 0);

    const size = this.gizmoSize;
    const padding = this.gizmoPadding;
    const height = this.container.clientHeight;

    this.renderer.setScissorTest(true);
    this.renderer.setViewport(padding, height - size - padding, size, size);
    this.renderer.setScissor(padding, height - size - padding, size, size);
    // So limpa o depth (nao a cor) nesse cantinho, para o gizmo desenhar por
    // cima do conteudo ja renderizado da cena principal em vez de um fundo preto.
    this.renderer.autoClearColor = false;
    this.renderer.render(this.gizmoScene, this.gizmoCamera);
    this.renderer.autoClearColor = true;
    this.renderer.setScissorTest(false);
    this.renderer.setViewport(0, 0, this.container.clientWidth, height);
  }
}
