import * as THREE from 'three';
import { DEG2RAD } from '../utils/transformMath.js';
import { evaluateExpression, resolveNumber } from '../utils/expressionEvaluator.js';
import { resolveAxisExpression } from '../utils/axisExpression.js';
import { isNegativePrimitiveType } from '../core/PrimitiveStore.js';

const MIN_DIMENSION = 1; // mm - evita geometria de tamanho zero/negativo/invalido
const RADIAL_SEGMENTS = 32; // resolucao das primitivas de revolucao (cilindro/cone/esfera/disco/snout/toro)

// Elemento NEGATIVO (ver core/PrimitiveStore.js: NEGATIVE_PRIMITIVE_TYPES) -
// tem EXATAMENTE os mesmos atributos/geometria do positivo correspondente
// (capitulo 7.5 do manual), entao buildGeometry/resolvePrimitiveOrigin so
// precisam tratar cada negativo como o positivo equivalente pra tudo que nao
// seja aparencia/hierarquia (ver createPrimitiveMesh).
const NEGATIVE_TO_POSITIVE_TYPE = { negBox: 'box', negCylinder: 'cylinder', negPyramid: 'pyramid' };
function basePositiveType(type) {
  return NEGATIVE_TO_POSITIVE_TYPE[type] ?? type;
}

// Cada dimensao e uma expressao (ver utils/expressionEvaluator.js) - pode ser
// um numero literal ou referenciar um parametro da variante ativa, como
// "PARAM 12". Se nao resolver para um numero >= `min` (parametro inexistente,
// variante ativa nao definida, erro de sintaxe), cai para `min` em vez de
// gerar uma geometria invalida. `min: 0` e usado pelas dimensoes de topo da
// piramide, onde zero e um valor legitimo (piramide "de ponta").
export function resolveDimension(raw, resolveParam, min = MIN_DIMENSION) {
  const { value, isNumber } = evaluateExpression(raw, resolveParam);
  return isNumber && value >= min ? value : min;
}

// Cada primitiva "de revolucao" do three.js (Cylinder/Cone/Sphere) nasce com
// o eixo ao longo de Y; giramos 90 graus em X para o eixo ficar em Z (mundo
// Z-up, convencao CAD/E3D), assim uma primitiva nova ja nasce "de pe" com
// rotacao (0,0,0).
function rotateAxisToZ(geometry) {
  geometry.rotateX(Math.PI / 2);
  return geometry;
}

// Resolve a lista de vertices (SVER: PX/PY/PRAD) de uma extrusao contra a
// variante ativa - cada campo e uma expressao independente (ver
// core/PrimitiveStore.js). Raio negativo nao faz sentido, entao cai pra 0.
export function resolveVertices(vertices, resolveParam) {
  return (vertices ?? []).map((v) => ({
    x: resolveNumber(v.x, resolveParam),
    y: resolveNumber(v.y, resolveParam),
    radius: Math.max(0, resolveNumber(v.radius, resolveParam))
  }));
}

const DEFAULT_AXIS_A = new THREE.Vector3(0, 1, 0); // Y
const DEFAULT_AXIS_B = new THREE.Vector3(0, 0, 1); // Z

// Resolve PAAX/PBAX (eixos locais do plano do SLOO de uma extrusao - ver
// capitulo 7.4.17 do manual e core/PrimitiveStore.js) pros vetores de base
// {axisA, axisB, normal}. `normal` (eixo de extrusao) = axisA x axisB - se
// os dois nao forem exatamente perpendiculares, PX/PY dos vertices ficam
// levemente "cisalhados" em vez de travar (o aviso de nao-perpendicular fica
// so na UI, ver PropertiesPanel.js). Se a expressao for invalida OU os 2
// eixos derem paralelos (produto vetorial degenerado - normal indefinida),
// cai pro padrao PAAX=Y/PBAX=Z do PARAGON real.
//
// `originPoint` = a posicao do P-point referenciado por PAAX ou PBAX (via
// "PP n" - ver utils/axisExpression.js), se algum dos dois for uma
// referencia desse tipo; PAAX tem prioridade se os dois forem (e o eixo
// principal, primeiro campo da UI). null se nenhum dos dois referenciar um
// P-point - usado por resolvePrimitiveOrigin abaixo.
export function resolveExtrusionBasis(data) {
  const resolvedA = resolveAxisExpression(data.axisA);
  const resolvedB = resolveAxisExpression(data.axisB);
  const axisA = resolvedA.direction ?? DEFAULT_AXIS_A.clone();
  const axisB = resolvedB.direction ?? DEFAULT_AXIS_B.clone();
  const originPoint = resolvedA.origin ?? resolvedB.origin ?? null;

  const normal = new THREE.Vector3().crossVectors(axisA, axisB);
  if (normal.lengthSq() < 1e-8) {
    // eixos paralelos (ou um deles invalido de um jeito que colapsou) - sem
    // isso a extrusao viraria uma geometria degenerada (altura zero em
    // qualquer direcao) - volta pro padrao de fabrica inteiro.
    return {
      axisA: DEFAULT_AXIS_A.clone(),
      axisB: DEFAULT_AXIS_B.clone(),
      normal: new THREE.Vector3(1, 0, 0),
      originPoint
    };
  }
  return { axisA, axisB, normal: normal.normalize(), originPoint };
}

const DEFAULT_SINGLE_AXIS = new THREE.Vector3(0, 0, 1); // Z - PAXI padrao ("de pe")

// Resolve PAXI (eixo UNICO de orientacao - ver core/PrimitiveStore.js) pro
// vetor direcao + a rotacao (THREE.Quaternion) que leva o Z "de fabrica"
// (ver rotateAxisToZ) ate esse eixo. Compartilhado por cilindro e cone: ao
// contrario da extrusao (2 eixos, PAAX/PBAX - ver resolveExtrusionBasis),
// as duas sao formas de revolucao rotacionalmente simetricas ao redor do
// proprio eixo, entao um segundo eixo nao faria diferenca visual nenhuma.
// `quat` e reaproveitada tanto por buildGeometry (orienta a geometria de
// verdade) quanto por SnapPoints.js (pontos "quadrante" - precisam da MESMA
// rotacao pra conferir com a geometria real). `originPoint`: posicao do
// P-point referenciado via "PP n" (ver utils/axisExpression.js), se houver -
// mesma ideia do PAAX/PBAX da extrusao, so que aqui e o UNICO jeito de
// posicionar o solido no mundo (ver resolveCylinderOrigin/resolveConeOrigin:
// nenhum dos dois tem PX/PY/PZ livre).
export function resolveSingleAxis(data) {
  const { direction, origin } = resolveAxisExpression(data.axis);
  const axis = direction ?? DEFAULT_SINGLE_AXIS.clone();
  const quat = new THREE.Quaternion().setFromUnitVectors(DEFAULT_SINGLE_AXIS, axis);
  return { axis, quat, originPoint: origin ?? null };
}

// Posicao "de mundo" da BASE de um cilindro. Igual a um P-point PTAXI (ver
// objects/PPointObject.resolvePointPosition) - SCYL nao tem PX/PY/PZ livre
// no catalogo real, so PAXI (eixo) + PDIS (distancia ate a base): a base
// fica a `distance` mm de origem, medida AO LONGO do proprio eixo. Sem
// P-point referenciado em PAXI, origem = 0,0,0 do mundo (mesmo padrao do
// PTAXI); com referencia ("PP n"), origem = posicao desse P-point. Vale
// IGUAL pra um elemento negativo (`parentId` setado) - ver comentario em
// resolvePrimitiveOrigin sobre `parentId` ser so vinculo organizacional, sem
// afetar esta conta.
export function resolveCylinderOrigin(data, resolveParam) {
  const { axis, originPoint } = resolveSingleAxis(data);
  const distance = resolveNumber(data.distance, resolveParam);
  const base = originPoint ? originPoint : new THREE.Vector3(0, 0, 0);
  return base.clone().addScaledVector(axis, distance);
}

// Posicao "de mundo" da BASE de um cone. Ao contrario do cilindro, SCON nao
// tem um PDIS separado de offset - a base fica SEMPRE exatamente na origem
// (ou no P-point referenciado por PAXI, se houver): `dimensions.height` ja
// e o proprio PDIS do catalogo real (distancia da base ate o apice - ver o
// case 'cone' de buildGeometry), nao uma posicao.
export function resolveConeOrigin(data) {
  const { originPoint } = resolveSingleAxis(data);
  return originPoint ? originPoint.clone() : new THREE.Vector3(0, 0, 0);
}

const DEFAULT_AXIS_X = new THREE.Vector3(1, 0, 0);
const DEFAULT_AXIS_Y = new THREE.Vector3(0, 1, 0);
const DEFAULT_AXIS_Z = new THREE.Vector3(0, 0, 1);

// Resolve PBAX/PCAX/PAAX (os 3 eixos LOCAIS de uma piramide/tronco - ver
// core/PrimitiveStore.js). NAO sao 3 vetores livres, mesmo cada um tendo seu
// proprio campo/botao PPnt na UI: o manual (cap. 7.4.11) e explicito - "PBAX,
// PCAX - the directions of the two axes perpendicular to the A axis AND
// mutually perpendicular" - PAAX (a "normal ao topo/base") e SEMPRE
// perpendicular as 2 faces por definicao, entao PBAX/PCAX sao
// ORTOGONALIZADOS contra ele (Gram-Schmidt), nunca usados crus - confirmado
// pelo usuario contra o E3D de verdade (as faces ficam perpendiculares ao
// eixo A mesmo quando PBAX/PCAX digitados nao seriam perpendiculares por
// conta propria).
//
// Algoritmo: PAAX fica como veio (autoritativo - e o "pra onde a piramide
// aponta"); PBAX e projetado pra ficar exatamente perpendicular a PAAX
// (mantendo o mais perto possivel da direcao digitada); PCAX e DERIVADO
// (PAAX x PBAX-ortogonalizado, que ja garante perpendicular aos 2 por
// construcao) - o valor digitado em PCAX so decide o SINAL/lateralidade
// (se o produto vetorial bateu ou nao com a direcao pretendida), nunca a
// direcao exata (senao nao daria pra garantir os 3 mutuamente
// perpendiculares a partir de 2 correcoes independentes).
// `originPoint`: posicao do P-point referenciado por QUALQUER um dos 3 (via
// "P n" - ver utils/axisExpression.js), com prioridade X > Y > Z (ordem dos
// campos na UI) - ver resolvePyramidOrigin.
export function resolvePyramidBasis(data) {
  const resolvedX = resolveAxisExpression(data.axisX);
  const resolvedY = resolveAxisExpression(data.axisY);
  const resolvedZ = resolveAxisExpression(data.axisZ);
  const rawX = resolvedX.direction ?? DEFAULT_AXIS_X.clone();
  const rawY = resolvedY.direction ?? DEFAULT_AXIS_Y.clone();
  const axisZ = (resolvedZ.direction ?? DEFAULT_AXIS_Z.clone()).normalize();
  const originPoint = resolvedX.origin ?? resolvedY.origin ?? resolvedZ.origin ?? null;

  // Gram-Schmidt: tira de rawX a componente ao longo de axisZ, sobra so a
  // parte perpendicular. Se rawX for (quase) paralelo a axisZ, nao da pra
  // derivar um B perpendicular dali (direcao indefinida) - cai pro padrao
  // X/Y/Z de fabrica.
  const axisX = rawX.clone().addScaledVector(axisZ, -rawX.dot(axisZ));
  if (axisX.lengthSq() < 1e-8) {
    return { axisX: DEFAULT_AXIS_X.clone(), axisY: DEFAULT_AXIS_Y.clone(), axisZ: DEFAULT_AXIS_Z.clone(), originPoint };
  }
  axisX.normalize();

  const axisY = new THREE.Vector3().crossVectors(axisZ, axisX);
  if (axisY.dot(rawY) < 0) axisY.negate(); // mantem a lateralidade que o usuario pretendia em PCAX

  return { axisX, axisY, axisZ, originPoint };
}

// Posicao "de mundo" da origem de uma piramide. Igual ao cone (ver
// resolveConeOrigin) - LPYR tambem nao tem PX/PY/PZ livre: PBDI/PTDI/
// PBOF/PCOF (ver buildGeometry) ja posicionam as 2 faces RELATIVAS a essa
// origem, entao ela nao precisa (nem tem como) ganhar um deslocamento extra.
export function resolvePyramidOrigin(data) {
  const { originPoint } = resolvePyramidBasis(data);
  return originPoint ? originPoint.clone() : new THREE.Vector3(0, 0, 0);
}

// Posicao "de mundo" da origem de um snout. Mesma ideia do cone/piramide
// (ver resolveConeOrigin/resolvePyramidOrigin) - LSNO tambem nao tem
// PX/PY/PZ livre: PBDI/PTDI/POFF (ver buildGeometry) ja posicionam as 2
// faces RELATIVAS a essa origem. PAAX/PBAX aqui sao os MESMOS axisA/axisB
// da extrusao (normal = axisA x axisB - ver resolveExtrusionBasis),
// reaproveitados sem duplicar a logica.
export function resolveSnoutOrigin(data) {
  const { originPoint } = resolveExtrusionBasis(data);
  return originPoint ? originPoint.clone() : new THREE.Vector3(0, 0, 0);
}

// Resolve o arco de um "torus" (curva de tubo ligando 2 pontos - SCTO/RTOR,
// ver core/PrimitiveStore.js): PAAX/PBAX TEM que referenciar um P-point cada
// ("P n" - ver utils/axisExpression.js) - a POSICAO de cada um vira a
// extremidade do arco (as faces circulares/retangulares ficam EXATAMENTE
// nesses pontos) e a DIRECAO vira a tangente do tubo naquela ponta. O raio
// da curva NAO e um campo livre - e o UNICO raio que faz o arco tangente as
// 2 direcoes nos 2 pontos (como uma curva real de tubo ligando 2 pontas de
// reta) - por isso nao ha campo de raio/angulo aqui, diferente de outros
// catalogos de torus.
//
// LIMITACAO (pedida explicitamente, pra manter o calculo simples e robusto
// em vez de resolver o caso geral 3D): os 2 pontos TEM que compartilhar uma
// coordenada (X, Y ou Z) - o arco inteiro fica no plano perpendicular a esse
// eixo compartilhado (bends "retos", sem inclinacao fora de eixo). Dentro
// desse plano, o centro do arco e a interseccao das 2 retas perpendiculares
// as direcoes em cada ponto (metodo classico de "circulo tangente a 2
// retas") - se as 2 direcoes forem paralelas, essa interseccao nao existe
// (retas paralelas nunca se cruzam), entao devolve null.
//
// Devolve null (elemento fica com uma geometria de fallback - ver
// buildTorusPlaceholder) se: falta P-point em PAAX ou PBAX; os pontos nao
// compartilham nenhuma coordenada; ou as 2 direcoes sao paralelas.
export function resolveTorusArc(data) {
  const resolvedA = resolveAxisExpression(data.axisA);
  const resolvedB = resolveAxisExpression(data.axisB);
  if (!resolvedA.origin || !resolvedB.origin) return null;

  const a = resolvedA.origin;
  const b = resolvedB.origin;
  // O E3D usa a direcao OPOSTA a resolvida pelo P-point pra este elemento -
  // digitar "P4" (sem sinal de menos) numa ponta deve fazer a curva sair na
  // direcao CONTRARIA a direcao real daquele ponto (comportamento
  // confirmado pelo usuario contra o E3D de verdade, diferente de todas as
  // outras primitivas deste app, que usam a direcao tal e qual).
  const dirA = resolvedA.direction.clone().negate();
  const dirB = resolvedB.direction.clone().negate();

  const coordsA = [a.x, a.y, a.z];
  const coordsB = [b.x, b.y, b.z];
  const sharedAxis = [0, 1, 2].find((i) => Math.abs(coordsA[i] - coordsB[i]) < 1e-6);
  if (sharedAxis === undefined) return null;
  const [u, v] = [0, 1, 2].filter((i) => i !== sharedAxis);

  const a2 = [coordsA[u], coordsA[v]];
  const b2 = [coordsB[u], coordsB[v]];
  const da2 = [dirA.getComponent(u), dirA.getComponent(v)];
  const db2 = [dirB.getComponent(u), dirB.getComponent(v)];

  // Centro do arco: interseccao da reta por A perpendicular a da2 (direcao
  // nA) com a reta por B perpendicular a db2 (direcao nB).
  const nA = [-da2[1], da2[0]];
  const nB = [-db2[1], db2[0]];
  const det = nB[0] * nA[1] - nA[0] * nB[1];
  if (Math.abs(det) < 1e-9) return null; // direcoes paralelas - sem centro unico

  const dx = b2[0] - a2[0];
  const dy = b2[1] - a2[1];
  const t1 = (nB[0] * dy - dx * nB[1]) / det;
  const center2 = [a2[0] + t1 * nA[0], a2[1] + t1 * nA[1]];
  const radius = Math.hypot(a2[0] - center2[0], a2[1] - center2[1]);
  if (radius < 1e-6) return null; // A e B coincidentes - sem arco nenhum

  const angleA = Math.atan2(a2[1] - center2[1], a2[0] - center2[0]);
  const angleB = Math.atan2(b2[1] - center2[1], b2[0] - center2[0]);

  // Sentido do arco (horario ou anti-horario): compara a tangente
  // "esperada" em A pra quem anda anti-horario (perpendicular ao raio,
  // rotacionado +90) com da2 - se apontarem no mesmo sentido, o arco vai
  // anti-horario; senao, horario.
  const radialA = [a2[0] - center2[0], a2[1] - center2[1]];
  const ccwTangentA = [-radialA[1], radialA[0]];
  const goesCCW = ccwTangentA[0] * da2[0] + ccwTangentA[1] * da2[1] >= 0;

  const TWO_PI = Math.PI * 2;
  let sweep = ((angleB - angleA) % TWO_PI + TWO_PI) % TWO_PI; // normaliza pra [0, 2PI)
  if (!goesCCW) sweep -= TWO_PI; // sentido horario: varredura negativa

  return { sharedAxis, u, v, sharedValue: coordsA[sharedAxis], center2, radius, angleA, sweep };
}

// Posicao "de mundo" da origem de uma primitiva. Cilindro/cone/piramide/
// snout sao um caso especial (ver resolveCylinderOrigin/resolveConeOrigin/
// resolvePyramidOrigin/resolveSnoutOrigin: sem posicao livre, so eixo(s), e
// no caso do cilindro tambem uma distancia). Torus/RTOR sempre fica em
// 0,0,0 - a geometria (ver buildTorusGeometry) ja embute as posicoes
// ABSOLUTAS dos 2 pontos direto nos vertices, entao nao ha "origem" nenhuma
// pra deslocar. Pras demais, so extrusao pode ter um P-point referenciado
// (PAAX/PBAX - ver resolveExtrusionBasis), que vira a origem (0,0,0) LOCAL -
// `data.position` deixa de ser posicao absoluta de mundo e passa a ser um
// deslocamento a partir dali. Sem referencia a P-point (ou pras primitivas
// sem campo de eixo, tipo caixa/esfera), `data.position` continua sendo a
// posicao absoluta de sempre.
//
// Elemento NEGATIVO (`data.parentId` - ver core/PrimitiveStore.js): a origem
// NAO soma a do "pai" - `parentId` e SO vinculo organizacional (agrupamento
// visual na arvore, ordem de exportacao no DATAL - ver
// persistence/DatalExporter.js) - decisao explicita do usuario, confirmada
// contra o E3D de verdade: um GMSET real e uma lista PLANA (cap. 7.5 do
// manual), sem transform de coordenada entre membros - cada primitiva
// (positiva ou negativa) resolve sua PROPRIA origem a partir dos SEUS
// PROPRIOS campos (position/axis/distance/etc.), exatamente como uma
// positiva comum. Por isso dar ao negativo o MESMO valor de campo do
// positivo faz os dois COINCIDIREM exatamente (posicao "absoluta", sem
// correlacao com o pai) - e nao um deslocamento adicional por cima da
// origem do pai (bug real ja corrigido 2x: 1a vez so pra origem-via-P-point,
// que "resolveu por coincidencia" o caso PAAX igual ao do pai mas nao o caso
// geral; esta e a correcao definitiva, removendo a soma por completo).
export function resolvePrimitiveOrigin(data, resolveParam) {
  return resolveOwnPrimitiveOrigin(data, resolveParam);
}

function resolveOwnPrimitiveOrigin(data, resolveParam) {
  const type = basePositiveType(data.type);
  if (type === 'cylinder') return resolveCylinderOrigin(data, resolveParam);
  if (type === 'cone') return resolveConeOrigin(data);
  if (type === 'pyramid') return resolvePyramidOrigin(data);
  if (type === 'snout') return resolveSnoutOrigin(data);
  if (type === 'torus' || type === 'torusRect') return new THREE.Vector3(0, 0, 0);
  const originPoint = type === 'extrusion' ? resolveExtrusionBasis(data).originPoint : null;
  const offset = new THREE.Vector3(
    resolveNumber(data.position.x, resolveParam),
    resolveNumber(data.position.y, resolveParam),
    resolveNumber(data.position.z, resolveParam)
  );
  return originPoint ? originPoint.clone().add(offset) : offset;
}

// Constroi o contorno 2D (THREE.Shape) do Loop/SLOO de uma extrusao a partir
// dos vertices ja resolvidos (numeros). Vertice com raio > 0 vira um canto
// arredondado: aproximado por uma curva quadratica (o proprio vertice como
// ponto de controle) entre os pontos de tangencia em cada aresta adjacente -
// nao e um arco de circulo perfeito, mas e visualmente equivalente e muito
// mais simples que calcular centro/angulos de arco exatos. O comprimento de
// tangencia e limitado a metade da aresta mais curta, pra cantos vizinhos
// nunca se sobreporem numa aresta curta.
function buildLoopShape(vertices) {
  const shape = new THREE.Shape();
  const n = vertices.length;

  if (n < 3) {
    // Perfil invalido (menos de 3 vertices) - um quadrado minusculo em vez
    // de deixar a extrusao quebrar o resto da cena.
    shape.moveTo(-1, -1);
    shape.lineTo(1, -1);
    shape.lineTo(1, 1);
    shape.lineTo(-1, 1);
    shape.closePath();
    return shape;
  }

  const pts = vertices.map((v) => new THREE.Vector2(v.x, v.y));

  function cornerTangentPoints(i) {
    const curr = pts[i];
    const prev = pts[(i - 1 + n) % n];
    const next = pts[(i + 1) % n];
    const radius = vertices[i].radius;
    if (radius <= 0) return { p1: curr, p2: curr, radius: 0 };

    const toPrev = prev.clone().sub(curr);
    const toNext = next.clone().sub(curr);
    const lenPrev = toPrev.length();
    const lenNext = toNext.length();
    if (lenPrev < 1e-6 || lenNext < 1e-6) return { p1: curr, p2: curr, radius: 0 };

    const dirPrev = toPrev.divideScalar(lenPrev);
    const dirNext = toNext.divideScalar(lenNext);
    const cosAngle = THREE.MathUtils.clamp(dirPrev.dot(dirNext), -1, 1);
    const angle = Math.acos(cosAngle);
    if (angle < 1e-3 || angle > Math.PI - 1e-3) return { p1: curr, p2: curr, radius: 0 }; // colinear

    const maxTangent = Math.min(lenPrev, lenNext) * 0.49;
    const tangentLength = Math.min(radius / Math.tan(angle / 2), maxTangent);

    return {
      p1: curr.clone().addScaledVector(dirPrev, tangentLength),
      p2: curr.clone().addScaledVector(dirNext, tangentLength),
      radius
    };
  }

  const corners = pts.map((_, i) => cornerTangentPoints(i));

  shape.moveTo(corners[0].p1.x, corners[0].p1.y);
  for (let i = 0; i < n; i++) {
    const corner = corners[i];
    if (corner.radius > 0) {
      shape.quadraticCurveTo(pts[i].x, pts[i].y, corner.p2.x, corner.p2.y);
    }
    const nextCorner = corners[(i + 1) % n];
    shape.lineTo(nextCorner.p1.x, nextCorner.p1.y);
  }
  shape.closePath();
  return shape;
}

// Piramide/tronco de piramide (LPYR): 8 vertices (retangulo da base +
// retangulo do topo) - topo 0x0 da uma piramide "de ponta"; topo > 0 da um
// tronco. Ver PBBT/PCBT (base), PBTP/PCTP (topo), PBDI/PTDI (distancia de
// cada face ate a origem, ao longo do eixo Z local) e PBOF/PCOF (deslocamento
// do CENTRO do topo em relacao ao centro da base, no plano XY local - permite
// um tronco "torto"/assimetrico, nao so um taper concentrico) no capitulo
// 7.4.11 do manual de referencia. `distBottom`/`distTop` sao a coordenada Z
// local JA COM SINAL (igual ao PBDI/PTDI real - confirmado por
// REFERENCIAS/PYRA.PMLMAC: `PBDI ( -150 )` bota a base 150mm ANTES da
// origem, `PTDI 150` bota o topo 150mm DEPOIS - MESMA convencao nos dois,
// sem inversao escondida). A base fica em Z local `distBottom`; o topo em
// `distTop` - a ORIGEM (Z local 0) pode ficar em qualquer ponto entre as
// duas faces (ou fora delas), nao necessariamente no meio. ATENCAO: ja foi
// `-distBottom` aqui (exigia digitar um valor POSITIVO pra base ficar
// "antes" da origem, ao contrario do PBDI real) - mudado porque confundia
// quem digita o mesmo valor negativo que usaria no E3D de verdade.
function buildPyramidGeometry(bottomWidth, bottomDepth, topWidth, topDepth, distBottom, distTop, offsetX, offsetY) {
  const hbw = bottomWidth / 2;
  const hbd = bottomDepth / 2;
  const htw = topWidth / 2;
  const htd = topDepth / 2;
  const bz = distBottom;
  const tz = distTop;

  // prettier-ignore
  const positions = new Float32Array([
    -hbw, -hbd, bz,   hbw, -hbd, bz,   hbw, hbd, bz,   -hbw, hbd, bz, // base (0-3)
    offsetX - htw, offsetY - htd, tz,   offsetX + htw, offsetY - htd, tz,   offsetX + htw, offsetY + htd, tz,   offsetX - htw, offsetY + htd, tz // topo (4-7)
  ]);
  // prettier-ignore
  const indices = [
    0, 2, 1,  0, 3, 2, // base (normal -Z)
    4, 5, 6,  4, 6, 7, // topo (normal +Z)
    0, 1, 5,  0, 5, 4, // lateral -Y
    1, 2, 6,  1, 6, 5, // lateral +X
    2, 3, 7,  2, 7, 6, // lateral +Y
    3, 0, 4,  3, 4, 7  // lateral -X
  ];

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

// Snout/tronco de cone (LSNO): 2 aneis (base + topo, diametros
// independentes - topo 0 da um cone "de ponta") + 2 tampas. Construido no
// "espaco local do perfil" (X = axisA, Y = axisB, Z = normal = axisA x
// axisB - MESMA convencao da extrusao, ver resolveExtrusionBasis - quem
// chama remapeia pro mundo depois via applyMatrix4). `distBottom`/`distTop`
// sao a coordenada Z local JA COM SINAL, mesma convencao (e mesmo motivo) de
// buildPyramidGeometry acima - a base fica em Z local `distBottom`, o topo
// em `distTop` (mesma ideia - a origem nao precisa ficar no meio do
// solido). `offset` (POFF) desloca o CENTRO do topo ao longo do eixo local
// X (axisA) em relacao ao centro da base - so 1 eixo de excentricidade (ao
// contrario da piramide, que tem PBOF/PCOF separados), igual ao catalogo real.
function buildSnoutGeometry(bottomDiameter, topDiameter, distBottom, distTop, offset, segments) {
  const rb = bottomDiameter / 2;
  const rt = topDiameter / 2;
  const bz = distBottom;
  const tz = distTop;

  const positions = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    positions.push(Math.cos(theta) * rb, Math.sin(theta) * rb, bz);
  }
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    positions.push(offset + Math.cos(theta) * rt, Math.sin(theta) * rt, tz);
  }
  const bottomCenterIndex = positions.length / 3;
  positions.push(0, 0, bz);
  const topCenterIndex = bottomCenterIndex + 1;
  positions.push(offset, 0, tz);

  const indices = [];
  for (let i = 0; i < segments; i++) {
    const next = (i + 1) % segments;
    const b0 = i;
    const b1 = next;
    const t0 = segments + i;
    const t1 = segments + next;
    indices.push(b0, t0, t1, b0, t1, b1); // lateral (2 triangulos por segmento)
    indices.push(bottomCenterIndex, b1, b0); // tampa da base
    indices.push(topCenterIndex, t0, t1); // tampa do topo
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

const TORUS_TUBE_SEGMENTS = 16; // resolucao da secao transversal circular (torus redondo)
const TORUS_ARC_SEGMENTS = 48; // resolucao ao longo do arco

// Converte coordenadas 2D do plano do arco (ver resolveTorusArc: `u`/`v` sao
// os indices dos 2 eixos de mundo que formam esse plano) + o valor do eixo
// compartilhado (constante ao longo de toda a curva) pra um ponto 3D real.
export function torusPoint3D(arc, u2, v2) {
  const p = new THREE.Vector3();
  p.setComponent(arc.u, u2);
  p.setComponent(arc.v, v2);
  p.setComponent(arc.sharedAxis, arc.sharedValue);
  return p;
}

// Varre uma secao transversal (lista de pontos 2D {radial, axial} - radial =
// deslocamento ao longo do raio, pra fora do centro do arco; axial =
// deslocamento ao longo do eixo compartilhado, que fica FIXO durante toda a
// curva) ao longo do arco resolvido por resolveTorusArc, gerando um solido
// fechado (lateral + as 2 tampas). Como o arco (`center2`/`radius`/`angleA`/
// `sweep`) ja foi calculado a partir das posicoes ABSOLUTAS dos 2 P-points,
// os vertices gerados aqui ja sao coordenadas de MUNDO - a tampa inicial
// cai exatamente no ponto de PAAX, a final exatamente no de PBAX (ver
// resolveTorusArc), sem precisar de nenhum transform/origem depois.
function buildTorusGeometry(arc, crossSection, arcSegments) {
  const ringCount = arcSegments + 1;
  const n = crossSection.length;
  const positions = [];
  let startCenter = null;
  let endCenter = null;

  for (let i = 0; i < ringCount; i++) {
    const t = i / arcSegments;
    const angle = arc.angleA + arc.sweep * t;
    const cosA = Math.cos(angle);
    const sinA = Math.sin(angle);
    const cu = arc.center2[0] + cosA * arc.radius;
    const cv = arc.center2[1] + sinA * arc.radius;
    const centerPoint = torusPoint3D(arc, cu, cv);
    if (i === 0) startCenter = centerPoint;
    if (i === ringCount - 1) endCenter = centerPoint;
    for (const cs of crossSection) {
      const p = torusPoint3D(arc, cu + cosA * cs.radial, cv + sinA * cs.radial);
      p.setComponent(arc.sharedAxis, arc.sharedValue + cs.axial);
      positions.push(p.x, p.y, p.z);
    }
  }

  const indices = [];
  for (let i = 0; i < arcSegments; i++) {
    for (let j = 0; j < n; j++) {
      const jNext = (j + 1) % n;
      const a0 = i * n + j;
      const a1 = i * n + jNext;
      const b0 = (i + 1) * n + j;
      const b1 = (i + 1) * n + jNext;
      indices.push(a0, b0, b1, a0, b1, a1); // lateral
    }
  }

  // Tampas (leque a partir do centro de cada extremidade) - ficam
  // EXATAMENTE nos 2 P-points, ver comentario de resolveTorusArc.
  const startCenterIndex = positions.length / 3;
  positions.push(startCenter.x, startCenter.y, startCenter.z);
  for (let j = 0; j < n; j++) {
    indices.push(startCenterIndex, (j + 1) % n, j);
  }
  const endCenterIndex = startCenterIndex + 1;
  const endRingBase = (ringCount - 1) * n;
  positions.push(endCenter.x, endCenter.y, endCenter.z);
  for (let j = 0; j < n; j++) {
    indices.push(endCenterIndex, endRingBase + j, endRingBase + ((j + 1) % n));
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

// Geometria de fallback quando resolveTorusArc devolve null (PAAX/PBAX sem
// P-point valido, direcoes paralelas, ou pontos sem coordenada em comum) -
// uma caixinha no lugar de sumir ou quebrar o resto da cena (mesmo
// principio de buildLoopShape acima, pra menos de 3 vertices).
function buildTorusPlaceholder() {
  return new THREE.BoxGeometry(50, 50, 50);
}

// Constroi a geometria solida a partir das dimensoes da primitiva (ver
// capitulo 7.4 do manual de referencia para os atributos reais de cada tipo).
// Elemento negativo (ver basePositiveType) usa a MESMA geometria do positivo
// correspondente - so a aparencia (createPrimitiveMesh) e a hierarquia
// (`parentId`, ver resolvePrimitiveOrigin) sao diferentes.
function buildGeometry(data, resolveParam) {
  const dims = data.dimensions;

  switch (basePositiveType(data.type)) {
    case 'cylinder': {
      const diameter = resolveDimension(dims.diameter, resolveParam);
      const height = resolveDimension(dims.height, resolveParam);
      const geometry = rotateAxisToZ(new THREE.CylinderGeometry(diameter / 2, diameter / 2, height, RADIAL_SEGMENTS));
      // THREE.CylinderGeometry nasce CENTRADA (de -h/2 a +h/2) - desloca pra
      // nascer da BASE (Z local 0 a h) antes de orientar pro eixo de
      // verdade: SCYL nao tem PX/PY/PZ, so PAXI+PDIS+PHEI (ver
      // resolveCylinderOrigin) - a origem e a base do solido, nao o centro
      // (mesmo principio da extrusao - ver o case 'extrusion' abaixo).
      geometry.translate(0, 0, height / 2);
      // PAXI (ver resolveSingleAxis) - se for diferente do Z padrao,
      // reorienta a geometria (mesma ideia da extrusao: a orientacao fica
      // "assada" nos vertices, nao num transform do mesh - ver
      // applyTransformToPrimitive).
      const { quat } = resolveSingleAxis(data);
      geometry.applyMatrix4(new THREE.Matrix4().makeRotationFromQuaternion(quat));
      return geometry;
    }
    case 'cone': {
      // SCON: PDIA (diametro da base) + PDIS (altura do vertice acima da
      // base - dims.height JA E o PDIS, nao ha campo separado de offset, ao
      // contrario do cilindro - ver resolveConeOrigin).
      const diameter = resolveDimension(dims.diameter, resolveParam);
      const height = resolveDimension(dims.height, resolveParam);
      const geometry = rotateAxisToZ(new THREE.ConeGeometry(diameter / 2, height, RADIAL_SEGMENTS));
      // THREE.ConeGeometry tambem nasce CENTRADA (apice em +h/2, base em
      // -h/2) - mesmo deslocamento do cilindro acima, pra base nascer em
      // Z local 0 e o apice em h.
      geometry.translate(0, 0, height / 2);
      const { quat } = resolveSingleAxis(data);
      geometry.applyMatrix4(new THREE.Matrix4().makeRotationFromQuaternion(quat));
      return geometry;
    }
    case 'sphere': {
      const diameter = resolveDimension(dims.diameter, resolveParam);
      return new THREE.SphereGeometry(diameter / 2, RADIAL_SEGMENTS, RADIAL_SEGMENTS / 2);
    }
    case 'disc': {
      // SDIS: disco plano de espessura zero, normal = eixo Z local (PAXI).
      // CircleGeometry ja nasce no plano XY (normal +Z) - sem rotacao extra.
      const diameter = resolveDimension(dims.diameter, resolveParam);
      return new THREE.CircleGeometry(diameter / 2, RADIAL_SEGMENTS);
    }
    case 'pyramid': {
      const bottomWidth = resolveDimension(dims.bottomWidth, resolveParam);
      const bottomDepth = resolveDimension(dims.bottomDepth, resolveParam);
      const topWidth = resolveDimension(dims.topWidth, resolveParam, 0);
      const topDepth = resolveDimension(dims.topDepth, resolveParam, 0);
      // PBDI/PTDI/PBOF/PCOF podem ser 0 ou negativos (deslocamento, nao
      // tamanho) - resolveNumber (sem piso minimo), nao resolveDimension.
      const distBottom = resolveNumber(dims.distBottom, resolveParam);
      const distTop = resolveNumber(dims.distTop, resolveParam);
      const offsetX = resolveNumber(dims.offsetX, resolveParam);
      const offsetY = resolveNumber(dims.offsetY, resolveParam);
      const geometry = buildPyramidGeometry(bottomWidth, bottomDepth, topWidth, topDepth, distBottom, distTop, offsetX, offsetY);
      // PBAX/PCAX/PAAX (ver resolvePyramidBasis) - mesma ideia da extrusao:
      // a orientacao fica "assada" nos vertices, nao num transform do mesh.
      const { axisX, axisY, axisZ } = resolvePyramidBasis(data);
      geometry.applyMatrix4(new THREE.Matrix4().makeBasis(axisX, axisY, axisZ));
      return geometry;
    }
    case 'snout': {
      // LSNO: PBDM/PTDM (diametros base/topo, topo 0 = cone "de ponta") +
      // PBDI/PTDI (distancia de cada face ate a origem, ao longo do eixo A x
      // B) + POFF (excentricidade do topo ao longo do eixo A). PAAX/PBAX =
      // axisA/axisB - MESMA regra da extrusao (normal = axisA x axisB - ver
      // resolveExtrusionBasis), reaproveitada sem duplicar logica.
      const bottomDiameter = resolveDimension(dims.bottomDiameter, resolveParam);
      const topDiameter = resolveDimension(dims.topDiameter, resolveParam, 0);
      // PBDI/PTDI/POFF podem ser 0 ou negativos (deslocamento, nao tamanho) -
      // resolveNumber (sem piso minimo), nao resolveDimension.
      const distBottom = resolveNumber(dims.distBottom, resolveParam);
      const distTop = resolveNumber(dims.distTop, resolveParam);
      const offset = resolveNumber(dims.offset, resolveParam);
      const geometry = buildSnoutGeometry(bottomDiameter, topDiameter, distBottom, distTop, offset, RADIAL_SEGMENTS);
      const { axisA, axisB, normal } = resolveExtrusionBasis(data);
      geometry.applyMatrix4(new THREE.Matrix4().makeBasis(axisA, axisB, normal));
      return geometry;
    }
    case 'torus': {
      // SCTO: curva de tubo (secao REDONDA, diametro PDIA) ligando os 2
      // pontos de PAAX/PBAX - ver resolveTorusArc pro calculo do arco (SEM
      // campo de raio/angulo: e o unico arco tangente as 2 direcoes nos 2
      // pontos).
      const diameter = resolveDimension(dims.diameter, resolveParam);
      const arc = resolveTorusArc(data);
      if (!arc) return buildTorusPlaceholder();
      const r = diameter / 2;
      const crossSection = [];
      for (let i = 0; i < TORUS_TUBE_SEGMENTS; i++) {
        const phi = (i / TORUS_TUBE_SEGMENTS) * Math.PI * 2;
        crossSection.push({ radial: Math.cos(phi) * r, axial: Math.sin(phi) * r });
      }
      return buildTorusGeometry(arc, crossSection, TORUS_ARC_SEGMENTS);
    }
    case 'torusRect': {
      // RTOR: mesma curva do 'torus' acima (ver resolveTorusArc), so que com
      // secao transversal RETANGULAR (PDIA = largura ao longo do raio, PHEI
      // = altura ao longo do eixo compartilhado) em vez de circular.
      const width = resolveDimension(dims.diameter, resolveParam);
      const height = resolveDimension(dims.height, resolveParam);
      const arc = resolveTorusArc(data);
      if (!arc) return buildTorusPlaceholder();
      const hw = width / 2;
      const hh = height / 2;
      const crossSection = [
        { radial: -hw, axial: -hh },
        { radial: hw, axial: -hh },
        { radial: hw, axial: hh },
        { radial: -hw, axial: hh }
      ];
      return buildTorusGeometry(arc, crossSection, TORUS_ARC_SEGMENTS);
    }
    case 'extrusion': {
      // SEXT: perfil 2D livre (Loop/SLOO de Vertices/SVER - PX/PY/PRAD) na
      // origem (PZ) do SLOO, extrudado por PHEI - a origem e a BASE do
      // solido, nao o centro (ao contrario de Box/Cilindro/etc., que ficam
      // centrados na propria posicao). Construido primeiro no "espaco local
      // do SLOO" (PX/PY do vertice = eixo local X/Y, extrusao ao longo do
      // eixo local Z - THREE.ExtrudeGeometry ja faz isso naturalmente, de
      // Z=0 pra Z=depth), depois os vertices sao remapeados pro espaco de
      // mundo via a base PAAX/PBAX (ver resolveExtrusionBasis) - como
      // primitivas nao tem rotacao propria (mesh.rotation fica sempre
      // zerado - ver applyTransformToPrimitive), a orientacao PRECISA ficar
      // "assada" direto nos vertices da geometria, nao num transform do mesh.
      const height = resolveDimension(dims.height, resolveParam);
      const vertices = resolveVertices(data.vertices, resolveParam);
      const shape = buildLoopShape(vertices);
      const geometry = new THREE.ExtrudeGeometry(shape, { depth: height, bevelEnabled: false, curveSegments: 16 });

      const { axisA, axisB, normal } = resolveExtrusionBasis(data);
      // Matriz cujas colunas sao os 3 eixos de destino - mapeia (localX,
      // localY, localZ) -> localX*axisA + localY*axisB + localZ*normal.
      const basisMatrix = new THREE.Matrix4().makeBasis(axisA, axisB, normal);
      geometry.applyMatrix4(basisMatrix);
      return geometry;
    }
    case 'box':
    default: {
      const width = resolveDimension(dims.width, resolveParam);
      const depth = resolveDimension(dims.depth, resolveParam);
      const height = resolveDimension(dims.height, resolveParam);
      return new THREE.BoxGeometry(width, depth, height);
    }
  }
}

// Constroi o Object3D (solido + contorno de selecao) correspondente a uma
// primitiva. Geometria e material sao proprios de cada objeto. `resolveParam`
// resolve referencias a parametro nas expressoes de dimensao (ver
// VariantStore.resolveParam).
// Elemento negativo (NSBO/NSCY - ver core/PrimitiveStore.js) e representado
// como CONTORNO (wireframe) num vermelho fixo, IGNORANDO `data.color` -
// "isto e um buraco" e uma propriedade semantica do elemento, nao uma
// escolha de estilo do usuario (ao contrario da cor de um positivo comum).
// Historico (ver CLAUDE.md pra detalhes completos, nao repetir os 2 rounds
// anteriores): 1o round foi um SOLIDO translucido; 2o round foi um corte
// booleano de verdade via CSG (three-bvh-csg); DECISAO FINAL do usuario:
// nem um nem outro - so um CONTORNO de arestas (EdgesGeometry, mesma tecnica
// ja usada pelo "selection-outline" abaixo), SEMPRE visivel (nao so quando
// seleciona), sem CSG nenhum. O MESH SOLIDO continua existindo por baixo do
// contorno, mas com opacidade SEMPRE 0 (invisivel) - serve so pra manter o
// raycasting/selecao no viewport funcionando (clicar "dentro" do volume do
// negativo ainda seleciona ele), nunca aparece preenchido.
const NEGATIVE_COLOR = '#ff4d4d';
// O contorno do negativo ignora o depth buffer (`depthTest: false`) - sem
// isso, a maior parte do contorno ficaria escondida (o negativo normalmente
// esta ENTERRADO dentro do solido opaco do positivo, e ate o proprio solido
// invisivel do negativo esconderia as arestas do "fundo" dele por
// auto-oclusao normal de profundidade) - pedido explicito do usuario:
// "poder ver as arestas do fundo dos negativos". Tracejado (`LineDashedMaterial`)
// e a convencao de desenho tecnico pra indicar uma aresta que normalmente
// estaria escondida atras de material solido, em vez de uma linha continua
// (que sugeriria uma aresta de verdade visivel a olho nu).
const NEGATIVE_WIREFRAME_DASH_SIZE = 12;
const NEGATIVE_WIREFRAME_GAP_SIZE = 6;

export function createPrimitiveMesh(data, resolveParam) {
  const geometry = buildGeometry(data, resolveParam);
  const negative = isNegativePrimitiveType(data.type);

  const material = new THREE.MeshStandardMaterial({
    color: negative ? NEGATIVE_COLOR : data.color,
    transparent: true,
    // Negativo: SEMPRE invisivel como solido (ver comentario acima) - a
    // aparencia de verdade e o contorno de arestas adicionado abaixo.
    opacity: negative ? 0 : data.opacity,
    side: THREE.DoubleSide,
    roughness: 0.6,
    metalness: 0.1
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = data.name;
  mesh.userData.objType = 'primitive';
  mesh.userData.refId = data.id;
  mesh.userData.dimensions = { ...data.dimensions };
  mesh.userData.vertices = data.vertices; // so relevante pra 'extrusion' (SEXT) - ver rebuildPrimitiveGeometry
  mesh.userData.axisA = data.axisA;
  mesh.userData.axisB = data.axisB;
  mesh.userData.axis = data.axis; // so relevante pra 'cylinder'/'cone' - PAXI
  mesh.userData.axisX = data.axisX; // so relevante pra 'pyramid' (LPYR) - PBAX/PCAX/PAAX
  mesh.userData.axisY = data.axisY;
  mesh.userData.axisZ = data.axisZ;

  // Contorno PERMANENTE (sempre visivel, independente de selecao) que
  // representa a forma do negativo - ver comentario acima de NEGATIVE_COLOR.
  // `raycast = () => {}` pra nunca interceptar cliques (a selecao usa o mesh
  // solido invisivel por baixo, ja com raycasting normal).
  if (negative) {
    const wireframe = new THREE.LineSegments(
      new THREE.EdgesGeometry(geometry),
      new THREE.LineDashedMaterial({
        color: NEGATIVE_COLOR,
        transparent: true,
        opacity: data.opacity,
        depthTest: false,
        dashSize: NEGATIVE_WIREFRAME_DASH_SIZE,
        gapSize: NEGATIVE_WIREFRAME_GAP_SIZE
      })
    );
    wireframe.name = 'negative-wireframe';
    wireframe.computeLineDistances(); // exigido pelo LineDashedMaterial - sem isso os tracos nao aparecem
    wireframe.raycast = () => {};
    mesh.add(wireframe);
  }

  const outline = new THREE.LineSegments(
    new THREE.EdgesGeometry(geometry),
    // Cor inicial irrelevante - so aparece quando selecionado, e nesse caso
    // setPrimitiveSelectionHighlight ja decide a cor (nunca fica sem tocar).
    new THREE.LineBasicMaterial({ color: 0xffaa34 })
  );
  outline.name = 'selection-outline';
  outline.visible = false;
  outline.raycast = () => {}; // nunca deve interceptar cliques/raycasts
  mesh.add(outline);

  applyTransformToPrimitive(mesh, data, resolveParam);
  mesh.visible = data.visible;

  return mesh;
}

// SEM rotacao nem escala por enquanto (ver comentario em core/PrimitiveStore.js)
// - o mesh fica sempre com eixos alinhados ao mundo e escala 1:1, so a
// posicao se aplica; o tamanho vem inteiramente das dimensoes reais
// (buildGeometry). `resolveParam` resolve referencias a parametro na
// posicao. Extrusao/cilindro sao um caso especial (ver
// resolvePrimitiveOrigin): se o campo de eixo referencia um P-point, a
// posicao dele vira a origem local da primitiva.
export function applyTransformToPrimitive(mesh, data, resolveParam = () => undefined) {
  mesh.position.copy(resolvePrimitiveOrigin(data, resolveParam));
  // Forca identidade: se o gizmo foi usado em modo Rotacionar/Escalar sobre
  // uma primitiva (nao deveria, mas a barra de ferramentas e global e nao
  // sabe o tipo selecionado), o objectChange grava so a posicao - sem isso o
  // mesh ficaria visualmente torto/escalado ate a pagina recarregar.
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
}

// Sincroniza transformacao/aparencia (rapido, chamado a cada update). Trocar
// as dimensoes reais exige refazer a geometria - ver rebuildPrimitiveGeometry.
export function syncPrimitiveMesh(mesh, data, resolveParam) {
  applyTransformToPrimitive(mesh, data, resolveParam);
  mesh.visible = data.visible;
  mesh.name = data.name;
  // Negativo ignora data.color e o solido fica sempre com opacidade 0 (ver
  // createPrimitiveMesh) - so o contorno ('negative-wireframe') usa
  // NEGATIVE_COLOR/data.opacity de verdade.
  const negative = isNegativePrimitiveType(data.type);
  const targetColor = negative ? NEGATIVE_COLOR : data.color;
  const targetOpacity = negative ? 0 : data.opacity;
  if (mesh.material.opacity !== targetOpacity) {
    mesh.material.opacity = targetOpacity;
  }
  if (`#${mesh.material.color.getHexString()}` !== targetColor) {
    mesh.material.color.set(targetColor);
  }
  const wireframe = mesh.getObjectByName('negative-wireframe');
  if (wireframe && wireframe.material.opacity !== data.opacity) {
    wireframe.material.opacity = data.opacity;
  }
}

// Refaz a geometria (e os contornos - selecao + contorno permanente do
// negativo) quando as dimensoes reais mudam, ou quando a variante ativa/
// parametros mudam (a expressao pode resolver para outro valor) - mais caro
// que o sync normal, por isso e chamado so quando necessario.
export function rebuildPrimitiveGeometry(mesh, data, resolveParam) {
  const newGeometry = buildGeometry(data, resolveParam);
  mesh.geometry.dispose();
  mesh.geometry = newGeometry;

  const outline = mesh.getObjectByName('selection-outline');
  if (outline) {
    outline.geometry.dispose();
    outline.geometry = new THREE.EdgesGeometry(newGeometry);
  }
  const wireframe = mesh.getObjectByName('negative-wireframe');
  if (wireframe) {
    wireframe.geometry.dispose();
    wireframe.geometry = new THREE.EdgesGeometry(newGeometry);
    wireframe.computeLineDistances(); // ver comentario em createPrimitiveMesh - exigido pelo LineDashedMaterial
  }

  mesh.userData.dimensions = { ...data.dimensions };
  mesh.userData.vertices = data.vertices;
  mesh.userData.axisA = data.axisA;
  mesh.userData.axisB = data.axisB;
  mesh.userData.axis = data.axis;
  mesh.userData.axisX = data.axisX;
  mesh.userData.axisY = data.axisY;
  mesh.userData.axisZ = data.axisZ;
}

export function setPrimitiveSelectionHighlight(mesh, selected, locked) {
  const outline = mesh.getObjectByName('selection-outline');
  if (!outline) return;
  outline.visible = selected;
  outline.material.color.set(locked ? 0xff5c5c : 0xffaa34);
}

export function disposePrimitiveMesh(mesh) {
  mesh.geometry.dispose();
  mesh.material.dispose();
  const outline = mesh.getObjectByName('selection-outline');
  if (outline) {
    outline.geometry.dispose();
    outline.material.dispose();
  }
  const wireframe = mesh.getObjectByName('negative-wireframe');
  if (wireframe) {
    wireframe.geometry.dispose();
    wireframe.material.dispose();
  }
}
