import * as THREE from 'three';
import { DEG2RAD } from '../utils/transformMath.js';
import { resolveNumber } from '../utils/expressionEvaluator.js';
import { axisVector, DEFAULT_AXIS } from '../utils/axisDirections.js';
import { resolveAxisExpression } from '../utils/axisExpression.js';
import { POINT_MARKER_BASE_ARROW_LENGTH, POINT_MARKER_BASE_HANDLE_RADIUS } from '../utils/pointMarkerSize.js';

const POINT_COLOR = 0xff3fd8;
// Tamanho "de projeto" (escala 1) - o mesh e reescalado a cada frame por
// SceneManager para manter um tamanho de tela constante, independente do
// zoom (ver utils/pointMarkerSize.js).
const ARROW_LENGTH = POINT_MARKER_BASE_ARROW_LENGTH;
const HANDLE_RADIUS = POINT_MARKER_BASE_HANDLE_RADIUS;

// A seta (ArrowHelper) nasce apontando (0,0,1) no espaco local dela - essa e
// a direcao de referencia usada para calcular a rotacao que alinha o
// marcador com um eixo PAXI (PTAXI/PTMIX), ver applyTransformToPoint.
const DEFAULT_ARROW_DIR = new THREE.Vector3(0, 0, 1);

// Constroi o marcador visual de um P-point: uma esfera pequena (alvo de
// clique) na posicao do ponto, com uma seta (THREE.ArrowHelper) apontando na
// direcao (eixo Z local, apos a rotacao) - equivalente visual ao PAXI/PTCDIR
// do catalogo real do E3D.
//
// Assim como nos outros objetos, o topo da arvore precisa ser o proprio Mesh
// (nao um Group) para o raycast nao-recursivo do SelectionManager funcionar;
// a seta e o contorno de selecao ficam como filhos que abrem mao do raycast.
export function createPointMesh(data, resolveParam) {
  const geometry = new THREE.SphereGeometry(HANDLE_RADIUS, 16, 12);
  const material = new THREE.MeshBasicMaterial({
    color: POINT_COLOR,
    transparent: true,
    opacity: 0.85
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = data.name;
  mesh.userData.objType = 'ppoint';
  mesh.userData.refId = data.id;

  const arrow = new THREE.ArrowHelper(
    new THREE.Vector3(0, 0, 1),
    new THREE.Vector3(0, 0, 0),
    ARROW_LENGTH,
    POINT_COLOR,
    ARROW_LENGTH * 0.35,
    ARROW_LENGTH * 0.22
  );
  arrow.raycast = () => {}; // decorativo; a esfera acima e o alvo de clique
  mesh.add(arrow);

  const outline = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.SphereGeometry(HANDLE_RADIUS * 1.3, 8, 6)),
    new THREE.LineBasicMaterial({ color: 0xffaa34 })
  );
  outline.name = 'selection-outline';
  outline.visible = false;
  outline.raycast = () => {};
  mesh.add(outline);

  applyTransformToPoint(mesh, data, resolveParam);
  mesh.visible = data.visible;

  return mesh;
}

// Ids de P-point cuja direcao esta sendo resolvida NESTE MOMENTO (mesma
// pilha de chamadas sincrona) - deteccao de ciclo pra "axis" poder
// referenciar outro P-point (ver utils/axisExpression.js: "PP n"), que por
// sua vez pode referenciar de volta o primeiro. Sem isso, A->B->A entra em
// loop infinito. Se um ciclo e detectado, devolve o eixo padrao (Y) em vez
// de travar - resultado "errado" mas seguro, e o usuario ve o ciclo
// olhando pro proprio modelo (os 2 P-points claramente nao apontam pra
// lugar nenhum coerente).
const resolvingPointIds = new Set();

// Direcao "pura" (sem mexer em mesh nenhum) de um P-point PTAXI/PTMIX/PTCAR -
// resolve `data.axis` (expressao de eixo estilo AVEVA/PTCDIR, ver
// utils/axisExpression.js, que aceita letra composta tipo "Y45X" OU
// referencia a outro P-point "P n"). PTCAR usa o MESMO campo/sintaxe que
// PTAXI/PTMIX - no catalogo real, PTCDIR (do PTCAR) e PAXI (do PTAXI/PTMIX)
// sao a mesma "Defining a Direction" do capitulo 5.5.8 do manual, so com
// nome de atributo diferente (ver persistence/DatalExporter.js). So PTPOS
// continua com rotacao livre (Euler) - e uma representacao so-de-viewport
// pra um subtipo cuja posicao/direcao de verdade sao texto PML livre nao
// interpretado (`positionExpr`/`directionExpr` - ver core/PointStore.js).
export function resolvePointDirection(data, resolveParam = () => undefined) {
  if (data.pointType === 'PTPOS') {
    const quat = new THREE.Quaternion().setFromEuler(
      new THREE.Euler(data.rotation.x * DEG2RAD, data.rotation.y * DEG2RAD, data.rotation.z * DEG2RAD)
    );
    return DEFAULT_ARROW_DIR.clone().applyQuaternion(quat);
  }
  if (resolvingPointIds.has(data.id)) return axisVector(DEFAULT_AXIS); // ciclo detectado - ver comentario acima
  resolvingPointIds.add(data.id);
  try {
    const { direction } = resolveAxisExpression(data.axis);
    return direction ?? axisVector(DEFAULT_AXIS);
  } finally {
    resolvingPointIds.delete(data.id);
  }
}

// Posicao "pura" (sem mexer em mesh nenhum) - extraido pra ser reaproveitado
// por objects/SnapPoints.js (a ferramenta de Cotas precisa da MESMA posicao
// mostrada no viewport, sem duplicar a logica de PTAXI/PTMIX aqui).
export function resolvePointPosition(data, resolveParam = () => undefined) {
  if (data.pointType === 'PTAXI') {
    const distance = resolveNumber(data.distance, resolveParam);
    return resolvePointDirection(data, resolveParam).multiplyScalar(distance);
  }
  return new THREE.Vector3(
    resolveNumber(data.position.x, resolveParam),
    resolveNumber(data.position.y, resolveParam),
    resolveNumber(data.position.z, resolveParam)
  );
}

// Posicao/direcao dependem do subtipo (`pointType` - ver comentario em
// core/PointStore.js):
// - PTAXI: posicao DERIVADA do eixo (PAXI) + distancia (PDIS); direcao e o
//   proprio eixo. `data.position`/`data.rotation` ficam sem uso.
// - PTMIX: posicao explicita (PX/PY/PZ) como o Cartesiano, mas direcao
//   tambem derivada do eixo (`data.rotation` fica sem uso).
// - PTCAR: posicao explicita (PX/PY/PZ) + direcao via expressao de eixo
//   (PTCDIR, mesmo campo `axis` de PTAXI/PTMIX) - `data.rotation` fica sem
//   uso, igual ao PTMIX.
// - PTPOS: posicao explicita + direcao livre (rotacao), so pra
//   representacao no viewport (a posicao/direcao "de verdade" sao texto
//   livre - ver resolvePointDirection).
export function applyTransformToPoint(mesh, data, resolveParam = () => undefined) {
  mesh.position.copy(resolvePointPosition(data, resolveParam));

  if (data.pointType === 'PTPOS') {
    mesh.rotation.set(
      data.rotation.x * DEG2RAD,
      data.rotation.y * DEG2RAD,
      data.rotation.z * DEG2RAD
    );
  } else {
    mesh.quaternion.setFromUnitVectors(DEFAULT_ARROW_DIR, resolvePointDirection(data, resolveParam));
  }
  // Sem scale: P-points nao tem atributo de escala no catalogo real do E3D.
}

export function syncPointMesh(mesh, data, resolveParam) {
  applyTransformToPoint(mesh, data, resolveParam);
  mesh.visible = data.visible;
  mesh.name = data.name;
}

export function setPointSelectionHighlight(mesh, selected, locked) {
  const outline = mesh.getObjectByName('selection-outline');
  if (!outline) return;
  outline.visible = selected;
  outline.material.color.set(locked ? 0xff5c5c : 0xffaa34);
}

export function disposePointMesh(mesh) {
  mesh.geometry.dispose();
  mesh.material.dispose();

  const arrow = mesh.children.find((child) => child.type === 'ArrowHelper');
  if (arrow) {
    arrow.line.geometry.dispose();
    arrow.line.material.dispose();
    arrow.cone.geometry.dispose();
    arrow.cone.material.dispose();
  }

  const outline = mesh.getObjectByName('selection-outline');
  if (outline) {
    outline.geometry.dispose();
    outline.material.dispose();
  }
}
