import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Uma "variante" e um Componente de catalogo (SCOMPONENT) - por exemplo, um
// dos tamanhos de uma familia de suporte (AGT_SDE-37-005JJ/LL/NN no exemplo
// REFERENCIAS/SUPORTE_SDE-37-005.pmlmac). Cada variante tem seu proprio
// conjunto de valores para as definicoes de parametro do ParameterStore - um
// valor por numero de parametro -, exatamente a grade "Name / Gtype / PA1 /
// PA2 / ..." da tela do PARAGON, preenchida pela linha `PARA 50 60.3 ATT ...`
// do SCOMPONENT no .pmlmac.
export function createDefaultVariantData(overrides = {}) {
  return {
    id: createId(),
    name: 'COMPONENTE',
    gtype: 'ATTA',
    values: {}, // { [numeroDoParametro]: 'valor' } - texto livre (numero ou palavra, como ATT)
    ...overrides
  };
}

export class VariantStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
    // A variante ativa e a que expressoes tipo "PARAM 3" resolvem contra -
    // equivalente a escolher qual Componente (JJ/LL/NN) esta sendo editado
    // no PARAGON. So uma variante ativa por vez, global a aplicacao.
    this.activeVariantId = null;
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  setActive(id) {
    if (id !== null && !this.items.has(id)) return;
    if (this.activeVariantId === id) return;
    this.activeVariantId = id;
    this.bus.emit('active-changed', id);
  }

  getActive() {
    return this.activeVariantId ? this.get(this.activeVariantId) : null;
  }

  // Le o valor bruto de um numero de parametro na variante ativa - usado
  // pelo avaliador de expressoes (utils/expressionEvaluator.js).
  resolveParam(number) {
    const active = this.getActive();
    if (!active) return undefined;
    return active.values[number];
  }

  addVariant(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('variant:added', data);
    return data;
  }

  updateVariant(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('variant:updated', updated);
    return updated;
  }

  removeVariant(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('variant:removed', id);
    if (this.activeVariantId === id) this.setActive(null);
  }

  duplicateVariant(id) {
    const source = this.items.get(id);
    if (!source) return null;
    const copy = createDefaultVariantData({
      ...structuredClone(source),
      id: createId(),
      // Sem espacos/parenteses: nomes no E3D nao aceitam esses caracteres.
      name: `${source.name}_copy`
    });
    return this.addVariant(copy);
  }

  clear() {
    [...this.order].forEach((id) => this.removeVariant(id));
  }
}
