// Barra superior: visibilidade do grid + salvar/carregar cena. Mover/
// Rotacionar/Escalar NAO tem botao aqui - viram atalhos de teclado (G/R/S,
// ver core/TransformModeShortcuts.js), o mesmo padrao do editor do three.js/
// Blender; os botoes eram so redundantes com o gizmo ja na tela. As vistas
// padrao (frente/topo/isometrica/etc.) ficam so no gizmo clicavel no canto
// do viewport (ver SceneManager._setupGizmo), pelo mesmo motivo.
export class Toolbar {
  constructor({ container, onToggleGrid, onSave, onLoad, onExportDatal, onCopyDatal, onImportDatal, gridVisible = false }) {
    this.container = container;
    this.onToggleGrid = onToggleGrid;

    container.innerHTML = `
      <button id="grid-toggle-btn" title="Mostrar/ocultar grid">Grid</button>
      <span class="sep"></span>
      <button id="save-scene-btn">Salvar cena</button>
      <button id="load-scene-btn">Carregar cena</button>
      <span class="sep"></span>
      <button id="export-datal-btn" title="Gerar o texto de macro PML (.pmlmac) da CATEGORY - ver persistence/DatalExporter.js">Exportar DATAL</button>
      <button id="copy-datal-btn" title="Copiar o texto de macro PML (.pmlmac) da CATEGORY direto pra area de transferencia">Copiar DATAL</button>
      <button id="import-datal-btn" title="Interpretar um DATAL (.pmlmac) de volta pros dados da aplicacao - ver persistence/DatalImporter.js">Importar DATAL</button>
    `;

    this.gridBtn = container.querySelector('#grid-toggle-btn');
    this.gridBtn.classList.toggle('active', gridVisible);
    this.gridBtn.addEventListener('click', () => this.setGridVisible(!this.gridBtn.classList.contains('active')));

    container.querySelector('#save-scene-btn').addEventListener('click', onSave);
    container.querySelector('#load-scene-btn').addEventListener('click', onLoad);
    container.querySelector('#export-datal-btn').addEventListener('click', onExportDatal);
    container.querySelector('#import-datal-btn').addEventListener('click', onImportDatal);

    // Feedback visual de "Copiado!" (ver handleCopyDatal em main.js) - so
    // troca o texto do botao por um instante, sem afetar o export-datal-btn.
    this.copyDatalBtn = container.querySelector('#copy-datal-btn');
    this.copyDatalBtn.addEventListener('click', async () => {
      const ok = await onCopyDatal();
      const original = 'Copiar DATAL';
      this.copyDatalBtn.textContent = ok ? 'Copiado!' : 'Falhou ao copiar';
      setTimeout(() => {
        this.copyDatalBtn.textContent = original;
      }, 1500);
    });
  }

  setGridVisible(visible) {
    this.gridBtn.classList.toggle('active', visible);
    this.onToggleGrid(visible);
  }
}
