import { EventBus } from '../utils/EventBus.js';

// Metadados da CATEGORY do catalogo (ver capitulo 7/8 do manual de
// referencia e os exemplos em REFERENCIAS/*.pmlmac) - ao contrario dos
// outros stores, NAO e uma lista: existe um unico registro por cena (uma
// cena deste app = uma familia de suporte = uma CATEGORY, com uma
// SCOMPONENT por variante do VariantStore). Usado pelo exportador de DATAL
// (persistence/DatalExporter.js) para montar `NEW CATEGORY /<name>` +
// `NEW SDTEXT /<name>-D`.
//
// GTYP fica FIXO em 'ATTA' (nao e um campo editavel) - decisao explicita do
// usuario: este app e focado em suportes (Support), que no catalogo real
// sempre usam esse generic type. PURP tambem fica fixo em 'COMP' (Component),
// igual aos 2 exemplos reais - nenhum dos dois varia entre suportes.
export const CATEGORY_GTYPE = 'ATTA';
export const CATEGORY_PURPOSE = 'COMP';

export function createDefaultCategoryData(overrides = {}) {
  return {
    name: '', // vira /<name> (CATEGORY), /<name>-D (SDTEXT), /<name>-PT (PTSET), /<name>-GM (GMSET), /<name>-DTS (DTSET)
    description: '', // DESC da CATEGORY - tambem usado como RTEX do SDTEXT (os 2 exemplos reais usam o MESMO texto nos dois lugares)
    ...overrides
  };
}

// Sem lista/order (so um registro) - mais simples que copiar o padrao
// Map+order dos outros stores para um unico objeto.
export class CategoryStore {
  constructor() {
    this.bus = new EventBus();
    this.data = createDefaultCategoryData();
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  get() {
    return this.data;
  }

  update(patch) {
    this.data = { ...this.data, ...patch };
    this.bus.emit('category:updated', this.data);
    return this.data;
  }

  replace(data) {
    this.data = createDefaultCategoryData(data ?? {});
    this.bus.emit('category:updated', this.data);
    return this.data;
  }
}
