import { EventBus } from '../utils/EventBus.js';

// Selecao compartilhada entre referencias e primitivas: apenas um objeto pode
// estar selecionado por vez em toda a cena, independente do tipo. Os stores
// (ReferenceStore, PrimitiveStore) guardam dados; este modelo so guarda
// "quem esta selecionado agora" como { type, id }.
export class SelectionModel {
  constructor() {
    this.bus = new EventBus();
    this.current = null; // { type: 'reference' | 'primitive', id } | null
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  select(type, id) {
    if (this.current && this.current.type === type && this.current.id === id) return;
    this.current = type && id ? { type, id } : null;
    this.bus.emit('changed', this.current);
  }

  clear() {
    this.select(null, null);
  }

  clearIfSelected(type, id) {
    if (this.current && this.current.type === type && this.current.id === id) {
      this.clear();
    }
  }

  isSelected(type, id) {
    return !!this.current && this.current.type === type && this.current.id === id;
  }
}
