import { createCollapsibleSection } from './CollapsibleSection.js';
import { createDefaultDatasetEntryData, despPproFor, isAutoGeneratedDespPpro } from '../core/DatasetStore.js';
import { isParametric, needsExpressionHint, evaluateExpression, hasInchLiteral, convertInchLiterals } from '../utils/expressionEvaluator.js';

// Normaliza um literal em polegada (ex.: "16in") pro numero em mm assim que
// o campo perde o foco OU quando aperta Enter (sem clicar em outro lugar
// depois, 'change' sozinho nao dispara - ver comentario completo em
// ui/PropertiesPanel.js: _attachInchNormalization). Repetido aqui em vez de
// importado porque manipula o DOM local do painel, nao vale a pena um
// modulo compartilhado so pra isso.
function _attachInchNormalization(input) {
  if (!input) return;
  const normalize = () => {
    if (hasInchLiteral(input.value)) {
      input.value = convertInchLiterals(input.value);
      input.dispatchEvent(new Event('input', { bubbles: true }));
    }
  };
  input.addEventListener('change', normalize);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      normalize();
    }
  });
}

// PTYP e so informativo (nao afeta a avaliacao da expressao) - ajuda a
// documentar que tipo de grandeza aquela entrada representa.
const PTYP_OPTIONS = ['DIST', 'BORE', 'ANGL', 'TEXT', 'DATA'];

// PURP - ver capitulo 8.1 do manual de referencia: PARA (parametro de
// catalogo), DESP (parametro de projetista/design), DATA (propriedade generica).
const PURP_OPTIONS = ['PARA', 'DESP', 'DATA'];

// Painel lateral esquerdo: Datasets (DTSET/DATA do catalogo real - ver
// capitulo 8 "Creating Datasets in PARAGON" do manual de referencia, e o
// exemplo real em REFERENCIAS/SUPORTE_SDE-37-005.pmlmac). Cada entrada tem
// campos demais para caber numa tabela na barra lateral estreita, entao cada
// uma vira um "cartao" colapsavel: recolhida mostra so DKEY/PURP + o valor
// resolvido (pra escanear muitas entradas rapido); expandida mostra
// DTIT/PPRO/DPRO/PTYP/NUMB para editar.
//
// A funcionalidade central: qualquer campo de expressao no app (dimensao,
// posicao, PCON/PBOR, distancia de PTAXI) pode referenciar uma entrada daqui
// via "RPRO <dkey>" em vez de repetir a mesma expressao em varios lugares -
// ver utils/expressionEvaluator.js (RPRO_TOKEN) e core/DatasetStore.js.
export class DatasetsPanel {
  constructor({ container, datasetStore, variantStore, parameterStore }) {
    this.datasetStore = datasetStore;
    this.variantStore = variantStore;
    this.parameterStore = parameterStore;
    this.resolveParam = (number) => this.variantStore.resolveParam(number);
    this.expandedIds = new Set(); // quais cartoes estao abertos - sobrevive a re-renders

    const { bodyEl } = createCollapsibleSection({ container, title: 'Datasets', defaultExpanded: false });
    this.container = bodyEl;

    this.container.innerHTML = `
      <button id="add-dataset-entry-btn" class="add-entity-btn full-add-btn">+ Adicionar entrada</button>
      <div id="dataset-entries"></div>
      <div id="dataset-empty" class="empty-state">
        Nenhuma entrada de Dataset. Uma entrada tem um valor (PPRO) que pode ser
        referenciado em qualquer campo de expressao com "RPRO &lt;dkey&gt;" em vez de
        repetir a mesma formula em varios lugares.
      </div>
    `;
    this.entriesEl = this.container.querySelector('#dataset-entries');
    this.emptyEl = this.container.querySelector('#dataset-empty');

    this.container.querySelector('#add-dataset-entry-btn').addEventListener('click', () => {
      const nextLetter = String.fromCharCode(65 + (this.datasetStore.list().length % 26));
      const entry = createDefaultDatasetEntryData({ dkey: nextLetter });
      this.expandedIds.add(entry.id); // uma entrada nova nasce aberta, pronta pra editar
      this.datasetStore.addEntry(entry);
    });

    // "added"/"removed" mudam a ESTRUTURA (quantidade de cartoes) - precisam
    // de rebuild completo. "updated" so muda VALORES (dispara a cada tecla
    // digitada em PPRO/DPRO, que usam 'input' para a dica atualizar ao
    // vivo) - rebuild completo ali reconstruiria o input focado a cada
    // tecla, jogando o cursor pro fim do campo (mesmo problema que
    // PropertiesPanel._setIfNotFocused evita em outro lugar). Por isso
    // "updated" so atualiza valores nos elementos JA existentes.
    datasetStore.on('dataset:added', () => this.render());
    datasetStore.on('dataset:updated', (data) => this._refreshEntryValues(data));
    datasetStore.on('dataset:removed', () => this.render());

    const refreshHints = () => this._refreshAllHints();
    variantStore.on('active-changed', refreshHints);
    variantStore.on('variant:updated', refreshHints);
    parameterStore.on('parameter:added', refreshHints);
    parameterStore.on('parameter:updated', refreshHints);
    parameterStore.on('parameter:removed', refreshHints);

    this.render();
  }

  render() {
    const active = document.activeElement;
    const focusedField = active?.dataset?.entryField;
    const focusedId = active?.dataset?.entryId;

    const items = this.datasetStore.list();
    this.emptyEl.style.display = items.length ? 'none' : 'block';
    this.entriesEl.innerHTML = '';
    items.forEach((item) => this.entriesEl.appendChild(this._buildEntryCard(item)));

    // Reforca o foco apos o re-render (que recria todo o DOM) - senao o
    // usuario perde o cursor a cada tecla digitada num campo.
    if (focusedId && focusedField) {
      const el = this.entriesEl.querySelector(`[data-entry-id="${focusedId}"][data-entry-field="${focusedField}"]`);
      el?.focus();
    }

    this._refreshAllHints();
  }

  _refreshEntryValues(item) {
    const card = this.entriesEl.querySelector(`[data-card-id="${item.id}"]`);
    if (!card) return;
    const active = document.activeElement;
    const setIfNotFocused = (field, value) => {
      const el = card.querySelector(`[data-entry-field="${field}"]`);
      if (el && el !== active) el.value = value;
    };
    setIfNotFocused('dkey', item.dkey);
    setIfNotFocused('purp', item.purp);
    setIfNotFocused('dtit', item.dtit);
    setIfNotFocused('ppro', item.ppro);
    setIfNotFocused('dpro', item.dpro);
    setIfNotFocused('ptyp', item.ptyp);
    setIfNotFocused('numb', item.number ?? '');
    this._applyPproDespHint(card, item.purp);
    this._refreshAllHints();
  }

  // PURP DESP (parametro de projetista, digitado ao posicionar o componente -
  // ver capitulo 8.1 do manual): no PARAGON de verdade o PPRO desse tipo de
  // entrada e GERADO a partir do NUMB ("ATTRIB DESP[n ]", mesmo padrao ja
  // usado por PARAM/PARA) - decisao explicita do usuario: PPRO tem que
  // EXISTIR de verdade no store (nao so no texto exportado), pra bater com o
  // catalogo real. Isso e seguro porque `DatasetStore.resolveDkey` agora
  // TESTA se PPRO resolve pra um numero antes de usa-lo - se nao resolver
  // (como e sempre o caso do texto bruto "ATTRIB DESP[n ]", que
  // evaluateExpression nao consegue calcular), cai pro DPRO automaticamente,
  // que fica sendo o valor de PREVIEW de verdade usado pelo app. Por isso o
  // campo PPRO fica DESABILITADO (so leitura) quando PURP=DESP - o valor e
  // sempre o que `_despPproFor` gerou a partir de NUMB, nunca digitado a
  // mao. BUG REAL ja corrigido 2x nessa area: 1a vez escreveu o texto bruto
  // no `ppro` mas a RESOLUCAO ainda dava prioridade cega a PPRO (quebrava
  // toda primitiva que referenciava a entrada via RPRO); 2a vez (fix
  // errado, oposto) parou de escrever em `ppro` de vez, mas isso deixava o
  // PPRO faltando no DATAL exportado e nao refletia o catalogo real. A
  // correcao definitiva mantem PPRO sempre preenchido/atualizado a partir de
  // NUMB E corrige a RESOLUCAO pra pular um PPRO que nao seja numero de
  // verdade (ver DatasetStore.resolveDkey) - os 2 lados da mesma moeda.
  // `despPproFor` mora em core/DatasetStore.js (compartilhado com
  // `resolveDkey`, que precisa reconhecer esse MESMO padrao pra dar um erro
  // claro em vez do erro cru do parser - ver comentario la).

  _applyPproDespHint(card, purp) {
    const pproInput = card.querySelector('[data-entry-field="ppro"]');
    const pproLabel = card.querySelector('[data-ppro-label]');
    const dproLabel = card.querySelector('[data-dpro-label]');
    if (!pproInput || !pproLabel || !dproLabel) return;
    const isDesp = purp === 'DESP';
    pproInput.disabled = isDesp;
    pproLabel.textContent = isDesp
      ? 'Valor (PPRO) - gerado automaticamente a partir de NUMB (ATTRIB DESP[n]) - o app usa o DPRO abaixo pra preview, ja que este texto nao e um numero'
      : 'Valor (PPRO) - aceita expressao, ex.: "PARAM 3"';
    // DPRO pra uma entrada DESP e OPCIONAL - varias entradas reais do
    // catalogo sao so informativas, sem valor padrao nenhum (confirmado
    // pelo usuario: "nao possui valor default... era feito assim no
    // passado"). Preencher aqui so serve pra ver um preview 3D NESTA
    // ferramenta - nao afeta o DATAL exportado nem e obrigatorio.
    dproLabel.textContent = isDesp
      ? 'Padrao (DPRO) - opcional: numero so pra habilitar o preview 3D aqui na ferramenta (o valor de verdade e digitado pelo projetista no design real)'
      : 'Padrao (DPRO) - usado se PPRO ficar vazio ou nao resolver';
  }

  _toggleExpanded(id) {
    if (this.expandedIds.has(id)) this.expandedIds.delete(id);
    else this.expandedIds.add(id);
    const card = this.entriesEl.querySelector(`[data-card-id="${id}"]`);
    if (!card) return;
    const expanded = this.expandedIds.has(id);
    card.classList.toggle('dataset-entry-expanded', expanded);
    card.querySelector('.dataset-entry-toggle').textContent = expanded ? '▾' : '▸';
    card.querySelector('.dataset-entry-body').hidden = !expanded;
  }

  _buildEntryCard(item) {
    const expanded = this.expandedIds.has(item.id);
    const card = document.createElement('div');
    card.className = `dataset-entry${expanded ? ' dataset-entry-expanded' : ''}`;
    card.dataset.cardId = item.id;
    card.innerHTML = `
      <div class="dataset-entry-header prop-row">
        <button type="button" class="icon-btn dataset-entry-toggle" data-action="toggle" title="Expandir/recolher">${expanded ? '▾' : '▸'}</button>
        <div class="axis-field">
          <span class="axis-tag">DKEY</span>
          <input type="text" class="dataset-dkey-input" data-entry-id="${item.id}" data-entry-field="dkey" />
        </div>
        <select class="full dataset-purp-select" data-entry-id="${item.id}" data-entry-field="purp">
          ${PURP_OPTIONS.map((opt) => `<option value="${opt}">${opt}</option>`).join('')}
        </select>
        <button type="button" class="icon-btn" data-action="delete" title="Excluir entrada">✕</button>
      </div>
      <div class="dataset-entry-summary" data-summary-for="${item.id}"></div>
      <div class="dataset-entry-body" ${expanded ? '' : 'hidden'}>
        <div class="prop-group">
          <label class="prop-label">Titulo (DTIT)</label>
          <input type="text" class="full" data-entry-id="${item.id}" data-entry-field="dtit" />
        </div>
        <div class="prop-group">
          <label class="prop-label" data-ppro-label="${item.id}">Valor (PPRO) - aceita expressao, ex.: "PARAM 3"</label>
          <input type="text" class="full" data-entry-id="${item.id}" data-entry-field="ppro" />
          <div class="expr-hint" data-entry-id="${item.id}" data-hint-field="ppro"></div>
        </div>
        <div class="prop-group">
          <label class="prop-label" data-dpro-label="${item.id}">Padrao (DPRO) - usado se PPRO ficar vazio</label>
          <input type="text" class="full" data-entry-id="${item.id}" data-entry-field="dpro" />
          <div class="expr-hint" data-entry-id="${item.id}" data-hint-field="dpro"></div>
        </div>
        <div class="prop-row">
          <div class="axis-field">
            <span class="axis-tag">PTYP</span>
            <select data-entry-id="${item.id}" data-entry-field="ptyp">
              ${PTYP_OPTIONS.map((opt) => `<option value="${opt}">${opt}</option>`).join('')}
            </select>
          </div>
          <div class="axis-field">
            <span class="axis-tag">NUMB</span>
            <input type="number" step="1" data-entry-id="${item.id}" data-entry-field="numb" />
          </div>
        </div>
      </div>
    `;

    card.querySelector('[data-entry-field="dkey"]').value = item.dkey;
    card.querySelector('[data-entry-field="purp"]').value = item.purp;
    card.querySelector('[data-entry-field="dtit"]').value = item.dtit;
    card.querySelector('[data-entry-field="ppro"]').value = item.ppro;
    card.querySelector('[data-entry-field="dpro"]').value = item.dpro;
    card.querySelector('[data-entry-field="ptyp"]').value = item.ptyp;
    card.querySelector('[data-entry-field="numb"]').value = item.number ?? '';
    this._applyPproDespHint(card, item.purp);

    card.querySelector('[data-entry-field="dkey"]').addEventListener('change', (e) => {
      const value = e.target.value.trim().toUpperCase();
      if (value) this.datasetStore.updateEntry(item.id, { dkey: value });
    });
    card.querySelector('[data-entry-field="purp"]').addEventListener('change', (e) => {
      const purp = e.target.value;
      const patch = { purp };
      // PURP DESP - PPRO passa a ser GERADO a partir de NUMB (ver
      // _despPproFor/_applyPproDespHint acima), igual ao PARAGON de
      // verdade.
      if (purp === 'DESP') {
        const fresh = this.datasetStore.get(item.id);
        patch.ppro = despPproFor(fresh?.number);
      }
      this.datasetStore.updateEntry(item.id, patch);
      this._applyPproDespHint(card, purp);
    });
    card.querySelector('[data-entry-field="dtit"]').addEventListener('change', (e) => {
      this.datasetStore.updateEntry(item.id, { dtit: e.target.value });
    });
    card.querySelector('[data-entry-field="ppro"]').addEventListener('input', (e) => {
      this.datasetStore.updateEntry(item.id, { ppro: e.target.value });
    });
    card.querySelector('[data-entry-field="dpro"]').addEventListener('input', (e) => {
      this.datasetStore.updateEntry(item.id, { dpro: e.target.value });
    });
    _attachInchNormalization(card.querySelector('[data-entry-field="ppro"]'));
    _attachInchNormalization(card.querySelector('[data-entry-field="dpro"]'));
    card.querySelector('[data-entry-field="ptyp"]').addEventListener('change', (e) => {
      this.datasetStore.updateEntry(item.id, { ptyp: e.target.value });
    });
    card.querySelector('[data-entry-field="numb"]').addEventListener('change', (e) => {
      const raw = e.target.value === '' ? null : Number(e.target.value);
      const number = Number.isNaN(raw) ? null : raw;
      const patch = { number };
      // Reflete o NUMB novo no PPRO derivado (ver _despPproFor) quando esta
      // entrada e PURP DESP - o mesmo raciocinio do handler de "purp" acima.
      const fresh = this.datasetStore.get(item.id);
      if (fresh?.purp === 'DESP') patch.ppro = despPproFor(number);
      this.datasetStore.updateEntry(item.id, patch);
    });
    card.querySelector('[data-action="delete"]').addEventListener('click', () => {
      this.expandedIds.delete(item.id);
      this.datasetStore.removeEntry(item.id);
    });
    card.querySelector('[data-action="toggle"]').addEventListener('click', () => this._toggleExpanded(item.id));
    card.querySelector('.dataset-entry-summary').addEventListener('click', () => this._toggleExpanded(item.id));

    return card;
  }

  // Mesma logica de dica de PropertiesPanel._refreshExpressionHints: separa
  // "nenhuma variante ativa" (so relevante se o campo de fato referencia
  // PARAM) de "parametro sem valor na variante ativa", e mostra "-> valor"
  // quando resolve com sucesso. Roda pros campos internos (PPRO/DPRO, so
  // existem no DOM se o cartao estiver expandido) E pro resumo do cabecalho
  // (sempre visivel, mesmo recolhido - por isso tem sua propria funcao, que
  // ao contrario da dica de campo tambem mostra literais puros, ja que o
  // input de PPRO em si fica escondido quando o cartao esta recolhido).
  _refreshAllHints() {
    const activeVariant = this.variantStore.getActive();

    this.entriesEl.querySelectorAll('.expr-hint').forEach((hintEl) => {
      const item = this.datasetStore.get(hintEl.dataset.entryId);
      const raw = item?.[hintEl.dataset.hintField];
      if (!needsExpressionHint(raw)) {
        hintEl.textContent = '';
        hintEl.title = '';
        hintEl.classList.remove('expr-error');
        return;
      }
      const { text, isError } = this._resolveDisplayValue(raw, activeVariant);
      hintEl.textContent = text;
      hintEl.title = isError ? text : '';
      hintEl.classList.toggle('expr-error', isError);
    });

    this.entriesEl.querySelectorAll('.dataset-entry-summary').forEach((summaryEl) => {
      const item = this.datasetStore.get(summaryEl.dataset.summaryFor);
      if (!item) return;
      const title = item.dtit?.trim();
      // Mesma prioridade de core/DatasetStore.js: resolveDkey - PPRO primeiro,
      // SO SE resolver pra um numero de verdade; senao cai pro DPRO. BUG REAL
      // corrigido 2x aqui: 1a vez o resumo olhava SO `ppro`, mostrando "(sem
      // PPRO)" mesmo com `dpro` preenchido e em uso; 2a vez (ao reinstaurar o
      // PPRO auto-gerado a partir de NUMB pra entradas PURP=DESP) o resumo
      // usava "ppro nao-vazio => usa ppro" sem TESTAR se aquele texto
      // realmente resolvia - uma entrada DESP tem PPRO SEMPRE preenchido
      // ("ATTRIB DESP[n ]", nunca calculavel), entao o resumo voltava a
      // mostrar "Expressao invalida" mesmo com o DPRO certo sendo usado de
      // verdade pelas primitivas.
      const pproRaw = String(item.ppro ?? '').trim();
      const dproRaw = String(item.dpro ?? '').trim();
      const pproResult = pproRaw === '' ? null : this._resolveDisplayValue(pproRaw, activeVariant);
      const pproUsable = pproResult !== null && !pproResult.isError;
      let text;
      let isError;
      if (pproUsable) {
        ({ text, isError } = pproResult);
      } else if (dproRaw !== '') {
        ({ text, isError } = this._resolveDisplayValue(dproRaw, activeVariant));
      } else if (isAutoGeneratedDespPpro(item)) {
        // So pra PURP=DESP com o PPRO auto-gerado (ver core/DatasetStore.js:
        // isAutoGeneratedDespPpro) - troca o erro cru de parser ("Expressao
        // invalida", tecnicamente correto mas nao acionavel) por uma
        // mensagem clara. NAO e um erro de configuracao (`isError: false`,
        // sem estilo vermelho) - e um padrao LEGITIMO do catalogo real:
        // parametro so informativo, sem valor padrao nenhum (confirmado
        // pelo usuario contra REFERENCIAS/dataset1.pmlmac - "nao possui
        // valor default... era feito assim no passado"). DPRO aqui e
        // OPCIONAL, so pra habilitar um preview 3D dentro desta ferramenta.
        // Pra QUALQUER outro PURP, mantem o erro de verdade do pproResult
        // (`PARAM sem variante ativa`, expressao malformada, etc.) - nao
        // esconder um erro real atras dessa mensagem quando o problema e
        // outro.
        text = 'ℹ Parametro informativo (sem valor padrao) - preencha o DPRO se quiser um preview 3D';
        isError = false;
      } else if (pproRaw !== '') {
        ({ text, isError } = pproResult);
      } else {
        text = '(sem PPRO nem DPRO)';
        isError = false;
      }
      summaryEl.textContent = title ? `${title} — ${text}` : text;
      summaryEl.title = isError ? text : '';
      summaryEl.classList.toggle('expr-error', isError);
    });
  }

  // Resolve um campo de expressao para o texto de exibicao: valor calculado
  // ("→ 63.5"), o proprio literal ("200"), ou uma mensagem de erro/aviso.
  _resolveDisplayValue(raw, activeVariant) {
    if (isParametric(raw) && !activeVariant) {
      return { text: '⚠ Nenhuma variante ativa selecionada (painel Parametros)', isError: true };
    }

    // Texto literal puro (sem PARAM/RPRO/polegada e sem nenhum digito) NAO e
    // uma expressao pra resolver - e um VALOR de texto legitimo (PTYP=TEXT,
    // ver capitulo 8.1 do manual: PPRO pode guardar uma propriedade textual,
    // so que sem RPRO funcionar sobre ela - "so caminho numerico suportado",
    // ver CLAUDE.md). BUG REAL corrigido: `evaluateExpression` SEMPRE falha
    // pra texto assim (nao ha nenhum numero pra extrair), e o resumo do
    // Dataset mostrava esse erro colado logo apos o titulo (DTIT) na mesma
    // linha ("TITULO — ⚠ Expressao invalida"), dando a falsa impressao de
    // que o proprio DTIT (um campo so-texto, nunca calculado) estava
    // invalido. Mostra o texto como esta, sem tentar avaliar.
    if (!needsExpressionHint(raw) && !/\d/.test(raw)) {
      return { text: raw, isError: false };
    }

    const { value, isNumber, error } = evaluateExpression(raw, this.resolveParam);
    if (error) {
      const missing = error.match(/^Parametro (\d+) nao encontrado/);
      return {
        text: missing ? `⚠ PA${missing[1]} sem valor na variante ativa ("${activeVariant.name}")` : `⚠ ${error}`,
        isError: true
      };
    }
    return { text: `→ ${isNumber ? Math.round(value * 1000) / 1000 : value}`, isError: false };
  }
}
