import * as THREE from 'three';
import { loadImageElement, applyWhiteAsAlpha } from '../utils/textureProcessing.js';
import { DEG2RAD } from '../utils/transformMath.js';
import { resolveNumber } from '../utils/expressionEvaluator.js';

const textureLoader = new THREE.TextureLoader();

// Constroi a textura do plano a partir do dataURL original. Quando
// `whiteAsAlpha` esta ativo, os pixels sao reprocessados em um canvas:
// branco vira transparente e qualquer outra cor vira preto solido - util
// para sobrepor desenhos tecnicos (fundo branco, linhas pretas) sem que o
// fundo branco esconda outros planos/grid atras dele.
async function buildTexture(data) {
  if (!data.fileData) return null;

  if (!data.whiteAsAlpha) {
    const texture = await textureLoader.loadAsync(data.fileData);
    texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
  }

  const img = await loadImageElement(data.fileData);
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  applyWhiteAsAlpha(ctx, canvas.width, canvas.height);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

// Constroi o Object3D (plano + contorno de selecao) correspondente a um item
// de dados. Geometria e textura sao proprias de cada plano, conforme exigido.
export async function createReferencePlaneMesh(data, resolveParam) {
  const geometry = new THREE.PlaneGeometry(data.width, data.height);

  const material = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    transparent: true,
    // "transparent:true" sozinho NAO desativa a escrita no depth buffer -
    // sem isso, ate os pixels totalmente transparentes (branco virado alpha
    // 0, ver whiteAsAlpha) continuam gravando profundidade e escondendo
    // primitivas/pontos atras do plano, mesmo parecendo invisiveis.
    depthWrite: false,
    opacity: data.opacity,
    toneMapped: false
  });

  material.map = await buildTexture(data);
  material.needsUpdate = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = data.name;
  mesh.userData.objType = 'reference';
  mesh.userData.refId = data.id;
  mesh.userData.whiteAsAlpha = data.whiteAsAlpha;

  const outline = new THREE.LineSegments(
    new THREE.EdgesGeometry(geometry),
    new THREE.LineBasicMaterial({ color: 0xffaa34 })
  );
  outline.name = 'selection-outline';
  outline.visible = false;
  outline.raycast = () => {}; // nunca deve interceptar cliques/raycasts
  mesh.add(outline);

  applyTransformToMesh(mesh, data, resolveParam);
  mesh.visible = data.visible;

  return mesh;
}

// `resolveParam` resolve referencias a parametro ("PARAM n") na posicao (ver
// VariantStore.resolveParam); pode ser omitido quando nao ha variante ativa
// para resolver ainda (a posicao so cai para o fallback 0 nesse caso).
export function applyTransformToMesh(mesh, data, resolveParam = () => undefined) {
  mesh.position.set(
    resolveNumber(data.position.x, resolveParam),
    resolveNumber(data.position.y, resolveParam),
    resolveNumber(data.position.z, resolveParam)
  );
  mesh.rotation.set(
    data.rotation.x * DEG2RAD,
    data.rotation.y * DEG2RAD,
    data.rotation.z * DEG2RAD
  );
  mesh.scale.set(data.scale.x, data.scale.y, data.scale.z);
}

// Sincroniza um mesh ja existente com o estado atual dos dados (chamado sempre
// que o ReferenceStore emite 'reference:updated').
export function syncMeshWithData(mesh, data, resolveParam) {
  applyTransformToMesh(mesh, data, resolveParam);
  mesh.visible = data.visible;
  mesh.name = data.name;
  if (mesh.material.opacity !== data.opacity) {
    mesh.material.opacity = data.opacity;
  }
}

// Regenera a textura do mesh (chamado apenas quando `whiteAsAlpha` muda -
// e uma operacao mais cara que o resto do sync, entao nao deve rodar a cada
// atualizacao de transformacao).
export async function updateMeshTexture(mesh, data) {
  const oldTexture = mesh.material.map;
  mesh.material.map = await buildTexture(data);
  mesh.material.needsUpdate = true;
  if (oldTexture) oldTexture.dispose();
}

export function setSelectionHighlight(mesh, selected, locked) {
  const outline = mesh.getObjectByName('selection-outline');
  if (!outline) return;
  outline.visible = selected;
  outline.material.color.set(locked ? 0xff5c5c : 0xffaa34);
}

export function disposeMesh(mesh) {
  mesh.geometry.dispose();
  if (mesh.material.map) mesh.material.map.dispose();
  mesh.material.dispose();
  const outline = mesh.getObjectByName('selection-outline');
  if (outline) {
    outline.geometry.dispose();
    outline.material.dispose();
  }
}

