// Merge raso por chave, com merge recursivo de sub-objetos simples (ex.:
// { position: { x } } aplicado sobre um objeto que ja tem position completo).
// Usado pelos stores (ReferenceStore, PrimitiveStore) para aplicar patches
// parciais sem exigir que o chamador reenvie o objeto inteiro.
export function deepMerge(target, patch) {
  const result = { ...target };
  for (const key of Object.keys(patch)) {
    const value = patch[key];
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      result[key] = { ...target[key], ...value };
    } else {
      result[key] = value;
    }
  }
  return result;
}
