import { createId } from '../utils/id.js';
import { CATEGORY_GTYPE } from '../core/CategoryStore.js';

// Interpretador inverso de "DATAL" - pega o texto de macro PML (.pmlmac) de
// uma CATEGORY do E3D (o MESMO formato que persistence/DatalExporter.js
// gera, mas tambem arquivos de verdade exportados pelo PARAGON - ver
// REFERENCIAS/*.pmlmac) e reconstroi, o MAXIMO possivel, os dados dos 7
// stores da aplicacao (Category/Parameter/Variant/Dataset/Point/Primitive -
// Cota/Reference nao tem equivalente no DATAL, ficam de fora). E o espelho
// exato do DatalExporter.js: cada tabela de mapeamento aqui e a MESMA
// tabela usada la, so invertida - qualquer mudanca de formato num dos dois
// arquivos tem que ser replicada no outro.
//
// Filosofia de "melhor esforco com avisos" (pedido explicito do usuario):
// isto NAO e um parser de PML completo (PML e uma linguagem de macro de
// verdade, com variavel/condicional/etc. - fora de escopo). So o
// subconjunto DECLARATIVO plano (blocos NEW/END aninhados com linhas de
// atributo) usado pelos 2 exemplos reais e' suportado. Qualquer coisa fora
// disso (bloco nao reconhecido, tipo de primitiva/P-point sem exemplo real
// confirmado - ver UNVERIFIED_* abaixo, expressao com referencia a Dataset
// que nao existe) gera um AVISO em vez de falhar silenciosamente ou travar
// a importacao inteira. `parseDatal` nunca lanca excecao por dado malformado
// dentro do DATAL - erros de sintaxe genuinamente irrecuperaveis (nenhum
// bloco CATEGORY encontrado) devolvem `{ error }` em vez de warnings.

// ---------------------------------------------------------------------------
// Tokenizacao: junta continuacao de linha (PML usa "$" no fim da linha pra
// continuar na proxima - usado pelos exemplos reais na lista de valores PARA
// de um SCOMPONENT quando tem muitos parametros) e descarta linhas em branco.
// ---------------------------------------------------------------------------
function splitLines(text) {
  const rawLines = String(text ?? '').replace(/\r\n/g, '\n').split('\n');
  const merged = [];
  let buffer = null;
  for (const rawLine of rawLines) {
    const line = rawLine.trim();
    buffer = buffer === null ? line : `${buffer} ${line}`;
    if (buffer.endsWith('$')) {
      buffer = buffer.slice(0, -1).trim();
      continue; // continua acumulando na proxima linha fisica
    }
    if (buffer !== '') merged.push(buffer);
    buffer = null;
  }
  if (buffer !== null && buffer !== '') merged.push(buffer);
  return merged;
}

// Bloco generico: { keyword, name, attrs: [{key, raw}], children: [bloco] } -
// espelha a funcao `block()` do DatalExporter.js (que monta `NEW <header>` +
// linhas de atributo + blocos filhos + `END`), so de tras pra frente.
function parseBlocks(lines) {
  let i = 0;

  function parseAttrLine(line) {
    const spaceIdx = line.indexOf(' ');
    if (spaceIdx === -1) return { key: line, raw: '' };
    return { key: line.slice(0, spaceIdx), raw: line.slice(spaceIdx + 1).trim() };
  }

  function parseBlock() {
    const header = lines[i].slice(4).trim(); // remove o "NEW " inicial
    i++;
    const spaceIdx = header.indexOf(' ');
    const keyword = (spaceIdx === -1 ? header : header.slice(0, spaceIdx)).toUpperCase();
    const name = spaceIdx === -1 ? null : header.slice(spaceIdx + 1).trim();
    const attrs = [];
    const children = [];
    while (i < lines.length && lines[i] !== 'END') {
      if (lines[i].startsWith('NEW ')) {
        children.push(parseBlock());
      } else {
        attrs.push(parseAttrLine(lines[i]));
        i++;
      }
    }
    if (i < lines.length && lines[i] === 'END') i++; // consome o END deste bloco
    return { keyword, name, attrs, children };
  }

  const blocks = [];
  while (i < lines.length) {
    if (lines[i].startsWith('NEW ')) {
      blocks.push(parseBlock());
    } else {
      i++; // "INPUT BEGIN"/"OLD ..."/"PTRE ..."/"INPUT END ..." - so metadados redundantes, ja cobertos pelo aninhamento NEW/END
    }
  }
  return blocks;
}

function attrValue(block, key) {
  const found = block.attrs.find((a) => a.key.toUpperCase() === key.toUpperCase());
  return found ? found.raw : null;
}

// Remove aspas simples + desfaz o escape '' -> ' (mesma convencao de
// escapeQuote no DatalExporter.js, invertida).
function unquote(raw) {
  if (raw === null) return '';
  const trimmed = raw.trim();
  if (!trimmed.startsWith("'")) return trimmed;
  const inner = trimmed.endsWith("'") && trimmed.length > 1 ? trimmed.slice(1, -1) : trimmed.slice(1);
  return inner.replace(/''/g, "'");
}

function stripOuterParens(text) {
  const t = text.trim();
  if (t.startsWith('(') && t.endsWith(')')) return t.slice(1, -1).trim();
  return t;
}

// ---------------------------------------------------------------------------
// Reversao de expressao - espelha pmlExpr/pmlExprForDataset do
// DatalExporter.js. "ATTRIB DESP[n ]" e um caso especial: NAO existe no
// modelo de expressao do app (so existe como PPRO auto-gerado de uma entrada
// de Dataset com PURP=DESP - ver core/DatasetStore.js) - por isso, ao
// encontrar essa referencia DENTRO de uma expressao qualquer (posicao,
// dimensao, eixo...), o importador troca pelo "RPRO <dkey>" da entrada de
// Dataset correspondente (mesmo NUMB), que e semanticamente equivalente
// dentro do app. Precisa rodar ANTES de ATTRIB PARA (padroes parecidos).
// ---------------------------------------------------------------------------
const BARE_PARAM_PML_RE = /^PARAM\s+(\d+)$/i;
const ATTRIB_DESP_RE = /ATTRIB\s+DESP\s*\[\s*(\d+)\s*\]/gi;
const ATTRIB_PARA_RE = /ATTRIB\s+PARA\s*\[\s*(\d+)\s*\]/gi;
const RPROP_RE = /RPROP?\s+([A-Za-z][A-Za-z0-9_]*)/gi;

function fromPmlExpr(raw, ctx, context) {
  if (raw === null) return '';
  const trimmed = raw.trim();
  if (trimmed === '') return '';

  const bare = trimmed.match(BARE_PARAM_PML_RE);
  if (bare) return `PARAM ${bare[1]}`;

  let working = stripOuterParens(trimmed);
  working = working.replace(ATTRIB_DESP_RE, (_m, n) => {
    const dkey = ctx.despLookup.get(Number(n));
    if (dkey) return `RPRO ${dkey}`;
    ctx.warnings.push(
      `${context}: referencia a "ATTRIB DESP[${n}]" sem nenhuma entrada de Dataset com PURP=DESP e NUMB ${n} correspondente - expressao mantida como texto bruto (vai aparecer como invalida), revise manualmente.`
    );
    return `ATTRIB DESP[${n}]`;
  });
  working = working.replace(ATTRIB_PARA_RE, (_m, n) => `PARAM ${n}`);
  working = working.replace(RPROP_RE, (_m, dkey) => `RPRO ${dkey}`);
  return working;
}

// Reverte pmlAxis: normaliza "Pn"/"-Pn" (sem espaco, forma exportada) de
// volta pra "P n" (forma primaria aceita por utils/axisExpression.js) -
// qualquer outra sintaxe de eixo (composta, tipo "Y45X") ja e passthrough
// direto nos dois sentidos.
function fromPmlAxis(raw) {
  if (raw === null) return null;
  const trimmed = raw.trim();
  const m = trimmed.match(/^(-?)P(\d+)$/i);
  if (m) return `${m[1]}P ${m[2]}`;
  return trimmed;
}

// ---------------------------------------------------------------------------
// Tipos de primitiva/P-point sem exemplo real confirmado (mesmas listas do
// DatalExporter.js) - so pra avisar o usuario que vale conferir com atencao
// extra, nunca pra bloquear a importacao.
// ---------------------------------------------------------------------------
// 'torusRect' CONFIRMADO por exemplo real (REFERENCIAS/SUP.pmlmac,
// "SRTORUS") - saiu desta lista (mesmo par de listas do DatalExporter.js).
const UNVERIFIED_PRIMITIVE_TYPES = new Set(['cone', 'sphere', 'disc', 'snout', 'torus', 'extrusion']);
const UNVERIFIED_POINT_TYPES = new Set(['PTMIX', 'PTPOS']);

// Aceita tanto o nome LONGO confirmado (SCYLINDER/LPYRAMID - o que o
// DatalExporter.js emite) quanto o mnemonico curto do manual (SCYL/LPYR),
// caso um DATAL de verdade (nao gerado por este app) use a forma curta.
const POSITIVE_KEYWORD_TO_TYPE = {
  SBOX: 'box',
  SCYLINDER: 'cylinder',
  SCYL: 'cylinder',
  SCON: 'cone',
  SSPH: 'sphere',
  SDIS: 'disc',
  LPYRAMID: 'pyramid',
  LPYR: 'pyramid',
  LSNO: 'snout',
  SCTO: 'torus',
  SRTORUS: 'torusRect', // CONFIRMADO por REFERENCIAS/SUP.pmlmac - forma real, nao SRTO/RTOR (so-por-manual)
  SRTO: 'torusRect',
  RTOR: 'torusRect',
  SEXT: 'extrusion'
};
const NEGATIVE_KEYWORD_TO_TYPE = {
  NSBOX: 'negBox',
  NSBO: 'negBox',
  NSCYLINDER: 'negCylinder',
  NSCY: 'negCylinder',
  NLPYRAMID: 'negPyramid',
  NLPY: 'negPyramid'
};
const BASE_POSITIVE_TYPE_OF_NEGATIVE = { negBox: 'box', negCylinder: 'cylinder', negPyramid: 'pyramid' };

const TYPE_LABELS = {
  box: 'Caixa',
  cylinder: 'Cilindro',
  cone: 'Cone',
  sphere: 'Esfera',
  disc: 'Disco',
  pyramid: 'Piramide',
  snout: 'Snout',
  torus: 'Toro',
  torusRect: 'Toro Retangular',
  extrusion: 'Extrusao',
  negBox: 'Caixa Negativa',
  negCylinder: 'Cilindro Negativo',
  negPyramid: 'Piramide Negativa'
};

// Preenche os campos de uma primitiva a partir dos atributos do bloco -
// espelha, tipo por tipo, os `build*Block` do DatalExporter.js.
function parsePrimitiveAttrs(type, block, ctx) {
  const baseType = BASE_POSITIVE_TYPE_OF_NEGATIVE[type] ?? type;
  const context = `Elemento ${block.keyword}`;
  const num = (key) => fromPmlExpr(attrValue(block, key), ctx, context);
  const axisOf = (key) => fromPmlAxis(attrValue(block, key));

  const data = { type, position: { x: '0', y: '0', z: '0' }, dimensions: {} };

  switch (baseType) {
    case 'box':
      data.position = { x: num('PX'), y: num('PY'), z: num('PZ') };
      data.dimensions = { width: num('PXLE'), depth: num('PYLE'), height: num('PZLE') };
      break;
    case 'cylinder':
      data.distance = num('PDIS');
      data.dimensions = { diameter: num('PDIA'), height: num('PHEI') };
      data.axis = axisOf('PAXI') ?? 'Z';
      break;
    case 'cone':
      data.axis = axisOf('PAXI') ?? 'Z';
      data.dimensions = { height: num('PDIS'), diameter: num('PDIA') };
      break;
    case 'sphere':
      data.position = { x: '0', y: '0', z: num('PDIS') };
      data.dimensions = { diameter: num('PDIA') };
      break;
    case 'disc':
      data.position = { x: '0', y: '0', z: num('PDIS') };
      data.dimensions = { diameter: num('PDIA') };
      break;
    case 'pyramid':
      data.axisZ = axisOf('PAAX') ?? 'Z';
      data.axisX = axisOf('PBAX') ?? 'X';
      data.axisY = axisOf('PCAX') ?? 'Y';
      data.dimensions = {
        bottomWidth: num('PBBT'),
        bottomDepth: num('PCBT'),
        topWidth: num('PBTP'),
        topDepth: num('PCTP'),
        distBottom: num('PBDI'),
        distTop: num('PTDI'),
        offsetX: num('PBOF'),
        offsetY: num('PCOF')
      };
      break;
    case 'snout':
      data.axisA = axisOf('PAAX') ?? 'Y';
      data.axisB = axisOf('PBAX') ?? 'Z';
      data.dimensions = {
        bottomDiameter: num('PBDM'),
        topDiameter: num('PTDM'),
        distBottom: num('PBDI'),
        distTop: num('PTDI'),
        offset: num('POFF')
      };
      break;
    case 'torus':
      data.axisA = axisOf('PAAX') ?? 'Y';
      data.axisB = axisOf('PBAX') ?? 'Z';
      data.dimensions = { diameter: num('PDIA') };
      break;
    case 'torusRect':
      data.axisA = axisOf('PAAX') ?? 'Y';
      data.axisB = axisOf('PBAX') ?? 'Z';
      data.dimensions = { diameter: num('PDIA'), height: num('PHEI') };
      break;
    case 'extrusion': {
      data.position = { x: num('PX'), y: num('PY'), z: num('PZ') };
      data.axisA = axisOf('PAAX') ?? 'Y';
      data.axisB = axisOf('PBAX') ?? 'Z';
      data.dimensions = { height: num('PHEI') };
      const slooBlock = block.children.find((c) => c.keyword === 'SLOO');
      data.vertices = slooBlock
        ? slooBlock.children
            .filter((c) => c.keyword === 'SVER')
            .map((v) => ({
              id: createId(),
              x: fromPmlExpr(attrValue(v, 'PX'), ctx, 'Vertice SVER'),
              y: fromPmlExpr(attrValue(v, 'PY'), ctx, 'Vertice SVER'),
              radius: fromPmlExpr(attrValue(v, 'PRAD'), ctx, 'Vertice SVER')
            }))
        : [];
      break;
    }
    default:
      break;
  }

  return data;
}

// Percorre o GMSET recursivamente - qualquer NEW filho com palavra-chave de
// elemento NEGATIVO fica ANINHADO dentro do NEW/END do positivo (sintaxe
// confirmada contra o E3D de verdade, ver DatalExporter.js:
// buildGeomSetMemberBlocks) - por isso a busca por negativos e' feita nos
// FILHOS de cada bloco de primitiva, nao numa lista separada.
function collectPrimitives(gmsetBlock, ctx) {
  const list = [];
  const counters = {};
  function nameFor(type) {
    counters[type] = (counters[type] ?? 0) + 1;
    return `${TYPE_LABELS[type] ?? type} ${counters[type]}`;
  }
  function walk(block, parentId) {
    const isNegative = Boolean(NEGATIVE_KEYWORD_TO_TYPE[block.keyword]);
    const isPositive = Boolean(POSITIVE_KEYWORD_TO_TYPE[block.keyword]);
    if (!isNegative && !isPositive) {
      if (block.keyword !== 'SLOO' && block.keyword !== 'SVER') {
        ctx.warnings.push(`Elemento de geometria "${block.keyword}" (dentro do GMSET) nao reconhecido - ignorado.`);
      }
      return;
    }
    const type = isNegative ? NEGATIVE_KEYWORD_TO_TYPE[block.keyword] : POSITIVE_KEYWORD_TO_TYPE[block.keyword];
    const baseType = BASE_POSITIVE_TYPE_OF_NEGATIVE[type] ?? type;
    if (UNVERIFIED_PRIMITIVE_TYPES.has(baseType)) {
      ctx.warnings.push(
        `Tipo de primitiva "${block.keyword}" (${TYPE_LABELS[type] ?? type}) sem exemplo real confirmado neste app - confira os valores importados com atencao extra.`
      );
    }
    const data = parsePrimitiveAttrs(type, block, ctx);
    data.id = createId();
    data.parentId = parentId;
    data.name = nameFor(type);
    list.push(data);
    block.children.forEach((child) => walk(child, data.id));
  }
  gmsetBlock.children.forEach((child) => walk(child, null));
  return list;
}

// ---------------------------------------------------------------------------
// P-points (PTSET) - espelha buildPointBlock do DatalExporter.js.
// ---------------------------------------------------------------------------
const POINT_KEYWORD_TO_TYPE = { PTAXIS: 'PTAXI', PTAXI: 'PTAXI', PTCAR: 'PTCAR', PTMIX: 'PTMIX', PTPOS: 'PTPOS' };

function parsePointBlock(block, ctx) {
  const pointType = POINT_KEYWORD_TO_TYPE[block.keyword];
  if (!pointType) {
    ctx.warnings.push(`Elemento "${block.keyword}" (dentro do PTSET) nao reconhecido - ignorado.`);
    return null;
  }
  if (UNVERIFIED_POINT_TYPES.has(pointType)) {
    ctx.warnings.push(`Subtipo de P-point "${block.keyword}" sem exemplo real confirmado neste app - confira os valores importados com atencao extra.`);
  }
  const numbRaw = attrValue(block, 'NUMB');
  const context = `P-point NUMB ${numbRaw ?? '?'}`;
  const num = (key) => fromPmlExpr(attrValue(block, key), ctx, context);
  const axisOf = (key) => fromPmlAxis(attrValue(block, key));

  const data = {
    pointType,
    number: numbRaw !== null && numbRaw.trim() !== '' ? Number(numbRaw) : 0,
    connectionType: num('PCON'),
    bore: num('PBOR'),
    description: unquote(attrValue(block, 'DESC')),
    purpose: (attrValue(block, 'PURP') ?? '').trim()
  };

  if (pointType === 'PTAXI') {
    data.distance = num('PDIS');
    data.axis = axisOf('PAXI') ?? 'Y';
  } else if (pointType === 'PTMIX') {
    data.position = { x: num('PX'), y: num('PY'), z: num('PZ') };
    data.axis = axisOf('PAXI') ?? 'Y';
  } else if (pointType === 'PTPOS') {
    data.positionExpr = attrValue(block, 'PTCPOS') ?? '';
    data.directionExpr = attrValue(block, 'PTCD') ?? '';
  } else {
    data.position = { x: num('PX'), y: num('PY'), z: num('PZ') };
    data.axis = axisOf('PTCDI') ?? 'Y';
  }

  // PARAGON as vezes nomeia o elemento com um path tipo
  // "/AGT_SDE-37-005-PT/POINT.01" (ver REFERENCIAS/SUPORTE_SDE-37-005.pmlmac)
  // - usa o ultimo segmento como nome, se existir; senao fica com o default
  // ("Ponto P") de createDefaultPointData.
  if (block.name) {
    const lastSeg = block.name.split('/').filter(Boolean).pop();
    if (lastSeg) data.name = lastSeg;
  }
  return data;
}

// ---------------------------------------------------------------------------
// Dataset (DTSET/DATA) - espelha buildDatasetEntryBlock do DatalExporter.js.
// ---------------------------------------------------------------------------

// 1a passada, SO pra montar dkey/NUMB das entradas PURP=DESP - precisa
// existir ANTES de resolver qualquer expressao (de Dataset, Ponto ou
// Primitiva) que possa referenciar "ATTRIB DESP[n]" (ver fromPmlExpr acima).
function buildDespLookup(dtsetBlock) {
  const lookup = new Map();
  if (!dtsetBlock) return lookup;
  dtsetBlock.children
    .filter((c) => c.keyword === 'DATA')
    .forEach((block) => {
      const purp = (attrValue(block, 'PURP') ?? '').trim();
      const dkey = (attrValue(block, 'DKEY') ?? '').trim();
      const numbRaw = attrValue(block, 'NUMB');
      if (purp === 'DESP' && dkey && numbRaw !== null && numbRaw.trim() !== '') {
        lookup.set(Number(numbRaw), dkey.toUpperCase());
      }
    });
  return lookup;
}

function collectDatasetEntries(dtsetBlock, ctx) {
  let anonCounter = 1;
  return dtsetBlock.children
    .filter((c) => c.keyword === 'DATA')
    .map((block) => {
      const dkey = (attrValue(block, 'DKEY') ?? '').trim();
      const purp = (attrValue(block, 'PURP') ?? '').trim();
      const numbRaw = attrValue(block, 'NUMB');
      const number = numbRaw !== null && numbRaw.trim() !== '' ? Number(numbRaw) : null;
      const context = `Dataset ${dkey || '?'}`;

      const pproRaw = attrValue(block, 'PPRO');
      let ppro = '';
      if (pproRaw !== null) {
        const inner = stripOuterParens(pproRaw);
        // PPRO auto-gerado a partir do proprio NUMB (PURP=DESP) - o app
        // guarda esse texto TAL QUAL no store (nunca convertido pra
        // RPRO/PARAM - ver core/DatasetStore.js e o comentario no cabecalho
        // deste arquivo), entao a importacao preserva o mesmo padrao.
        const despSelfMatch = inner.match(/^ATTRIB\s+DESP\s*\[\s*(\d+)\s*\]$/i);
        if (purp === 'DESP' && despSelfMatch && number !== null && Number(despSelfMatch[1]) === number) {
          ppro = `ATTRIB DESP[${despSelfMatch[1]} ]`;
        } else {
          ppro = fromPmlExpr(inner, ctx, context);
        }
      }
      const dproRaw = attrValue(block, 'DPRO');
      const dpro = dproRaw !== null ? fromPmlExpr(stripOuterParens(dproRaw), ctx, context) : '';

      return {
        dkey: dkey || `D${anonCounter++}`,
        ptyp: (attrValue(block, 'PTYP') ?? '').trim(),
        ppro,
        dpro,
        purp,
        number,
        dtit: unquote(attrValue(block, 'DTIT'))
      };
    });
}

// ---------------------------------------------------------------------------
// Parametros (TEXT /<category>-PA<n>) e Variantes/Componentes (SCOMPONENT) -
// ambos filhos diretos do bloco CATEGORY.
// ---------------------------------------------------------------------------
const PARAM_TEXT_NAME_RE = /-PA(\d+)$/i;

function collectParameters(categoryChildren) {
  return categoryChildren
    .filter((c) => c.keyword === 'TEXT')
    .map((block) => {
      const m = (block.name ?? '').match(PARAM_TEXT_NAME_RE);
      if (!m) return null; // TEXT .../-PTSE e .../-GMSE nao sao parametro - ignora
      return { number: Number(m[1]), description: unquote(attrValue(block, 'STEX')) };
    })
    .filter(Boolean)
    .sort((a, b) => a.number - b.number);
}

function collectVariants(categoryChildren, parameterDefs, ctx) {
  return categoryChildren
    .filter((c) => c.keyword === 'SCOMPONENT')
    .map((block) => {
      const rawName = (block.name ?? '').trim();
      const name = rawName.startsWith('/') ? rawName.slice(1) : rawName;
      const gtype = (attrValue(block, 'GTYP') ?? '').trim();
      if (gtype && gtype !== CATEGORY_GTYPE) {
        ctx.warnings.push(`Componente "${name}": GTYP "${gtype}" diferente do esperado ("${CATEGORY_GTYPE}") - importado do mesmo jeito.`);
      }
      const tokens = (attrValue(block, 'PARA') ?? '').split(/\s+/).filter((t) => t !== '');
      if (tokens.length !== parameterDefs.length) {
        ctx.warnings.push(
          `Componente "${name}": ${tokens.length} valor(es) de PARA, mas ha ${parameterDefs.length} definicao(es) de parametro - confira se os valores ficaram na coluna certa.`
        );
      }
      const values = {};
      parameterDefs.forEach((p, idx) => {
        values[p.number] = tokens[idx] ?? '';
      });
      return { name: name || 'COMPONENTE', gtype: gtype || CATEGORY_GTYPE, values };
    });
}

// ---------------------------------------------------------------------------
// Entrada principal.
// ---------------------------------------------------------------------------
export function parseDatal(text) {
  const lines = splitLines(text);
  const topBlocks = parseBlocks(lines);
  const categoryBlock = topBlocks.find((b) => b.keyword === 'CATEGORY');
  if (!categoryBlock) {
    return { error: 'Nenhum bloco "NEW CATEGORY" encontrado no texto - confira se o conteudo colado/carregado e um DATAL (.pmlmac) completo.' };
  }

  const warnings = [];
  const dtsetBlock = categoryBlock.children.find((c) => c.keyword === 'DTSET');
  const ptsetBlock = categoryBlock.children.find((c) => c.keyword === 'PTSET');
  const gmsetBlock = categoryBlock.children.find((c) => c.keyword === 'GMSET');

  const ctx = { warnings, despLookup: buildDespLookup(dtsetBlock) };

  const category = {
    name: (categoryBlock.name ?? '').replace(/^\//, ''),
    description: unquote(attrValue(categoryBlock, 'DESC'))
  };
  const parameters = collectParameters(categoryBlock.children);
  const datasets = dtsetBlock ? collectDatasetEntries(dtsetBlock, ctx) : [];
  const points = ptsetBlock ? ptsetBlock.children.map((b) => parsePointBlock(b, ctx)).filter(Boolean) : [];
  const primitives = gmsetBlock ? collectPrimitives(gmsetBlock, ctx) : [];
  const variants = collectVariants(categoryBlock.children, parameters, ctx);

  if (!dtsetBlock) warnings.push('Nenhum bloco DTSET encontrado - nenhuma entrada de Dataset foi importada.');
  if (!ptsetBlock) warnings.push('Nenhum bloco PTSET encontrado - nenhum P-point foi importado.');
  if (!gmsetBlock) warnings.push('Nenhum bloco GMSET encontrado - nenhuma primitiva foi importada.');
  if (variants.length === 0) warnings.push('Nenhum SCOMPONENT encontrado - nenhuma variante foi importada.');

  return { category, parameters, datasets, points, primitives, variants, warnings };
}
