import * as THREE from 'three';
import { DEG2RAD } from '../utils/transformMath.js';
import { resolveNumber } from '../utils/expressionEvaluator.js';
import {
  resolveDimension,
  resolveVertices,
  resolveExtrusionBasis,
  resolveSingleAxis,
  resolvePyramidBasis,
  resolveTorusArc,
  torusPoint3D,
  resolvePrimitiveOrigin
} from './PrimitiveObject.js';
import { resolvePointPosition } from './PPointObject.js';

// Pontos de encaixe ("snap") usados pela ferramenta de Cotas (ver
// core/CotaPickTool.js) - cada objeto da cena expoe um conjunto de pontos
// "colaveis": vertices reais quando existem (extrusao), ou pontos
// representativos - "quadrantes" nos 4 pontos cardeais (0/90/180/270 graus) -
// quando a forma e redonda e nao tem vertice de verdade (cilindro/cone/
// snout/disco/toro); esfera usa os 6 polos (extensao 3D do mesmo principio).
//
// Cada funcao devolve pontos em coordenadas de MUNDO, sempre recalculados a
// partir do estado ATUAL do objeto (nunca uma coordenada "congelada") - por
// isso recebem `resolveParam`, igual ao resto do app: se a primitiva crescer
// (expressao muda de valor), o proximo calculo ja reflete o novo tamanho.
const QUADRANT_ANGLES_DEG = [0, 90, 180, 270];

function quadrantOffsets(radius) {
  return QUADRANT_ANGLES_DEG.map((deg) => {
    const rad = deg * DEG2RAD;
    return new THREE.Vector3(Math.cos(rad) * radius, Math.sin(rad) * radius, 0);
  });
}

// Extrusao e cilindro sao um caso especial: se o campo de eixo (PAAX/PBAX ou
// PAXI) referencia um P-point, a posicao dele vira a origem local da
// primitiva (ver PrimitiveObject.resolvePrimitiveOrigin) - sem isso os
// pontos colaveis (usados pela ferramenta de Cotas) ficariam desalinhados
// da posicao visual real do solido. Pras demais primitivas, e so a posicao
// mesmo (resolvePrimitiveOrigin ja cobre os dois casos).
function primitiveOrigin(data, resolveParam) {
  return resolvePrimitiveOrigin(data, resolveParam);
}

// Pontos LOCAIS (relativos a origem da primitiva) por tipo - ver capitulo
// 7.4 do manual de referencia para os atributos reais de cada forma.
function primitiveLocalPoints(data, resolveParam) {
  const dims = data.dimensions;
  const points = [];
  const add = (key, x, y, z) => points.push({ anchorKey: key, offset: new THREE.Vector3(x, y, z) });

  switch (data.type) {
    case 'cylinder': {
      // PAXI (ver PrimitiveObject.resolveSingleAxis) reorienta o cilindro
      // inteiro - os pontos "quadrante"/topo/base sao medidos ao longo da
      // MESMA rotacao aplicada a geometria de verdade (buildGeometry), senao
      // ficariam desalinhados quando o eixo nao e o Z padrao. A origem e a
      // BASE (nao o centro - ver resolveCylinderOrigin), entao bottom fica
      // em offset ZERO e top a `h` de distancia, nao +-h/2.
      const r = resolveDimension(dims.diameter, resolveParam) / 2;
      const h = resolveDimension(dims.height, resolveParam);
      const { quat } = resolveSingleAxis(data);
      const axisX = new THREE.Vector3(1, 0, 0).applyQuaternion(quat);
      const axisY = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);
      const axisZ = new THREE.Vector3(0, 0, 1).applyQuaternion(quat);
      const bottom = new THREE.Vector3(0, 0, 0);
      const top = axisZ.clone().multiplyScalar(h);
      add('bottom-center', bottom.x, bottom.y, bottom.z);
      add('top-center', top.x, top.y, top.z);
      QUADRANT_ANGLES_DEG.forEach((deg, i) => {
        const rad = deg * DEG2RAD;
        const radial = axisX.clone().multiplyScalar(Math.cos(rad) * r).add(axisY.clone().multiplyScalar(Math.sin(rad) * r));
        const bottomPt = radial.clone().add(bottom);
        const topPt = radial.clone().add(top);
        add(`bottom-quad-${i}`, bottomPt.x, bottomPt.y, bottomPt.z);
        add(`top-quad-${i}`, topPt.x, topPt.y, topPt.z);
      });
      break;
    }
    case 'cone': {
      // Mesmo principio do cilindro acima (PAXI reorienta, origem e a BASE -
      // ver resolveConeOrigin) - so nao tem "top-quad", ja que o topo e um
      // unico ponto (o apice), nao um circulo.
      const r = resolveDimension(dims.diameter, resolveParam) / 2;
      const h = resolveDimension(dims.height, resolveParam);
      const { quat } = resolveSingleAxis(data);
      const axisX = new THREE.Vector3(1, 0, 0).applyQuaternion(quat);
      const axisY = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);
      const axisZ = new THREE.Vector3(0, 0, 1).applyQuaternion(quat);
      const bottom = new THREE.Vector3(0, 0, 0);
      const apex = axisZ.clone().multiplyScalar(h);
      add('bottom-center', bottom.x, bottom.y, bottom.z);
      add('apex', apex.x, apex.y, apex.z);
      QUADRANT_ANGLES_DEG.forEach((deg, i) => {
        const rad = deg * DEG2RAD;
        const radial = axisX.clone().multiplyScalar(Math.cos(rad) * r).add(axisY.clone().multiplyScalar(Math.sin(rad) * r));
        const pt = radial.clone().add(bottom);
        add(`bottom-quad-${i}`, pt.x, pt.y, pt.z);
      });
      break;
    }
    case 'sphere': {
      const r = resolveDimension(dims.diameter, resolveParam) / 2;
      add('center', 0, 0, 0);
      add('pos-x', r, 0, 0);
      add('neg-x', -r, 0, 0);
      add('pos-y', 0, r, 0);
      add('neg-y', 0, -r, 0);
      add('pos-z', 0, 0, r);
      add('neg-z', 0, 0, -r);
      break;
    }
    case 'disc': {
      const r = resolveDimension(dims.diameter, resolveParam) / 2;
      add('center', 0, 0, 0);
      quadrantOffsets(r).forEach((off, i) => add(`quad-${i}`, off.x, off.y, 0));
      break;
    }
    case 'pyramid': {
      // PBAX/PCAX/PAAX (ver PrimitiveObject.resolvePyramidBasis) reorientam
      // o solido inteiro; PBDI/PTDI posicionam cada face ao longo de PAAX
      // (local Z), e PBOF/PCOF deslocam o centro do topo - tudo tem que
      // bater exatamente com o que buildGeometry usa, senao os pontos
      // colaveis (Cotas) ficam desalinhados da geometria real.
      const bw = resolveDimension(dims.bottomWidth, resolveParam) / 2;
      const bd = resolveDimension(dims.bottomDepth, resolveParam) / 2;
      const tw = resolveDimension(dims.topWidth, resolveParam, 0) / 2;
      const td = resolveDimension(dims.topDepth, resolveParam, 0) / 2;
      const distBottom = resolveNumber(dims.distBottom, resolveParam);
      const distTop = resolveNumber(dims.distTop, resolveParam);
      const offsetX = resolveNumber(dims.offsetX, resolveParam);
      const offsetY = resolveNumber(dims.offsetY, resolveParam);
      const { axisX, axisY, axisZ } = resolvePyramidBasis(data);
      const toWorld = (lx, ly, lz) =>
        axisX.clone().multiplyScalar(lx).add(axisY.clone().multiplyScalar(ly)).add(axisZ.clone().multiplyScalar(lz));
      const bz = -distBottom;
      const tz = distTop;
      [
        [-bw, -bd],
        [bw, -bd],
        [bw, bd],
        [-bw, bd]
      ].forEach(([x, y], i) => {
        const p = toWorld(x, y, bz);
        add(`base-${i}`, p.x, p.y, p.z);
      });
      [
        [-tw, -td],
        [tw, -td],
        [tw, td],
        [-tw, td]
      ].forEach(([x, y], i) => {
        const p = toWorld(offsetX + x, offsetY + y, tz);
        add(`top-${i}`, p.x, p.y, p.z);
      });
      break;
    }
    case 'snout': {
      // PAAX/PBAX (ver PrimitiveObject.resolveExtrusionBasis - MESMA regra
      // da extrusao: normal = axisA x axisB) reorientam o solido; PBDI/PTDI
      // posicionam cada face ao longo da normal, e POFF desloca o centro do
      // topo ao longo de axisA - tudo tem que bater com buildGeometry.
      const rb = resolveDimension(dims.bottomDiameter, resolveParam) / 2;
      const rt = resolveDimension(dims.topDiameter, resolveParam, 0) / 2;
      const distBottom = resolveNumber(dims.distBottom, resolveParam);
      const distTop = resolveNumber(dims.distTop, resolveParam);
      const offset = resolveNumber(dims.offset, resolveParam);
      const { axisA, axisB, normal } = resolveExtrusionBasis(data);
      const bottomCenter = normal.clone().multiplyScalar(-distBottom);
      const topCenter = normal.clone().multiplyScalar(distTop).add(axisA.clone().multiplyScalar(offset));
      add('bottom-center', bottomCenter.x, bottomCenter.y, bottomCenter.z);
      add('top-center', topCenter.x, topCenter.y, topCenter.z);
      QUADRANT_ANGLES_DEG.forEach((deg, i) => {
        const rad = deg * DEG2RAD;
        const bRadial = axisA.clone().multiplyScalar(Math.cos(rad) * rb).add(axisB.clone().multiplyScalar(Math.sin(rad) * rb));
        const tRadial = axisA.clone().multiplyScalar(Math.cos(rad) * rt).add(axisB.clone().multiplyScalar(Math.sin(rad) * rt));
        const bp = bRadial.clone().add(bottomCenter);
        const tp = tRadial.clone().add(topCenter);
        add(`bottom-quad-${i}`, bp.x, bp.y, bp.z);
        add(`top-quad-${i}`, tp.x, tp.y, tp.z);
      });
      break;
    }
    case 'torus':
    case 'torusRect': {
      // resolvePrimitiveOrigin ja devolve 0,0,0 pra torus/torusRect (a
      // geometria embute posicoes ABSOLUTAS - ver PrimitiveObject.js), entao
      // os "offsets" abaixo sao na verdade coordenadas de mundo diretas.
      const arc = resolveTorusArc(data);
      if (!arc) {
        add('center', 0, 0, 0); // sem P-point valido - so o placeholder na origem
        break;
      }
      const start = torusPoint3D(arc, arc.center2[0] + Math.cos(arc.angleA) * arc.radius, arc.center2[1] + Math.sin(arc.angleA) * arc.radius);
      const endAngle = arc.angleA + arc.sweep;
      const end = torusPoint3D(arc, arc.center2[0] + Math.cos(endAngle) * arc.radius, arc.center2[1] + Math.sin(endAngle) * arc.radius);
      add('start-center', start.x, start.y, start.z);
      add('end-center', end.x, end.y, end.z);
      break;
    }
    case 'extrusion': {
      // PAAX/PBAX (ver core/PrimitiveStore.js e PrimitiveObject.resolveExtrusionBasis)
      // reorientam o plano do SLOO - v.x/v.y sao medidos ao longo de
      // axisA/axisB, nao mais do mundo X/Y direto.
      const height = resolveDimension(dims.height, resolveParam);
      const { axisA, axisB, normal } = resolveExtrusionBasis(data);
      resolveVertices(data.vertices, resolveParam).forEach((v, i) => {
        const bottom = axisA.clone().multiplyScalar(v.x).addScaledVector(axisB, v.y);
        const top = bottom.clone().addScaledVector(normal, height);
        points.push({ anchorKey: `vertex-${i}-bottom`, offset: bottom });
        points.push({ anchorKey: `vertex-${i}-top`, offset: top });
      });
      break;
    }
    case 'box':
    default: {
      const w = resolveDimension(dims.width, resolveParam) / 2;
      const d = resolveDimension(dims.depth, resolveParam) / 2;
      const h = resolveDimension(dims.height, resolveParam) / 2;
      [-1, 1].forEach((sx) =>
        [-1, 1].forEach((sy) => [-1, 1].forEach((sz) => add(`corner-${sx}-${sy}-${sz}`, sx * w, sy * d, sz * h)))
      );
      add('center', 0, 0, 0);
      break;
    }
  }
  return points;
}

export function getPrimitiveSnapPoints(data, resolveParam) {
  const origin = primitiveOrigin(data, resolveParam);
  // Primitivas nao tem rotacao (ver core/PrimitiveStore.js) - soma direta,
  // sem passar o offset por nenhuma matriz/quaternion de rotacao.
  return primitiveLocalPoints(data, resolveParam).map(({ anchorKey, offset }) => ({
    anchorKey,
    position: origin.clone().add(offset)
  }));
}

// Referencias TEM rotacao livre - o offset local (cantos do plano) precisa
// ser rotacionado antes de somar a posicao.
export function getReferenceSnapPoints(data, resolveParam) {
  const origin = new THREE.Vector3(
    resolveNumber(data.position.x, resolveParam),
    resolveNumber(data.position.y, resolveParam),
    resolveNumber(data.position.z, resolveParam)
  );
  const quat = new THREE.Quaternion().setFromEuler(
    new THREE.Euler(data.rotation.x * DEG2RAD, data.rotation.y * DEG2RAD, data.rotation.z * DEG2RAD)
  );
  const hw = (data.width * data.scale.x) / 2;
  const hh = (data.height * data.scale.y) / 2;

  const local = [
    { anchorKey: 'corner-bl', offset: new THREE.Vector3(-hw, -hh, 0) },
    { anchorKey: 'corner-br', offset: new THREE.Vector3(hw, -hh, 0) },
    { anchorKey: 'corner-tr', offset: new THREE.Vector3(hw, hh, 0) },
    { anchorKey: 'corner-tl', offset: new THREE.Vector3(-hw, hh, 0) },
    { anchorKey: 'center', offset: new THREE.Vector3(0, 0, 0) }
  ];

  return local.map(({ anchorKey, offset }) => ({
    anchorKey,
    position: origin.clone().add(offset.applyQuaternion(quat))
  }));
}

// P-point: um unico ponto - a MESMA posicao mostrada no viewport (ver
// objects/PPointObject.js, cobre PTAXI/PTMIX/PTCAR/PTPOS sem duplicar logica).
export function getPointSnapPoints(data, resolveParam) {
  return [{ anchorKey: 'origin', position: resolvePointPosition(data, resolveParam) }];
}

function snapPointsFor(objectType, data, resolveParam) {
  if (objectType === 'reference') return getReferenceSnapPoints(data, resolveParam);
  if (objectType === 'primitive') return getPrimitiveSnapPoints(data, resolveParam);
  return getPointSnapPoints(data, resolveParam);
}

// Varre os 3 stores e devolve TODOS os pontos colaveis da cena, cada um
// marcado com o objeto de origem - usado pela ferramenta de Cotas pra achar
// o ponto mais proximo do mouse (ver core/CotaPickTool.js). Objetos ocultos
// nao entram (nao faz sentido colar num ponto que nao esta sendo desenhado).
export function collectAllSnapPoints({ referenceStore, primitiveStore, pointStore }, resolveParam) {
  const results = [];
  const stores = [
    ['reference', referenceStore],
    ['primitive', primitiveStore],
    ['ppoint', pointStore]
  ];
  for (const [objectType, store] of stores) {
    for (const data of store.list()) {
      if (!data.visible) continue;
      for (const sp of snapPointsFor(objectType, data, resolveParam)) {
        results.push({ objectType, objectId: data.id, anchorKey: sp.anchorKey, position: sp.position });
      }
    }
  }
  return results;
}

// Resolve UMA referencia de ponto (objectType+objectId+anchorKey, salva numa
// Cota - ver core/CotaStore.js) de volta pra uma posicao de mundo ATUAL.
// Devolve null se o objeto foi apagado ou aquele anchorKey nao existe mais
// (ex.: um vertice de extrusao removido) - quem chama decide o que fazer
// (ver objects/CotaObject.js, que esconde a Cota nesse caso).
export function resolveAnchorPosition(ref, stores, resolveParam) {
  const store = ref.objectType === 'reference' ? stores.referenceStore : ref.objectType === 'primitive' ? stores.primitiveStore : stores.pointStore;
  const data = store.get(ref.objectId);
  if (!data) return null;
  const match = snapPointsFor(ref.objectType, data, resolveParam).find((p) => p.anchorKey === ref.anchorKey);
  return match ? match.position : null;
}
