import { renderEntityList } from './EntityTree.js';
import { createCollapsibleSection } from './CollapsibleSection.js';

// Painel lateral esquerdo: arvore/lista de referencias da cena + botao de adicionar.
export class ScenePanel {
  constructor({ container, store, selectionModel, onAddReference }) {
    this.container = container;
    this.store = store;
    this.selectionModel = selectionModel;
    this.onAddReference = onAddReference;
    this.renamingId = null;

    this._buildStaticLayout();
    store.on('reference:added', () => this.render());
    store.on('reference:removed', () => this.render());
    store.on('reference:updated', () => this.render());
    selectionModel.on('changed', () => this.render());

    this.render();
  }

  _buildStaticLayout() {
    const { bodyEl } = createCollapsibleSection({ container: this.container, title: 'Cena', defaultExpanded: false });
    this.container = bodyEl;
    this.container.innerHTML = `
      <button id="add-reference-btn" class="add-entity-btn full-add-btn">+ Adicionar referencia</button>
      <ul id="scene-tree" class="entity-tree"></ul>
    `;
    this.treeEl = this.container.querySelector('#scene-tree');
    this.container.querySelector('#add-reference-btn').addEventListener('click', () => {
      this.onAddReference();
    });
  }

  render() {
    renderEntityList({
      treeEl: this.treeEl,
      items: this.store.list(),
      isSelected: (id) => this.selectionModel.isSelected('reference', id),
      iconFor: (item) => (item.type === 'pdf' ? '\u{1F4C4}' : '\u{1F5BC}'),
      renamingId: this.renamingId,
      onSelect: (id) => this.selectionModel.select('reference', id),
      onStartRename: (id) => {
        this.renamingId = id;
        this.render();
      },
      onCommitRename: (id, value) => this._commitRename(id, value),
      onCancelRename: () => {
        this.renamingId = null;
        this.render();
      },
      onToggleVisible: (item) => this.store.updateReference(item.id, { visible: !item.visible }),
      onDuplicate: (id) => {
        const copy = this.store.duplicateReference(id);
        if (copy) this.selectionModel.select('reference', copy.id);
      },
      onDelete: (id) => this.store.removeReference(id),
      emptyMessage: 'Nenhuma referencia na cena. Use "Adicionar referencia" para comecar.'
    });
  }

  _commitRename(id, value) {
    this.renamingId = null;
    const name = value.trim();
    if (name) {
      this.store.updateReference(id, { name });
    } else {
      this.render();
    }
  }
}
