import { isParametric, needsExpressionHint, evaluateExpression, hasInchLiteral, convertInchLiterals } from '../utils/expressionEvaluator.js';
import { PSKEY_OPTIONS } from '../utils/axisDirections.js';
import { resolveAxisExpression } from '../utils/axisExpression.js';
import { createId } from '../utils/id.js';
import { openPointPickerDialog } from './PointPickerDialog.js';
import { isNegativePrimitiveType } from '../core/PrimitiveStore.js';

// Normaliza um literal em polegada (ex.: "16in") pro numero em mm assim que
// o campo perde o foco (evento nativo 'change', so dispara se o valor
// realmente mudou desde que o campo ganhou foco - nao atrapalha o 'input' de
// cada tecla) OU quando o usuario aperta Enter (BUG REAL corrigido: um
// campo de texto solto, fora de um <form>, nao dispara 'change' nenhum so
// com Enter - so blur; sem o listener de Enter, digitar "16in" e apertar
// Enter direto, sem clicar em outro lugar depois, parecia "nao fazer nada")
// - decisao explicita do usuario: digitar "16in" deve REDIGITAR o campo com
// o valor ja convertido ("406.4"), nao so mostrar a dica de baixo com o
// valor resolvido. Reaproveita `hasInchLiteral`/`convertInchLiterals` (ja
// usados por evaluateExpression - mesma regra, so aplicada como texto em
// vez de calculo) e dispara um 'input' sintetico depois de normalizar pra
// reusar o listener 'input' que cada campo ja tem (persiste no store +
// atualiza a dica), sem duplicar logica de persistencia por campo.
function _attachInchNormalization(input) {
  if (!input) return;
  const normalize = () => {
    if (hasInchLiteral(input.value)) {
      input.value = convertInchLiterals(input.value);
      input.dispatchEvent(new Event('input', { bubbles: true }));
    }
  };
  input.addEventListener('change', normalize);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      normalize();
    }
  });
}

// Campos de expressao de eixo (ver utils/axisExpression.js) - resolvem pra
// um VETOR, nao um numero/PARAM, entao ficam fora do loop generico de
// _refreshExpressionHints (que so entende evaluateExpression) e sao
// tratados a parte por _refreshAxisHints.
const AXIS_HINT_FIELDS = new Set(['axis', 'axisA', 'axisB', 'axisX', 'axisY', 'axisZ', 'axisPerp']);

// Tipos de primitiva sem posicao livre (PX/PY/PZ) no catalogo real - so PAXI
// (+ PDIS no caso do cilindro) - ver core/PrimitiveStore.js e
// _cylinderAxisSection/_coneFieldsSection/_pyramidFieldsSection. Cilindro
// NEGATIVO segue a MESMA regra do cilindro positivo (mesmos atributos - ver
// capitulo 7.5 do manual); caixa negativa continua com posicao livre, igual
// a caixa positiva (por isso 'negBox' NAO entra aqui).
const NO_FREE_POSITION_TYPES = new Set(['cylinder', 'negCylinder', 'cone', 'pyramid', 'negPyramid', 'snout', 'torus', 'torusRect']);

// Os 4 subtipos de P-point do catalogo real (PTSET, capitulo 7.1 do manual
// de referencia) - ver comentario em core/PointStore.js para o que cada um
// guarda/deriva.
const POINT_TYPE_OPTIONS = [
  { value: 'PTCAR', label: 'Cartesiano (PTCAR) - posicao + direcao livres' },
  { value: 'PTAXI', label: 'Axial (PTAXI) - eixo + distancia' },
  { value: 'PTMIX', label: 'Misto (PTMIX) - posicao livre + direcao no eixo' },
  { value: 'PTPOS', label: 'Posicao/expressao (PTPOS) - PTCPOS/PTCD em texto' }
];

// Layout dos campos de dimensao por tipo de primitiva (chave do campo em
// `dimensions`, rotulo curto) - cada sub-array e uma linha (`.prop-row`) do
// formulario. Mantido junto do PropertiesPanel porque so afeta esta UI; os
// nomes de campo tem que bater com objects/PrimitiveObject.js e
// core/PrimitiveStore.js.
const DIMENSION_FIELDS = {
  box: [[['width', 'Larg (X)'], ['depth', 'Prof (Y)'], ['height', 'Alt (Z)']]],
  // negBox nao precisa de entrada propria - cai no fallback pra box (mesmas
  // dimensoes, ver DIMENSION_FIELDS[data.type] ?? DIMENSION_FIELDS.box em
  // _dimensionsSection). negCylinder SIM precisa - senao cairia nesse mesmo
  // fallback de box (largura/profundidade/altura), errado pro layout de
  // diametro+altura do cilindro.
  cylinder: [[['diameter', 'Diam'], ['height', 'Alt (Z)']]],
  negCylinder: [[['diameter', 'Diam'], ['height', 'Alt (Z)']]],
  // cone nao usa este layout - suas 2 dimensoes (diameter/height) aparecem
  // dentro de _coneFieldsSection(), junto do PAXI (ver _buildForm).
  sphere: [[['diameter', 'Diam']]],
  disc: [[['diameter', 'Diam']]],
  // piramide nao usa este layout - suas 8 dimensoes aparecem dentro de
  // _pyramidFieldsSection(), junto dos 3 eixos (ver _buildForm).
  // snout tambem nao usa - suas 5 dimensoes aparecem dentro de
  // _snoutFieldsSection(), junto de axisA/axisB. torus/torusRect idem -
  // ver _torusFieldsSection().
  extrusion: [[['height', 'Alt (Z)']]]
};

// Painel de propriedades do objeto selecionado (referencia, primitiva ou
// P-point). Qualquer alteracao numerica atualiza o store correspondente, que
// por sua vez atualiza o objeto no viewport.
//
// Posicao (todos os tipos), dimensoes de primitiva e PCON/PBOR de P-point
// aceitam expressoes (ver utils/expressionEvaluator.js) - um campo de texto
// em vez de numero, com uma dica abaixo mostrando o valor resolvido contra a
// variante ativa (VariantStore) sempre que o texto referenciar um parametro
// ("PARAM n").
//
// Rotacao NAO existe em primitivas por enquanto (ver core/PrimitiveStore.js)
// - nem todo elemento do catalogo real tem esse atributo generico.
export class PropertiesPanel {
  constructor({
    container,
    referenceStore,
    primitiveStore,
    pointStore,
    variantStore,
    parameterStore,
    datasetStore,
    selectionModel,
    onScaleByReference
  }) {
    this.container = container;
    this.referenceStore = referenceStore;
    this.primitiveStore = primitiveStore;
    this.pointStore = pointStore;
    this.variantStore = variantStore;
    this.parameterStore = parameterStore;
    this.datasetStore = datasetStore;
    this.selectionModel = selectionModel;
    this.onScaleByReference = onScaleByReference;
    this.currentType = null;
    this.currentId = null;
    this.inputs = {};
    this.resolveParam = (number) => this.variantStore.resolveParam(number);

    selectionModel.on('changed', (sel) => this._onSelectionChanged(sel));
    referenceStore.on('reference:updated', (data) => this._onExternalUpdate('reference', data));
    referenceStore.on('reference:removed', (id) => this._onExternalRemoved('reference', id));
    primitiveStore.on('primitive:updated', (data) => this._onExternalUpdate('primitive', data));
    primitiveStore.on('primitive:removed', (id) => this._onExternalRemoved('primitive', id));
    pointStore.on('point:updated', (data) => this._onExternalUpdate('ppoint', data));
    pointStore.on('point:removed', (id) => this._onExternalRemoved('ppoint', id));

    // A variante ativa (ou os valores/definicoes de parametro) podem mudar
    // sem que o proprio objeto selecionado mude - so as dicas de expressao
    // precisam ser recalculadas nesse caso. Todo tipo selecionado tem ao
    // menos posicao, que agora tambem aceita expressao.
    const refreshHintsIfRelevant = () => {
      if (!this.currentType) return;
      const data = this._store().get(this.currentId);
      if (data) this._refreshExpressionHints(data);
    };
    variantStore.on('active-changed', refreshHintsIfRelevant);
    variantStore.on('variant:updated', refreshHintsIfRelevant);
    parameterStore.on('parameter:added', refreshHintsIfRelevant);
    parameterStore.on('parameter:updated', refreshHintsIfRelevant);
    parameterStore.on('parameter:removed', refreshHintsIfRelevant);
    datasetStore.on('dataset:added', refreshHintsIfRelevant);
    datasetStore.on('dataset:updated', refreshHintsIfRelevant);
    datasetStore.on('dataset:removed', refreshHintsIfRelevant);

    this._renderEmpty();
  }

  _onExternalUpdate(type, data) {
    if (type === this.currentType && data.id === this.currentId) this._refreshValues(data);
  }

  _onExternalRemoved(type, id) {
    if (type === this.currentType && id === this.currentId) this._onSelectionChanged(null);
  }

  _onSelectionChanged(sel) {
    // Se um campo tipo Nome (commit so no 'change', ou seja, so no blur/
    // Enter - ao contrario de posicao/dimensao, que commitam a cada tecla
    // via 'input') estava focado e EDITADO mas ainda sem o 'change' nativo
    // disparar, tira o foco AQUI, ANTES de trocar `currentId` pro objeto
    // novo. Bug real que isso evita: trocar `currentId` primeiro e SO
    // DEPOIS reconstruir o formulario (removendo o input focado do DOM)
    // faz o navegador disparar o 'change' tardio (blur automatico por
    // remocao do DOM) DEPOIS que `currentId` ja mudou - o texto digitado
    // pro objeto ANTIGO acaba aplicado no objeto NOVO. Reproduzido:
    // renomear um item e clicar direto em outro (sem Tab/Enter antes)
    // fazia o segundo item "herdar" o nome digitado no primeiro.
    if (this.container.contains(document.activeElement)) {
      document.activeElement.blur();
    }

    this.currentType = sel?.type ?? null;
    this.currentId = sel?.id ?? null;
    if (!sel) {
      this._renderEmpty();
      return;
    }
    const data = this._store().get(sel.id);
    if (!data) {
      this._renderEmpty();
      return;
    }
    this._buildForm(data);
  }

  _store() {
    if (this.currentType === 'primitive') return this.primitiveStore;
    if (this.currentType === 'ppoint') return this.pointStore;
    return this.referenceStore;
  }

  // Quais grupos de eixo (posicao/rotacao/escala) o formulario mostra, por
  // tipo: primitivas nao tem rotacao nem escala (ver core/PrimitiveStore.js);
  // referencias tem os tres. P-points dependem do subtipo (pointType - ver
  // core/PointStore.js): PTAXI deriva posicao E direcao do eixo/distancia
  // (nenhum dos dois grupos e editavel aqui); PTMIX/PTCAR derivam a direcao
  // de uma expressao de eixo (campo `axis`, fora do grupo "rotation" - ver
  // _buildForm), so a posicao continua livre; so PTPOS ainda tem rotacao
  // livre de verdade. Cilindro/cone tambem nao tem posicao livre - so
  // PAXI(+PDIS no cilindro) - ver NO_FREE_POSITION_TYPES, mesmo principio do
  // PTAXI acima.
  _vectorGroups(data) {
    if (this.currentType === 'ppoint') {
      const pointType = data?.pointType ?? 'PTCAR';
      if (pointType === 'PTAXI') return [];
      if (pointType === 'PTMIX' || pointType === 'PTCAR') return ['position'];
      return ['position', 'rotation'];
    }
    if (this.currentType === 'primitive') return NO_FREE_POSITION_TYPES.has(data?.type) ? [] : ['position'];
    return ['position', 'rotation', 'scale'];
  }

  _update(patch) {
    if (this.currentType === 'reference') {
      this.referenceStore.updateReference(this.currentId, patch);
    } else if (this.currentType === 'primitive') {
      this.primitiveStore.updatePrimitive(this.currentId, patch);
    } else if (this.currentType === 'ppoint') {
      this.pointStore.updatePoint(this.currentId, patch);
    }
  }

  _renderEmpty() {
    this.container.innerHTML = `
      <div class="panel-section" style="border-bottom:none">
        <h3>Propriedades</h3>
      </div>
      <div class="empty-state">Selecione um objeto no viewport ou nas listas da cena.</div>
    `;
    this.inputs = {};
  }

  _buildForm(data) {
    const isPrimitive = this.currentType === 'primitive';
    const isPoint = this.currentType === 'ppoint';
    const isReference = this.currentType === 'reference';
    // Subtipo de P-point (PTCAR/PTAXI/PTMIX/PTPOS - ver core/PointStore.js);
    // null para os outros tipos, onde nao se aplica.
    const pointType = isPoint ? data.pointType : null;
    // PTAXI deriva posicao E direcao do eixo/distancia - a secao de
    // posicao/eixo fica sozinha (sem secao de Rotacao/Direcao depois dela),
    // entao e ela quem fica "sem borda" antes de Visibilidade.
    const isLastSection = isPoint && pointType === 'PTAXI';

    this.container.innerHTML = `
      <div class="panel-section" style="border-bottom:none">
        <h3>Propriedades</h3>
        <div class="prop-group">
          <label class="prop-label">Nome</label>
          <input type="text" class="full" data-field="name" />
        </div>
        ${isPrimitive && data.parentId ? this._negativeParentInfo(data) : ''}
      </div>

      ${isPrimitive && !['cone', 'pyramid', 'negPyramid', 'snout', 'torus', 'torusRect'].includes(data.type) ? this._dimensionsSection(data) : ''}
      ${isPrimitive && data.type === 'extrusion' ? this._extrusionAxesSection() : ''}
      ${isPrimitive && (data.type === 'cylinder' || data.type === 'negCylinder') ? this._cylinderAxisSection() : ''}
      ${isPrimitive && data.type === 'cone' ? this._coneFieldsSection() : ''}
      ${isPrimitive && (data.type === 'pyramid' || data.type === 'negPyramid') ? this._pyramidFieldsSection() : ''}
      ${isPrimitive && data.type === 'snout' ? this._snoutFieldsSection() : ''}
      ${isPrimitive && data.type === 'torus' ? this._torusFieldsSection(false) : ''}
      ${isPrimitive && data.type === 'torusRect' ? this._torusFieldsSection(true) : ''}
      ${isPrimitive && data.type === 'extrusion' ? this._verticesSection(data) : ''}
      ${isPoint ? this._pointFieldsSection(pointType) : ''}

      ${
        pointType === 'PTAXI'
          ? `<div class="panel-section" style="${isLastSection ? 'border-bottom:none' : ''}">
              <h3>Eixo e distancia (PAXI / PDIS)</h3>
              ${this._axisExpressionField('axis', 'Eixo (PAXI)')}
              <div class="prop-group">
                <label class="prop-label">Distancia (mm) - aceita expressao, ex.: "PARAM 12"</label>
                <input type="text" class="full" data-field="distance" />
                <div class="expr-hint" data-hint-for="distance"></div>
              </div>
            </div>`
          : isPrimitive && NO_FREE_POSITION_TYPES.has(data.type)
            ? '' // Sem posicao livre - PAXI(/PDIS) ja aparecem em _cylinderAxisSection()/_coneFieldsSection()
            : `<div class="panel-section">
                <h3>Posicao (mm) - aceita expressao, ex.: "PARAM 12"</h3>
                ${this._exprAxisRow('position')}
              </div>`
      }

      ${
        isPrimitive || pointType === 'PTAXI'
          ? ''
          : pointType === 'PTMIX' || pointType === 'PTCAR'
            ? `<div class="panel-section" style="border-bottom:none">
                <h3>Direcao (${pointType === 'PTCAR' ? 'PTCDIR' : 'PAXI'}) - sintaxe AVEVA, ex.: "Y45X"</h3>
                ${this._axisExpressionField('axis', pointType === 'PTCAR' ? 'Direcao (PTCDIR)' : 'Eixo (PAXI)')}
              </div>`
            : `<div class="panel-section" style="${isPoint ? 'border-bottom:none' : ''}">
                <h3>Rotacao (graus)${isPoint ? ' - define a direcao do ponto' : ''}</h3>
                ${this._axisRow('rotation', 'x', 'y', 'z')}
              </div>`
      }

      ${
        isPoint || isPrimitive
          ? ''
          : `<div class="panel-section">
              <h3>Escala</h3>
              ${this._axisRow('scale', 'x', 'y', 'z', 0.01)}
              <label class="checkbox-row" style="margin-top:6px">
                <input type="checkbox" data-field="uniformScale" />
                Escala uniforme (liga X/Y/Z)
              </label>
              ${
                isReference
                  ? `<button type="button" class="full" data-action="scale-by-points" style="margin-top:8px">
                      Escalonar por 2 pontos...
                    </button>`
                  : ''
              }
            </div>`
      }

      ${
        isPoint
          ? `<div class="panel-section" style="border-bottom:none">
              <h3>Visibilidade</h3>
              <label class="checkbox-row">
                <input type="checkbox" data-field="visible" />
                Visivel
              </label>
              <label class="checkbox-row">
                <input type="checkbox" data-field="locked" />
                Fixar (bloqueia mover/rotacionar)
              </label>
            </div>`
          : `<div class="panel-section">
              <h3>Aparencia</h3>
              ${
                isPrimitive && !isNegativePrimitiveType(data.type)
                  ? `<div class="prop-group">
                      <label class="prop-label">Cor</label>
                      <input type="color" data-field="color" />
                    </div>`
                  : ''
              }
              ${
                isPrimitive && isNegativePrimitiveType(data.type)
                  ? `<div class="prop-group" style="color:var(--text-dim);font-size:11px">Cor fixa (vermelho translucido) - elemento negativo nao usa a cor do positivo.</div>`
                  : ''
              }
              <div class="prop-group">
                <label class="prop-label">Opacidade</label>
                <input type="range" min="0" max="1" step="0.01" data-field="opacity" />
              </div>
              <label class="checkbox-row">
                <input type="checkbox" data-field="visible" />
                Visivel
              </label>
              <label class="checkbox-row">
                <input type="checkbox" data-field="locked" />
                Fixar (bloqueia mover${isPrimitive ? '' : '/rotacionar/escalar'})
              </label>
              ${
                isReference
                  ? `<label class="checkbox-row">
                      <input type="checkbox" data-field="whiteAsAlpha" />
                      Fundo branco transparente (branco vira alpha, resto fica preto)
                    </label>`
                  : ''
              }
            </div>`
      }

      ${
        isReference
          ? `<div class="panel-section" style="border-bottom:none">
              <h3>Arquivo</h3>
              <div class="prop-group" style="color:var(--text-dim)">
                <div>Tipo: ${data.type === 'pdf' ? 'PDF' : 'Imagem'}</div>
                <div>Origem: ${data.source || '-'}</div>
                ${data.type === 'pdf' ? `<div>Pagina: ${data.page}</div>` : ''}
                <div>Dimensao: ${data.width.toFixed(1)} x ${data.height.toFixed(1)} mm</div>
              </div>
            </div>`
          : ''
      }
    `;

    this.inputs = {};
    this.container.querySelectorAll('[data-field]').forEach((el) => {
      this.inputs[el.dataset.field] = el;
    });
    this.hints = {};
    this.container.querySelectorAll('[data-hint-for]').forEach((el) => {
      this.hints[el.dataset.hintFor] = el;
    });

    this._bindEvents(data);
    this._refreshValues(data);
  }

  // Elemento negativo (ver core/PrimitiveStore.js: `parentId`) - dropdown
  // editavel com todos os elementos POSITIVOS da cena (nunca outro negativo -
  // um negativo nao pode ser pai), pra "mover" o negativo pra outro positivo
  // sem precisar apagar e recriar. Trocar aqui muda so `parentId` - a arvore
  // de Primitivas (ui/PrimitivesPanel.js) recalcula a hierarquia do zero a
  // cada render a partir de `parentId`, entao a linha "salta" pro novo pai
  // sozinha, sem codigo extra. `parentId` e SO vinculo organizacional
  // (agrupamento visual + ordem de exportacao) - posicao/eixo abaixo sao
  // ABSOLUTOS, igual a qualquer elemento positivo, sem correlacao com o pai
  // (ver objects/PrimitiveObject.js: resolvePrimitiveOrigin).
  _negativeParentInfo(data) {
    const candidates = this.primitiveStore.list().filter((p) => p.id !== data.id && !isNegativePrimitiveType(p.type));
    const options = candidates
      .map((p) => `<option value="${p.id}" ${p.id === data.parentId ? 'selected' : ''}>${p.name}</option>`)
      .join('');
    return `
      <div class="prop-group">
        <label class="prop-label">⚠ Elemento negativo (buraco) - vinculado a</label>
        <select class="full" data-field="parentId">${options}</select>
        <div class="expr-hint" style="color:var(--text-dim)">So vinculo organizacional (agrupamento na lista/exportacao) - posicao/eixo abaixo sao coordenadas ABSOLUTAS, sem relacao com o elemento escolhido acima.</div>
      </div>
    `;
  }

  _dimensionsSection(data) {
    const layout = DIMENSION_FIELDS[data.type] ?? DIMENSION_FIELDS.box;
    const rows = layout.map((row) => `<div class="prop-row">${row.map(([key, label]) => this._dimField(key, label)).join('')}</div>`);
    return `
      <div class="panel-section">
        <h3>Dimensoes (mm) - aceita expressao, ex.: "PARAM 12"</h3>
        ${rows.join('')}
      </div>
    `;
  }

  // So para type==='extrusion' (SEXT): lista de vertices do perfil 2D
  // (SVER: PX/PY/PRAD - ver capitulo 7.4.17 do manual e core/PrimitiveStore.js).
  // Tamanho variavel (ao contrario de `dimensions`, que e um conjunto fixo
  // de campos por tipo) - adicionar/remover vertice reconstroi o formulario
  // inteiro (ver _bindEvents), editar um campo existente so atualiza valores.
  _verticesSection(data) {
    const rows = data.vertices.map((v, i) => this._vertexRow(i, data.vertices.length)).join('');
    return `
      <div class="panel-section">
        <h3>Vertices do perfil (SLOO) - aceita expressao</h3>
        ${rows}
        <button type="button" class="add-entity-btn full-add-btn" data-action="add-vertex">+ Adicionar vertice</button>
      </div>
    `;
  }

  _vertexRow(index, total) {
    return `
      <div class="prop-row" style="align-items:flex-start">
        ${this._vertexField(index, 'x', 'X')}
        ${this._vertexField(index, 'y', 'Y')}
        ${this._vertexField(index, 'radius', 'R')}
        <button
          type="button"
          class="icon-btn"
          data-action="remove-vertex"
          data-vertex-index="${index}"
          title="Remover vertice (minimo 3)"
          ${total <= 3 ? 'disabled' : ''}
        >✕</button>
      </div>
    `;
  }

  _vertexField(index, axis, label) {
    const field = `vertex.${index}.${axis}`;
    return `
      <div class="expr-field">
        <div class="axis-field">
          <span class="axis-tag">${label}</span>
          <input type="text" data-field="${field}" />
        </div>
        <div class="expr-hint" data-hint-for="${field}"></div>
      </div>
    `;
  }

  // Adicionar/remover vertice muda a ESTRUTURA do formulario (quantidade de
  // linhas) - precisa reconstruir tudo, igual a troca de pointType de
  // P-point. Editar X/Y/R de um vertice existente so atualiza o array
  // (deepMerge substitui arrays inteiros - ver utils/deepMerge.js - entao
  // sempre reconstruimos a lista completa em vez de mandar um patch parcial).
  //
  // IMPORTANTE: cada handler le a lista de vertices ATUAL do store (nunca o
  // `data` capturado quando o formulario foi montado) - `data` fica
  // desatualizado assim que QUALQUER campo do vertice e editado (o form nao
  // e reconstruido a cada tecla, so _refreshValues), entao reconstruir o
  // array a partir dele descartava silenciosamente edicoes ja aplicadas a
  // outros campos do mesmo vertice (ex.: digitar em Y apagava o que acabou
  // de ser digitado em X, porque o patch de Y "voltava" o X pro valor antigo
  // ainda preso no `data` da closure).
  _bindVertexEvents(data) {
    data.vertices.forEach((vertex, index) => {
      ['x', 'y', 'radius'].forEach((axis) => {
        const input = this.inputs[`vertex.${index}.${axis}`];
        input.addEventListener('input', () => {
          const current = this._store().get(this.currentId);
          const nextVertices = current.vertices.map((v, i) => (i === index ? { ...v, [axis]: input.value } : v));
          this._update({ vertices: nextVertices });
          this._refreshExpressionHints(this._store().get(this.currentId));
        });
        _attachInchNormalization(input);
      });
    });

    this.container.querySelectorAll('[data-action="remove-vertex"]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const current = this._store().get(this.currentId);
        if (current.vertices.length <= 3) return;
        const index = Number(btn.dataset.vertexIndex);
        this._update({ vertices: current.vertices.filter((_, i) => i !== index) });
        this._buildForm(this._store().get(this.currentId));
      });
    });

    const addBtn = this.container.querySelector('[data-action="add-vertex"]');
    addBtn?.addEventListener('click', () => {
      const current = this._store().get(this.currentId);
      const last = current.vertices[current.vertices.length - 1];
      const newVertex = { id: createId(), x: last?.x ?? '0', y: last?.y ?? '0', radius: '0' };
      this._update({ vertices: [...current.vertices, newVertex] });
      this._buildForm(this._store().get(this.currentId));
    });
  }

  _pointFieldsSection(pointType) {
    // Campos equivalentes aos atributos de um P-point do catalogo do E3D
    // (NUMB, PCON, PBOR, PSKEY, DESC, PURP - ver capitulo 7.1 do manual de
    // referencia). O subtipo (PTCAR/PTAXI/PTMIX/PTPOS) decide quais campos
    // de posicao/direcao aparecem depois desta secao (ver _buildForm).
    return `
      <div class="panel-section">
        <h3>P-point</h3>
        <div class="prop-group">
          <label class="prop-label">Tipo (PTSET)</label>
          <select class="full" data-field="pointType">
            ${POINT_TYPE_OPTIONS.map((opt) => `<option value="${opt.value}">${opt.label}</option>`).join('')}
          </select>
        </div>
        <div class="prop-group">
          <label class="prop-label">Numero (NUMB)</label>
          <input type="number" step="1" class="full" data-field="number" />
        </div>
        <div class="prop-group">
          <label class="prop-label">Tipo de conexao (PCON)</label>
          <input type="text" class="full" placeholder="ex.: WELD, SCRD, PARAM 3" data-field="connectionType" />
          <div class="expr-hint" data-hint-for="connectionType"></div>
        </div>
        <div class="prop-group">
          <label class="prop-label">Bore (PBOR, mm)</label>
          <input type="text" class="full" placeholder="ex.: 50, PARAM 1" data-field="bore" />
          <div class="expr-hint" data-hint-for="bore"></div>
        </div>
        <div class="prop-group">
          <label class="prop-label">Condicao de extremidade p/ ISODRAFT (PSKEY)</label>
          <select class="full" data-field="pskey">
            ${PSKEY_OPTIONS.map((opt) => `<option value="${opt.value}">${opt.label}</option>`).join('')}
          </select>
        </div>
        <div class="prop-group">
          <label class="prop-label">Descricao (DESC)</label>
          <input type="text" class="full" data-field="description" />
        </div>
        <div class="prop-group">
          <label class="prop-label">Proposito (PURP)</label>
          <input type="text" class="full" data-field="purpose" />
        </div>
        ${
          pointType === 'PTPOS'
            ? `<div class="prop-group">
                <label class="prop-label">Expressao de posicao (PTCPOS) - texto livre, so documentacao</label>
                <input type="text" class="full" placeholder="ex.: POS(PARA[1],0,0)" data-field="positionExpr" />
              </div>
              <div class="prop-group">
                <label class="prop-label">Expressao de direcao (PTCD) - texto livre, so documentacao</label>
                <input type="text" class="full" placeholder="ex.: DIR(0,0,1)" data-field="directionExpr" />
              </div>
              <div class="prop-group" style="color:var(--text-dim);font-size:11px">
                PTCPOS/PTCD sao expressoes PML livres no catalogo real - este app nao as
                interpreta. A posicao/direcao usadas no viewport abaixo (X/Y/Z e rotacao) sao
                uma simplificacao para permitir visualizar e arrastar o ponto.
              </div>`
            : ''
        }
      </div>
    `;
  }

  // Campo de expressao de eixo (ver utils/axisExpression.js): aceita eixo
  // cardeal ("Y"), composto ("Y45X" - Y girado 45 graus em direcao a X), ou
  // referencia a um P-point ("P3", ou "-P3" pra direcao oposta) inserida
  // pelo botao "PPnt". Usado por PAXI de PTAXI/PTMIX e por PAAX/PBAX de
  // extrusao/snout/torus.
  _axisExpressionField(fieldKey, label) {
    return `
      <div class="prop-group">
        <label class="prop-label">${label}</label>
        <div class="prop-row">
          <input type="text" class="full" style="flex:1 1 0%; min-width:0; width:auto" data-field="${fieldKey}" placeholder='ex.: Y, Y45X, "P3", "-P3"' />
          <button type="button" class="icon-btn" data-action="pick-point" data-target-field="${fieldKey}" title="Usar a direcao de um P-point">PPnt</button>
        </div>
        <div class="expr-hint" data-hint-for="${fieldKey}"></div>
      </div>
    `;
  }

  // PAAX/PBAX (ver capitulo 7.4.17 do manual e core/PrimitiveStore.js):
  // eixos locais do plano do perfil (SLOO) de uma extrusao - a extrusao em
  // si vai ao longo do eixo perpendicular aos dois (axisA x axisB).
  _extrusionAxesSection() {
    return `
      <div class="panel-section">
        <h3>Orientacao do perfil (PAAX / PBAX)</h3>
        ${this._axisExpressionField('axisA', 'A Axis (PAAX)')}
        ${this._axisExpressionField('axisB', 'B Axis (PBAX)')}
        <div class="expr-hint" data-hint-for="axisPerp" style="padding-left:2px"></div>
      </div>
    `;
  }

  // PAXI/PDIS (ver core/PrimitiveStore.js): eixo unico de orientacao +
  // distancia ate a base de um cilindro - SEM posicao livre (SCYL nao tem
  // PX/PY/PZ no catalogo real), mesmo principio de um P-point PTAXI (ver
  // trecho "Eixo e distancia (PAXI / PDIS)" acima, pra pointType==='PTAXI').
  // So UM eixo (ao contrario da extrusao, 2 eixos PAAX/PBAX).
  _cylinderAxisSection() {
    return `
      <div class="panel-section">
        <h3>Eixo e distancia (PAXI / PDIS)</h3>
        ${this._axisExpressionField('axis', 'Eixo (PAXI)')}
        <div class="prop-group">
          <label class="prop-label">Dist. ate a base (mm) - aceita expressao, ex.: "PARAM 12"</label>
          <input type="text" class="full" data-field="distance" />
          <div class="expr-hint" data-hint-for="distance"></div>
        </div>
      </div>
    `;
  }

  // PAXI/PDIS/PDIA (ver core/PrimitiveStore.js) - igual ao dialogo do
  // catalogo real: ao contrario do cilindro, o cone NAO tem um PDIS de
  // offset separado - a base fica sempre exatamente na origem/P-point de
  // PAXI, entao PDIS aqui e so a distancia da base ate o apice
  // (`dimensions.height`, ja existente) - por isso as 3 dimensoes do cone
  // (Direction/PDIS/Diametro) ficam juntas nesta secao, sem uma secao
  // "Dimensoes" nem "Posicao" separadas (ver _buildForm).
  _coneFieldsSection() {
    return `
      <div class="panel-section">
        <h3>Direcao e dimensoes (PAXI / PDIS / PDIA)</h3>
        ${this._axisExpressionField('axis', 'Direction (PAXI)')}
        ${this._dimGroupField('height', 'Dist. ao centro (mm, PDIS) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('diameter', 'Diametro (mm, PDIA) - aceita expressao, ex.: "PARAM 12"')}
      </div>
    `;
  }

  // PBAX/PCAX/PAAX/PBTP/PCTP/PBBT/PCBT/PTDI/PBDI/PBOF/PCOF (ver
  // core/PrimitiveStore.js) - igual ao dialogo do catalogo real: 3 campos de
  // eixo (cada um com seu proprio botao PPnt), mas PBAX/PCAX sao
  // ortogonalizados contra PAAX na hora de resolver (ver
  // objects/PrimitiveObject.js: resolvePyramidBasis) - as faces ficam sempre
  // perpendiculares ao eixo A, o campo so influencia a direcao "preferida"/
  // lateralidade + as dimensoes de cada face + a distancia de cada face ate
  // a origem + o deslocamento do centro do topo em relacao ao da base. Sem
  // posicao livre nem secao "Dimensoes" separada (ver _buildForm) - tudo
  // junto nesta secao, igual a imagem de referencia do catalogo.
  _pyramidFieldsSection() {
    return `
      <div class="panel-section">
        <h3>Eixos e dimensoes (PBAX / PCAX / PAAX / PDIS / PDIA)</h3>
        ${this._axisExpressionField('axisX', 'X Axis (PBAX)')}
        ${this._axisExpressionField('axisY', 'Y Axis (PCAX)')}
        ${this._axisExpressionField('axisZ', 'Z Axis (PAAX)')}
        ${this._dimGroupField('topWidth', 'X Top (mm, PBTP) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('topDepth', 'Y Top (mm, PCTP) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('bottomWidth', 'X Bottom (mm, PBBT) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('bottomDepth', 'Y Bottom (mm, PCBT) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('distTop', 'Dist. ao topo (mm, PTDI) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('distBottom', 'Dist. a base (mm, PBDI) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('offsetX', 'X Offset (mm, PBOF) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('offsetY', 'Y Offset (mm, PCOF) - aceita expressao, ex.: "PARAM 12"')}
      </div>
    `;
  }

  // PAAX/PBAX/PTDI/PBDI/PTDM/PBDM/POFF (ver core/PrimitiveStore.js) - MESMA
  // regra de eixo da extrusao (2 eixos explicitos + normal = axisA x axisB -
  // ver objects/PrimitiveObject.js: resolveExtrusionBasis, reaproveitada sem
  // duplicar - por isso os campos usam os mesmos nomes `axisA`/`axisB`).
  // Sem posicao livre (ver _buildForm) - PBDI/PTDI (distancia de cada face
  // ate a origem) + POFF (excentricidade do topo, so 1 eixo - ao longo de A,
  // ao contrario da piramide que tem PBOF/PCOF separados) substituem PX/PY/PZ.
  _snoutFieldsSection() {
    return `
      <div class="panel-section">
        <h3>Eixos e dimensoes (PAAX / PBAX / PTDI / PBDI / PTDM / PBDM / POFF)</h3>
        ${this._axisExpressionField('axisA', 'A Axis (PAAX)')}
        ${this._axisExpressionField('axisB', 'B Axis (PBAX)')}
        <div class="expr-hint" data-hint-for="axisPerp" style="padding-left:2px"></div>
        ${this._dimGroupField('distTop', 'Dist. ao topo (mm, PTDI) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('distBottom', 'Dist. a base (mm, PBDI) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('topDiameter', 'Diametro topo (mm, PTDM) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('bottomDiameter', 'Diametro base (mm, PBDM) - aceita expressao, ex.: "PARAM 12"')}
        ${this._dimGroupField('offset', 'Offset (mm, POFF) - aceita expressao, ex.: "PARAM 12"')}
      </div>
    `;
  }

  // PAAX/PBAX/PDIA(/PHEI) (ver core/PrimitiveStore.js) - curva de tubo
  // ligando 2 pontos, MESMOS axisA/axisB do snout/extrusao, mas aqui os 2
  // TEM que referenciar um P-point cada (ver
  // objects/PrimitiveObject.js: resolveTorusArc) - sem campo de
  // raio/angulo, o arco e calculado sozinho como o unico tangente as 2
  // direcoes nos 2 pontos. `isRect` adiciona PHEI (torus de secao
  // retangular, PDIA vira so a largura) - senao PDIA e o diametro do tubo
  // redondo.
  _torusFieldsSection(isRect) {
    return `
      <div class="panel-section">
        <h3>Eixos e dimensoes (PAAX / PBAX / PDIA${isRect ? ' / PHEI' : ''})</h3>
        ${this._axisExpressionField('axisA', 'A Axis (PAAX)')}
        ${this._axisExpressionField('axisB', 'B Axis (PBAX)')}
        <div class="expr-hint" data-hint-for="axisPerp" style="padding-left:2px"></div>
        ${this._dimGroupField('diameter', `${isRect ? 'Largura' : 'Diametro'} (mm, PDIA) - aceita expressao, ex.: "PARAM 12"`)}
        ${isRect ? this._dimGroupField('height', 'Altura (mm, PHEI) - aceita expressao, ex.: "PARAM 12"') : ''}
        <div class="prop-group" style="color:var(--text-dim);font-size:11px">
          So forma uma curva de verdade quando A Axis E B Axis referenciam um
          P-point cada (botao PPnt, ou "P&lt;numb&gt;" digitado a mao) - a
          posicao de cada ponto vira a extremidade do tubo. A curva sai na
          direcao OPOSTA a direcao do ponto (comportamento do E3D real) - use
          "-P&lt;numb&gt;" pra inverter de volta. Os 2 pontos precisam
          compartilhar uma coordenada (X, Y ou Z).
        </div>
      </div>
    `;
  }

  // Campo de expressao de dimensao (`dim.<key>`) full-width com label
  // proprio - usado quando o campo precisa aparecer FORA da secao
  // "Dimensoes" generica (_dimensionsSection/_dimField, que empilha varios
  // campos lado a lado com um rotulo curto), ver _coneFieldsSection/
  // _pyramidFieldsSection/_snoutFieldsSection.
  _dimGroupField(key, label) {
    return `
      <div class="prop-group">
        <label class="prop-label">${label}</label>
        <input type="text" class="full" data-field="dim.${key}" />
        <div class="expr-hint" data-hint-for="dim.${key}"></div>
      </div>
    `;
  }

  _dimField(key, label) {
    return `
      <div class="expr-field">
        <div class="axis-field">
          <span class="axis-tag">${label}</span>
          <input type="text" data-field="dim.${key}" />
        </div>
        <div class="expr-hint" data-hint-for="dim.${key}"></div>
      </div>
    `;
  }

  // Linha de X/Y/Z que aceita expressao (usada pela Posicao - ver
  // utils/expressionEvaluator.js). Rotacao/Escala continuam com
  // `_axisRow`/_axisField abaixo, que sao numero puro.
  _exprAxisRow(group) {
    return `<div class="prop-row">${['x', 'y', 'z'].map((axis) => this._exprAxisField(group, axis)).join('')}</div>`;
  }

  _exprAxisField(group, axis) {
    return `
      <div class="expr-field">
        <div class="axis-field">
          <span class="axis-tag">${axis.toUpperCase()}</span>
          <input type="text" data-field="${group}.${axis}" />
        </div>
        <div class="expr-hint" data-hint-for="${group}.${axis}"></div>
      </div>
    `;
  }

  _axisRow(group, x, y, z, step = 0.1) {
    return `
      <div class="prop-row">
        ${this._axisField(group, x, step)}
        ${this._axisField(group, y, step)}
        ${this._axisField(group, z, step)}
      </div>
    `;
  }

  _axisField(group, axis, step) {
    return `
      <div class="axis-field">
        <span class="axis-tag">${axis.toUpperCase()}</span>
        <input type="number" step="${step}" data-field="${group}.${axis}" />
      </div>
    `;
  }

  _bindEvents(data) {
    const nameInput = this.inputs.name;
    nameInput.addEventListener('change', () => {
      const value = nameInput.value.trim();
      if (value) this._update({ name: value });
    });

    this._vectorGroups(data).forEach((group) => {
      ['x', 'y', 'z'].forEach((axis) => {
        const input = this.inputs[`${group}.${axis}`];
        if (group === 'position') {
          // Posicao e expressao: commita a string crua, sem exigir numero.
          input.addEventListener('input', () => {
            this._update({ position: { [axis]: input.value } });
            this._refreshExpressionHints(this._store().get(this.currentId));
          });
          _attachInchNormalization(input);
        } else {
          input.addEventListener('input', () => this._onVectorInput(group, axis, input));
        }
      });
    });

    this.inputs.visible.addEventListener('change', () => {
      this._update({ visible: this.inputs.visible.checked });
    });

    this.inputs.locked.addEventListener('change', () => {
      this._update({ locked: this.inputs.locked.checked });
    });

    if (this.currentType === 'reference' || this.currentType === 'primitive') {
      this.inputs.opacity.addEventListener('input', () => {
        this._update({ opacity: Number(this.inputs.opacity.value) });
      });
    }

    if (this.currentType === 'reference') {
      this.inputs.whiteAsAlpha.addEventListener('change', () => {
        this._update({ whiteAsAlpha: this.inputs.whiteAsAlpha.checked });
      });

      const scaleByPointsBtn = this.container.querySelector('[data-action="scale-by-points"]');
      scaleByPointsBtn?.addEventListener('click', () => this.onScaleByReference(this.currentId));
    }

    if (this.currentType === 'primitive') {
      // Elemento negativo nao tem campo de Cor (ver _buildForm/isNegativePrimitiveType) - fica sem esse listener.
      this.inputs.color?.addEventListener('input', () => {
        this._update({ color: this.inputs.color.value });
      });

      // So existe no DOM pra elemento negativo (ver _negativeParentInfo) -
      // "mover" pra outro positivo trocando o dropdown.
      this.inputs.parentId?.addEventListener('change', () => {
        this._update({ parentId: this.inputs.parentId.value });
      });

      Object.keys(data.dimensions).forEach((key) => {
        const input = this.inputs[`dim.${key}`];
        input.addEventListener('input', () => {
          this._update({ dimensions: { [key]: input.value } });
          this._refreshExpressionHints(this._store().get(this.currentId));
        });
        _attachInchNormalization(input);
      });

      // axisA/axisB (PAAX/PBAX) sao compartilhados por extrusao/snout/torus -
      // MESMOS campos; extrusao/snout usam a MESMA regra (normal = axisA x
      // axisB - ver objects/PrimitiveObject.js: resolveExtrusionBasis),
      // torus/torusRect usam resolveTorusArc (2 P-points obrigatorios).
      if (['extrusion', 'snout', 'torus', 'torusRect'].includes(data.type)) {
        this.inputs.axisA.addEventListener('input', () => {
          this._update({ axisA: this.inputs.axisA.value });
          this._refreshAxisHints(this._store().get(this.currentId));
        });
        this.inputs.axisB.addEventListener('input', () => {
          this._update({ axisB: this.inputs.axisB.value });
          this._refreshAxisHints(this._store().get(this.currentId));
        });
      }

      if (data.type === 'extrusion') {
        this._bindVertexEvents(data);
      }

      if (data.type === 'cylinder' || data.type === 'negCylinder') {
        this.inputs.axis.addEventListener('input', () => {
          this._update({ axis: this.inputs.axis.value });
          this._refreshAxisHints(this._store().get(this.currentId));
        });
        this.inputs.distance.addEventListener('input', () => {
          this._update({ distance: this.inputs.distance.value });
          this._refreshExpressionHints(this._store().get(this.currentId));
        });
        _attachInchNormalization(this.inputs.distance);
      }

      if (data.type === 'cone') {
        this.inputs.axis.addEventListener('input', () => {
          this._update({ axis: this.inputs.axis.value });
          this._refreshAxisHints(this._store().get(this.currentId));
        });
      }

      if (data.type === 'pyramid' || data.type === 'negPyramid') {
        ['axisX', 'axisY', 'axisZ'].forEach((field) => {
          this.inputs[field].addEventListener('input', () => {
            this._update({ [field]: this.inputs[field].value });
            this._refreshAxisHints(this._store().get(this.currentId));
          });
        });
      }
    }

    if (this.currentType === 'ppoint') {
      // Trocar o subtipo muda quais campos aparecem (posicao/eixo,
      // rotacao/direcao) - precisa reconstruir o formulario inteiro, um
      // _update()/_refreshValues() normal so muda valores, nao adiciona/
      // remove campos do DOM.
      this.inputs.pointType.addEventListener('change', () => {
        this._update({ pointType: this.inputs.pointType.value });
        this._buildForm(this._store().get(this.currentId));
      });

      this.inputs.number.addEventListener('change', () => {
        const value = Number(this.inputs.number.value);
        if (!Number.isNaN(value)) this._update({ number: value });
      });
      this.inputs.connectionType.addEventListener('input', () => {
        this._update({ connectionType: this.inputs.connectionType.value });
        this._refreshExpressionHints(this._store().get(this.currentId));
      });
      this.inputs.bore.addEventListener('input', () => {
        this._update({ bore: this.inputs.bore.value });
        this._refreshExpressionHints(this._store().get(this.currentId));
      });
      _attachInchNormalization(this.inputs.bore);
      this.inputs.pskey.addEventListener('change', () => {
        this._update({ pskey: this.inputs.pskey.value });
      });
      this.inputs.description.addEventListener('change', () => {
        this._update({ description: this.inputs.description.value });
      });
      this.inputs.purpose.addEventListener('change', () => {
        this._update({ purpose: this.inputs.purpose.value });
      });

      // axis/distance so existem no DOM para PTAXI/PTMIX/PTCAR (ver _buildForm).
      this.inputs.axis?.addEventListener('input', () => {
        this._update({ axis: this.inputs.axis.value });
        this._refreshAxisHints(this._store().get(this.currentId));
      });
      this.inputs.distance?.addEventListener('input', () => {
        this._update({ distance: this.inputs.distance.value });
        this._refreshExpressionHints(this._store().get(this.currentId));
      });
      _attachInchNormalization(this.inputs.distance);

      // positionExpr/directionExpr so existem para PTPOS - texto livre, sem
      // avaliacao (ver comentario em core/PointStore.js).
      this.inputs.positionExpr?.addEventListener('change', () => {
        this._update({ positionExpr: this.inputs.positionExpr.value });
      });
      this.inputs.directionExpr?.addEventListener('change', () => {
        this._update({ directionExpr: this.inputs.directionExpr.value });
      });
    }

    this._bindPointPickerButtons();
  }

  // Liga TODOS os botoes "PPnt" renderizados no formulario atual (axis de
  // PTAXI/PTMIX, axisA/axisB de extrusao/snout/torus - ver
  // _axisExpressionField) - abre o seletor de P-point e escreve "P<numb>" no
  // campo alvo quando um e escolhido.
  _bindPointPickerButtons() {
    this.container.querySelectorAll('[data-action="pick-point"]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const targetField = btn.dataset.targetField;
        const point = await openPointPickerDialog(this.pointStore.list());
        if (!point) return;
        const input = this.inputs[targetField];
        const value = `P${point.number}`;
        if (input) input.value = value;
        this._update({ [targetField]: value });
        this._refreshAxisHints(this._store().get(this.currentId));
      });
    });
  }

  _onVectorInput(group, axis, input) {
    const value = Number(input.value);
    if (Number.isNaN(value)) return;

    if (group === 'scale' && this.inputs.uniformScale.checked) {
      this._update({ scale: { x: value, y: value, z: value } });
      return;
    }

    this._update({ [group]: { [axis]: value } });
  }

  _refreshValues(data) {
    const active = document.activeElement;

    this._setIfNotFocused(this.inputs.name, active, data.name);

    this._vectorGroups(data).forEach((group) => {
      ['x', 'y', 'z'].forEach((axis) => {
        const input = this.inputs[`${group}.${axis}`];
        const value = group === 'position' ? data.position[axis] : roundDisplay(data[group][axis]);
        this._setIfNotFocused(input, active, value);
      });
    });

    this.inputs.visible.checked = data.visible;
    this.inputs.locked.checked = data.locked;

    if (this.currentType === 'reference' || this.currentType === 'primitive') {
      this._setIfNotFocused(this.inputs.opacity, active, data.opacity);
    }

    if (this.currentType === 'reference') {
      this.inputs.whiteAsAlpha.checked = data.whiteAsAlpha;
    }

    if (this.currentType === 'primitive') {
      if (this.inputs.color) this._setIfNotFocused(this.inputs.color, active, data.color);
      if (this.inputs.parentId) this._setIfNotFocused(this.inputs.parentId, active, data.parentId);
      Object.entries(data.dimensions).forEach(([key, value]) => {
        const input = this.inputs[`dim.${key}`];
        if (input) this._setIfNotFocused(input, active, value);
      });
      if (data.type === 'extrusion') {
        data.vertices.forEach((vertex, index) => {
          ['x', 'y', 'radius'].forEach((axis) => {
            const input = this.inputs[`vertex.${index}.${axis}`];
            if (input) this._setIfNotFocused(input, active, vertex[axis]);
          });
        });
      }
      if (['extrusion', 'snout', 'torus', 'torusRect'].includes(data.type)) {
        if (this.inputs.axisA) this._setIfNotFocused(this.inputs.axisA, active, data.axisA);
        if (this.inputs.axisB) this._setIfNotFocused(this.inputs.axisB, active, data.axisB);
      }
      if (data.type === 'cylinder' || data.type === 'negCylinder') {
        if (this.inputs.axis) this._setIfNotFocused(this.inputs.axis, active, data.axis);
        if (this.inputs.distance) this._setIfNotFocused(this.inputs.distance, active, data.distance);
      }
      if (data.type === 'cone' && this.inputs.axis) this._setIfNotFocused(this.inputs.axis, active, data.axis);
      if (data.type === 'pyramid' || data.type === 'negPyramid') {
        ['axisX', 'axisY', 'axisZ'].forEach((field) => {
          if (this.inputs[field]) this._setIfNotFocused(this.inputs[field], active, data[field]);
        });
      }
    }

    if (this.currentType === 'ppoint') {
      this._setIfNotFocused(this.inputs.pointType, active, data.pointType);
      this._setIfNotFocused(this.inputs.number, active, data.number);
      this._setIfNotFocused(this.inputs.connectionType, active, data.connectionType);
      this._setIfNotFocused(this.inputs.bore, active, data.bore);
      this._setIfNotFocused(this.inputs.pskey, active, data.pskey);
      this._setIfNotFocused(this.inputs.description, active, data.description);
      this._setIfNotFocused(this.inputs.purpose, active, data.purpose);
      if (this.inputs.axis) this._setIfNotFocused(this.inputs.axis, active, data.axis);
      if (this.inputs.distance) this._setIfNotFocused(this.inputs.distance, active, data.distance);
      if (this.inputs.positionExpr) this._setIfNotFocused(this.inputs.positionExpr, active, data.positionExpr);
      if (this.inputs.directionExpr) this._setIfNotFocused(this.inputs.directionExpr, active, data.directionExpr);
    }

    this._refreshExpressionHints(data);
    this._refreshAxisHints(data);
  }

  // Recalcula as dicas de resolucao ("PARAM 12" -> "63.5") de todos os campos
  // que aceitam expressao, contra a variante ativa atual.
  //
  // "Parametro nao encontrado" pode significar duas coisas bem diferentes -
  // nenhuma variante esta marcada como ativa, ou a variante ativa existe mas
  // aquele numero de parametro esta sem valor preenchido nela (a DEFINICAO
  // de um parametro, em si, nunca tem valor - o valor mora na tabela de
  // Variantes). Sem distinguir os dois, "defini o parametro 1" e "a variante
  // ativa tem valor para o parametro 1" parecem a mesma coisa para quem le
  // so "Parametro 1 nao encontrado" - por isso as mensagens abaixo sao
  // explicitas sobre qual das duas faltou.
  _refreshExpressionHints(data) {
    if (!this.hints) return;
    const activeVariant = this.variantStore.getActive();

    Object.entries(this.hints).forEach(([field, hintEl]) => {
      if (AXIS_HINT_FIELDS.has(field)) return; // resolvidos por _refreshAxisHints (vetor, nao PARAM/numero)

      const raw = field.startsWith('dim.')
        ? data.dimensions[field.slice(4)]
        : field.startsWith('position.')
          ? data.position[field.slice(9)]
          : field.startsWith('vertex.')
            ? (() => {
                const [, indexStr, axis] = field.split('.');
                return data.vertices?.[Number(indexStr)]?.[axis];
              })()
            : data[field];

      if (!needsExpressionHint(raw)) {
        hintEl.textContent = '';
        hintEl.title = '';
        hintEl.classList.remove('expr-error');
        return;
      }

      // Um literal em polegadas puro ("2.5in") nao depende de variante
      // nenhuma - so os campos que de fato referenciam PARAM precisam de
      // uma variante ativa para resolver.
      if (isParametric(raw) && !activeVariant) {
        hintEl.textContent = '⚠ Nenhuma variante ativa selecionada (painel Parametros)';
        hintEl.title = hintEl.textContent;
        hintEl.classList.add('expr-error');
        return;
      }

      const { value, isNumber, error } = evaluateExpression(raw, this.resolveParam);
      if (error) {
        const missing = error.match(/^Parametro (\d+) nao encontrado/);
        hintEl.textContent = missing
          ? `⚠ PA${missing[1]} sem valor na variante ativa ("${activeVariant.name}")`
          : `⚠ ${error}`;
        hintEl.title = hintEl.textContent;
        hintEl.classList.add('expr-error');
      } else {
        hintEl.textContent = `→ ${isNumber ? roundDisplay(value) : value}`;
        hintEl.title = '';
        hintEl.classList.remove('expr-error');
      }
    });
  }

  // Resolve os campos de expressao de eixo (axis/axisA/axisB - ver
  // utils/axisExpression.js) pro vetor direcao resultante, mostrado como
  // dica igual as outras expressoes. Pra extrusao, tambem confere se
  // axisA/axisB estao aproximadamente perpendiculares (o usuario pode
  // definir os dois via P-points com direcoes quaisquer - so avisa se nao
  // estiverem a ~90 graus, nao bloqueia).
  _refreshAxisHints(data) {
    if (!this.hints) return;

    const resolveOne = (field) => {
      const hintEl = this.hints[field];
      if (!hintEl) return null;
      const raw = data[field];
      const { direction, error } = resolveAxisExpression(raw);
      if (error) {
        hintEl.textContent = `⚠ ${error}`;
        hintEl.title = hintEl.textContent;
        hintEl.classList.add('expr-error');
        return null;
      }
      const r = (n) => Math.round(n * 1000) / 1000;
      hintEl.textContent = `→ (${r(direction.x)}, ${r(direction.y)}, ${r(direction.z)})`;
      hintEl.title = '';
      hintEl.classList.remove('expr-error');
      return direction;
    };

    const dirAxis = resolveOne('axis');
    const dirA = resolveOne('axisA');
    const dirB = resolveOne('axisB');
    resolveOne('axisX');
    resolveOne('axisY');
    resolveOne('axisZ');
    void dirAxis;

    const perpHint = this.hints.axisPerp;
    if (perpHint) {
      if (dirA && dirB) {
        const dot = Math.abs(dirA.dot(dirB));
        if (dot > 0.05) {
          // ~3 graus de tolerancia antes de avisar
          perpHint.textContent = `⚠ A e B nao estao perpendiculares (produto escalar ${roundDisplay(dot)}) - a extrusao pode sair distorcida`;
          perpHint.title = perpHint.textContent;
          perpHint.classList.add('expr-error');
        } else {
          perpHint.textContent = '';
          perpHint.classList.remove('expr-error');
        }
      } else {
        perpHint.textContent = '';
        perpHint.classList.remove('expr-error');
      }
    }
  }

  _setIfNotFocused(input, active, value) {
    if (input === active) return;
    input.value = value;
  }
}

function roundDisplay(value) {
  return Math.round(value * 1000) / 1000;
}
