import * as THREE from 'three';

// Os 6 eixos cardeais - usados como atalhos rapidos na UI (ver
// PropertiesPanel._axisSelectField). O campo "axis" de um P-point PTAXI/
// PTMIX aceita bem mais que isso (letra composta tipo "Y45X", ou referencia
// a outro P-point "PP n") - ver utils/axisExpression.js, que e quem de fato
// resolve o campo; esses 6 aqui sao so o subconjunto "sem rotacao composta".
export const AXIS_OPTIONS = ['X', '-X', 'Y', '-Y', 'Z', '-Z'];

// PAXI Y e o padrao quando nao definido (ver manual, 5.5.5/5.6.3).
export const DEFAULT_AXIS = 'Y';

const AXIS_VECTORS = {
  X: new THREE.Vector3(1, 0, 0),
  '-X': new THREE.Vector3(-1, 0, 0),
  Y: new THREE.Vector3(0, 1, 0),
  '-Y': new THREE.Vector3(0, -1, 0),
  Z: new THREE.Vector3(0, 0, 1),
  '-Z': new THREE.Vector3(0, 0, -1)
};

export function axisVector(axis) {
  return (AXIS_VECTORS[axis] ?? AXIS_VECTORS[DEFAULT_AXIS]).clone();
}

// PSKEY - condicao de extremidade usada pelo ISODRAFT (5.5.11 do manual).
// NULL e o padrao (nenhuma condicao extra alem do simbolo padrao do SKEY).
export const PSKEY_OPTIONS = [
  { value: 'NULL', label: 'NULL (padrao)' },
  { value: 'BW', label: 'BW - Butt Weld' },
  { value: 'CP', label: 'CP - Compression' },
  { value: 'FL', label: 'FL - Flange' },
  { value: 'SC', label: 'SC - Screwed' },
  { value: 'SW', label: 'SW - Socket Weld' },
  { value: 'PL', label: 'PL - Plain' }
];
