// Calcula as dimensoes (em mm, unidade de mundo da cena) do plano de referencia,
// sempre preservando a proporcao largura/altura original do arquivo.
//
// Paginas de PDF carregam seu tamanho real de papel (ex.: A4 = 210x297mm), obtido
// a partir do viewport do PDF.js. Imagens comuns (PNG/JPG) nao possuem essa
// informacao, entao sao normalizadas para um tamanho padrao mantendo a proporcao.
const DEFAULT_LONG_SIDE_MM = 1000;

export function computePlaneDimensionsMM({ pixelWidth, pixelHeight, realWidthMM, realHeightMM }) {
  if (realWidthMM && realHeightMM) {
    return { width: realWidthMM, height: realHeightMM };
  }

  const aspect = pixelWidth / pixelHeight;
  if (!isFinite(aspect) || aspect <= 0) {
    return { width: DEFAULT_LONG_SIDE_MM, height: DEFAULT_LONG_SIDE_MM };
  }

  if (aspect >= 1) {
    return { width: DEFAULT_LONG_SIDE_MM, height: DEFAULT_LONG_SIDE_MM / aspect };
  }
  return { width: DEFAULT_LONG_SIDE_MM * aspect, height: DEFAULT_LONG_SIDE_MM };
}
