import * as THREE from 'three';
import { resolveAnchorPosition } from './SnapPoints.js';
import { COTA_LABEL_BASE_WIDTH, COTA_POINT_MARKER_BASE_RADIUS } from '../utils/cotaLabelSize.js';

const LINE_COLOR = 0xffe066; // amarelo - nao usado por mais nada na cena, fica facil de distinguir
const LABEL_TEXT_COLOR = '#1a1d0a';

function buildLabelTexture(text) {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 72;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(255, 224, 102, 0.92)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = LABEL_TEXT_COLOR;
  ctx.font = 'bold 34px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function buildPointMarker(name) {
  const geometry = new THREE.SphereGeometry(COTA_POINT_MARKER_BASE_RADIUS, 12, 8);
  const material = new THREE.MeshBasicMaterial({ color: LINE_COLOR, depthTest: false });
  const marker = new THREE.Mesh(geometry, material);
  marker.name = name;
  marker.renderOrder = 998;
  marker.raycast = () => {}; // cota nao e selecionavel/clicavel - so visual (ver ui/CotasPanel.js)
  return marker;
}

// Constroi o Object3D de uma Cota (ver core/CotaStore.js): uma linha ligando
// ponta A -> rotulo -> ponta B (ver syncCotaMesh - o vertice do meio fica
// sempre na posicao do rotulo), um marcador visivel em cada ponta (pra
// deixar claro EXATAMENTE qual ponto esta sendo medido, nao so uma linha
// fina que pode ser dificil de mirar visualmente) e o rotulo (sprite com
// texto) mostrando a distancia. So fica visivel quando as 2 pontas resolvem
// pra uma posicao de verdade (objeto de origem existe e o anchorKey ainda e
// valido) - ver syncCotaMesh.
export function createCotaMesh(data) {
  const group = new THREE.Group();
  group.userData.objType = 'cota';
  group.userData.refId = data.id;
  group.name = data.name;

  const lineGeometry = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(),
    new THREE.Vector3(),
    new THREE.Vector3()
  ]);
  const line = new THREE.Line(lineGeometry, new THREE.LineBasicMaterial({ color: LINE_COLOR, depthTest: false }));
  line.name = 'cota-line';
  line.renderOrder = 998;
  line.raycast = () => {}; // cota nao e selecionavel/clicavel - so visual (ver ui/CotasPanel.js)
  group.add(line);

  group.add(buildPointMarker('cota-point-a'));
  group.add(buildPointMarker('cota-point-b'));

  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: buildLabelTexture('—'), depthTest: false }));
  sprite.name = 'cota-label';
  sprite.scale.set(COTA_LABEL_BASE_WIDTH, COTA_LABEL_BASE_WIDTH * (72 / 256), 1);
  sprite.renderOrder = 999;
  sprite.raycast = () => {};
  group.add(sprite);

  return group;
}

// `stores` = { referenceStore, primitiveStore, pointStore } - resolve as 2
// pontas contra o estado ATUAL dos objetos referenciados (nunca uma
// coordenada congelada), entao acompanha automaticamente quando a
// geometria de origem muda de tamanho/posicao.
export function syncCotaMesh(group, data, stores, resolveParam) {
  group.name = data.name;

  const posA = data.pointA ? resolveAnchorPosition(data.pointA, stores, resolveParam) : null;
  const posB = data.pointB ? resolveAnchorPosition(data.pointB, stores, resolveParam) : null;

  if (!posA || !posB || !data.visible) {
    group.visible = false;
    return;
  }
  group.visible = true;

  const distanceMm = posA.distanceTo(posB);
  const midpoint = posA.clone().add(posB).multiplyScalar(0.5);

  // 3 vertices (A -> meio -> B) em vez de so A -> B: o vertice do meio fica
  // sempre na posicao do rotulo, entao a linha sempre "chega" na caixa de
  // texto a partir de cada ponta, mesmo que o rotulo um dia deixe de ficar
  // exatamente no ponto medio geometrico.
  const line = group.getObjectByName('cota-line');
  const positionAttr = line.geometry.attributes.position;
  positionAttr.setXYZ(0, posA.x, posA.y, posA.z);
  positionAttr.setXYZ(1, midpoint.x, midpoint.y, midpoint.z);
  positionAttr.setXYZ(2, posB.x, posB.y, posB.z);
  positionAttr.needsUpdate = true;
  line.geometry.computeBoundingSphere();

  group.getObjectByName('cota-point-a').position.copy(posA);
  group.getObjectByName('cota-point-b').position.copy(posB);

  const sprite = group.getObjectByName('cota-label');
  sprite.position.copy(midpoint);

  const text = `${Math.round(distanceMm * 1000) / 1000} mm`;
  if (sprite.userData.lastText !== text) {
    sprite.userData.lastText = text;
    sprite.material.map.dispose();
    sprite.material.map = buildLabelTexture(text);
    sprite.material.needsUpdate = true;
  }
}

export function disposeCotaMesh(group) {
  const line = group.getObjectByName('cota-line');
  line.geometry.dispose();
  line.material.dispose();

  ['cota-point-a', 'cota-point-b'].forEach((name) => {
    const marker = group.getObjectByName(name);
    marker.geometry.dispose();
    marker.material.dispose();
  });

  const sprite = group.getObjectByName('cota-label');
  sprite.material.map.dispose();
  sprite.material.dispose();
}
