import { renderPdfPageToDataURL } from '../loaders/PdfLoader.js';

// Modal simples para escolher qual pagina do PDF sera carregada como
// referencia. Resolve com o numero da pagina escolhida, ou null se cancelado.
export function openPdfPageDialog(pdf, numPages) {
  return new Promise((resolve) => {
    let currentPage = 1;
    let previewToken = 0;

    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.innerHTML = `
      <div class="modal">
        <h2>Escolher pagina do PDF</h2>
        <div class="page-nav">
          <button id="pdf-prev">&lt;</button>
          <span>Pagina</span>
          <input type="number" id="pdf-page-input" class="pdf-page-input" min="1" max="${numPages}" step="1" value="1" />
          <span>de ${numPages}</span>
          <button id="pdf-next">&gt;</button>
        </div>
        <div class="modal-preview"><span style="color:var(--text-dim)">Carregando previa...</span></div>
        <div class="modal-actions">
          <button id="pdf-cancel">Cancelar</button>
          <button id="pdf-confirm" class="active">Carregar pagina</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);

    const preview = backdrop.querySelector('.modal-preview');
    const prevBtn = backdrop.querySelector('#pdf-prev');
    const nextBtn = backdrop.querySelector('#pdf-next');
    const pageInput = backdrop.querySelector('#pdf-page-input');

    async function updatePreview() {
      pageInput.value = currentPage;
      prevBtn.disabled = currentPage <= 1;
      nextBtn.disabled = currentPage >= numPages;

      const token = ++previewToken;
      preview.innerHTML = '<span style="color:var(--text-dim)">Carregando previa...</span>';
      try {
        const result = await renderPdfPageToDataURL(pdf, currentPage, 1);
        if (token !== previewToken) return; // usuario ja trocou de pagina
        const img = document.createElement('img');
        img.src = result.dataURL;
        preview.innerHTML = '';
        preview.appendChild(img);
      } catch (err) {
        preview.innerHTML = '<span style="color:var(--danger)">Falha ao renderizar previa.</span>';
      }
    }

    function close(result) {
      document.body.removeChild(backdrop);
      resolve(result);
    }

    prevBtn.addEventListener('click', () => {
      if (currentPage > 1) {
        currentPage -= 1;
        updatePreview();
      }
    });
    nextBtn.addEventListener('click', () => {
      if (currentPage < numPages) {
        currentPage += 1;
        updatePreview();
      }
    });

    // Digitar a pagina direto - essencial em PDFs de muitas paginas, onde
    // clicar em "<"/">" repetidas vezes ate a pagina certa e inviavel.
    function commitPageInput() {
      const parsed = Math.round(Number(pageInput.value));
      const clamped = Number.isFinite(parsed) ? Math.min(Math.max(parsed, 1), numPages) : currentPage;
      if (clamped === currentPage) {
        pageInput.value = currentPage; // reverte valor invalido/fora do intervalo digitado
        return;
      }
      currentPage = clamped;
      updatePreview();
    }
    pageInput.addEventListener('change', commitPageInput);
    pageInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        commitPageInput();
      }
    });
    pageInput.addEventListener('focus', () => pageInput.select());
    backdrop.querySelector('#pdf-cancel').addEventListener('click', () => close(null));
    backdrop.querySelector('#pdf-confirm').addEventListener('click', () => close(currentPage));
    backdrop.addEventListener('click', (e) => {
      if (e.target === backdrop) close(null);
    });

    updatePreview();
  });
}
