const MIN_WIDTH = 220;
const MAX_WIDTH = 640;

function readSavedWidth(storageKey, min, max) {
  try {
    const saved = Number(localStorage.getItem(storageKey));
    return Number.isFinite(saved) && saved >= min && saved <= max ? saved : null;
  } catch {
    return null; // localStorage indisponivel (aba privada, etc.) - segue com a largura padrao do CSS
  }
}

function writeSavedWidth(storageKey, width) {
  try {
    localStorage.setItem(storageKey, String(width));
  } catch {
    // silencioso - nao e critico se a largura nao persistir entre sessoes
  }
}

// Deixa uma barra lateral (esquerda: #scene-panel, ou direita:
// #properties-panel) redimensionavel por arrasto numa faixa fina entre ela e
// o viewport - campos de expressao com rotulo longo (ex.: dimensao unica de
// uma extrusao) podem esticar demais numa barra estreita e fixa, entao o
// usuario ganha controle direto em vez de um tamanho fixo escolhido por nos.
// A largura escolhida fica salva no localStorage (por painel) e volta ao
// recarregar a pagina.
//
// `side` diz de que lado do handle o painel fica: 'left' (handle a DIREITA
// do painel, ex.: #scene-panel) ou 'right' (handle a ESQUERDA do painel, ex.:
// #properties-panel) - define o sinal do delta de arrasto.
export function makeResizable({ handleEl, panelEl, side, storageKey, min = MIN_WIDTH, max = MAX_WIDTH }) {
  const savedWidth = readSavedWidth(storageKey, min, max);
  if (savedWidth !== null) {
    panelEl.style.width = `${savedWidth}px`;
  }

  let startX = 0;
  let startWidth = 0;

  const onPointerMove = (event) => {
    const delta = event.clientX - startX;
    const signedDelta = side === 'left' ? delta : -delta;
    const width = Math.min(max, Math.max(min, startWidth + signedDelta));
    panelEl.style.width = `${width}px`;
  };

  const onPointerUp = () => {
    handleEl.classList.remove('panel-resize-active');
    document.removeEventListener('pointermove', onPointerMove);
    document.removeEventListener('pointerup', onPointerUp);
    writeSavedWidth(storageKey, Math.round(panelEl.getBoundingClientRect().width));
  };

  handleEl.addEventListener('pointerdown', (event) => {
    if (event.button !== 0) return;
    event.preventDefault();
    startX = event.clientX;
    startWidth = panelEl.getBoundingClientRect().width;
    handleEl.classList.add('panel-resize-active');
    document.addEventListener('pointermove', onPointerMove);
    document.addEventListener('pointerup', onPointerUp);
  });

  // Duplo clique volta pro tamanho padrao do CSS (destrava a largura salva).
  handleEl.addEventListener('dblclick', () => {
    panelEl.style.width = '';
    try {
      localStorage.removeItem(storageKey);
    } catch {
      // ignorado - ver writeSavedWidth
    }
  });
}
