import * as THREE from 'three';
import { collectAllSnapPoints } from '../objects/SnapPoints.js';
import {
  SNAP_HOVER_BASE_RADIUS,
  SNAP_CONFIRMED_BASE_RADIUS,
  SNAP_HOVER_SCREEN_FRACTION,
  SNAP_CONFIRMED_SCREEN_FRACTION
} from '../utils/snapMarkerSize.js';

const SNAP_PIXEL_RADIUS = 18; // raio em pixels de tela pra considerar o mouse "perto o suficiente" de um ponto
const DRAG_THRESHOLD_PX = 5;
const MARKER_COLOR = 0x66ffcc;

const HINT_FIRST = 'Passe o mouse perto de um vertice/canto e clique (1a ponta da cota) - Esc para cancelar';
const HINT_SECOND = 'Agora a segunda ponta - Esc para cancelar';

// Ferramenta de captura das 2 pontas de uma Cota - estilo OSNAP do AutoCAD:
// ao passar o mouse perto de um ponto "colavel" (ver objects/SnapPoints.js -
// vertice real ou ponto representativo tipo quadrante), ele e destacado com
// um marcador; um clique confirma aquele ponto como uma ponta. So funciona
// com pontos colados a algum objeto - nunca cria uma Cota com uma ponta
// solta no espaco (decisao explicita do usuario, ver core/CotaStore.js).
export class CotaPickTool {
  constructor({ sceneManager, referenceStore, primitiveStore, pointStore, resolveParam, onComplete }) {
    this.sceneManager = sceneManager;
    this.stores = { referenceStore, primitiveStore, pointStore };
    this.resolveParam = resolveParam;
    this.onComplete = onComplete;

    this.active = false;
    this.picked = [];
    this.downPos = null;
    this.hoverMarker = null;
    this.confirmedMarkers = [];

    this.hintEl = document.createElement('div');
    this.hintEl.className = 'pick-hint';
    this.hintEl.style.display = 'none';
    sceneManager.container.appendChild(this.hintEl);
  }

  isActive() {
    return this.active;
  }

  start() {
    if (this.active) this._cleanup();
    this.active = true;
    this.picked = [];
    this._setHint(HINT_FIRST);

    const dom = this.sceneManager.renderer.domElement;
    dom.addEventListener('pointermove', this._onPointerMove);
    dom.addEventListener('pointerdown', this._onPointerDown);
    dom.addEventListener('pointerup', this._onPointerUp);
    window.addEventListener('keydown', this._onKeyDown);
  }

  cancel() {
    this._cleanup();
  }

  _setHint(text) {
    this.hintEl.textContent = text ?? '';
    this.hintEl.style.display = text ? 'block' : 'none';
  }

  _onKeyDown = (event) => {
    if (event.key === 'Escape') this.cancel();
  };

  // Projeta cada ponto colavel da cena pra tela e devolve o mais proximo do
  // cursor, se estiver dentro do raio de captura - senao null.
  _findNearestSnap(clientX, clientY) {
    const rect = this.sceneManager.renderer.domElement.getBoundingClientRect();
    const allPoints = collectAllSnapPoints(this.stores, this.resolveParam);
    let best = null;
    let bestDist = SNAP_PIXEL_RADIUS;
    for (const sp of allPoints) {
      const ndc = sp.position.clone().project(this.sceneManager.camera);
      if (ndc.z < -1 || ndc.z > 1) continue; // atras da camera ou fora do frustum
      const sx = rect.left + ((ndc.x + 1) / 2) * rect.width;
      const sy = rect.top + ((1 - ndc.y) / 2) * rect.height;
      const dist = Math.hypot(sx - clientX, sy - clientY);
      if (dist < bestDist) {
        bestDist = dist;
        best = sp;
      }
    }
    return best;
  }

  _onPointerMove = (event) => {
    const snap = this._findNearestSnap(event.clientX, event.clientY);
    this._updateHoverMarker(snap);
  };

  _updateHoverMarker(snap) {
    if (!snap) {
      if (this.hoverMarker) this.hoverMarker.visible = false;
      return;
    }
    if (!this.hoverMarker) {
      const geometry = new THREE.SphereGeometry(SNAP_HOVER_BASE_RADIUS, 12, 8);
      const material = new THREE.MeshBasicMaterial({ color: MARKER_COLOR, depthTest: false, transparent: true, opacity: 0.85 });
      this.hoverMarker = new THREE.Mesh(geometry, material);
      this.hoverMarker.renderOrder = 999;
      this.hoverMarker.userData = { baseRadius: SNAP_HOVER_BASE_RADIUS, screenFraction: SNAP_HOVER_SCREEN_FRACTION };
      this.sceneManager.pickMarkersGroup.add(this.hoverMarker);
    }
    this.hoverMarker.visible = true;
    this.hoverMarker.position.copy(snap.position);
  }

  _onPointerDown = (event) => {
    if (event.button !== 0) return;
    this.downPos = { x: event.clientX, y: event.clientY };
  };

  // De proposito SEM stopPropagation (ver core/ReferenceScaleTool.js pro
  // mesmo raciocinio): deixa OrbitControls/SelectionManager verem o clique
  // tambem - orbitar a camera continua funcionando normalmente, e um clique
  // fora de qualquer ponto colavel simplesmente nao faz nada aqui.
  _onPointerUp = (event) => {
    if (event.button !== 0 || !this.downPos) return;
    const dx = event.clientX - this.downPos.x;
    const dy = event.clientY - this.downPos.y;
    this.downPos = null;
    if (Math.hypot(dx, dy) > DRAG_THRESHOLD_PX) return; // foi um arrasto de orbita, nao um clique

    const snap = this._findNearestSnap(event.clientX, event.clientY);
    if (!snap) return; // clique fora de qualquer ponto colavel - ignora

    this.picked.push({ objectType: snap.objectType, objectId: snap.objectId, anchorKey: snap.anchorKey });
    this._addConfirmedMarker(snap.position);

    if (this.picked.length < 2) {
      this._setHint(HINT_SECOND);
      return;
    }

    const [pointA, pointB] = this.picked;
    this._cleanup();
    this.onComplete(pointA, pointB);
  };

  _addConfirmedMarker(position) {
    const geometry = new THREE.SphereGeometry(SNAP_CONFIRMED_BASE_RADIUS, 12, 8);
    const material = new THREE.MeshBasicMaterial({ color: MARKER_COLOR, depthTest: false });
    const marker = new THREE.Mesh(geometry, material);
    marker.position.copy(position);
    marker.renderOrder = 999;
    marker.userData = { baseRadius: SNAP_CONFIRMED_BASE_RADIUS, screenFraction: SNAP_CONFIRMED_SCREEN_FRACTION };
    this.sceneManager.pickMarkersGroup.add(marker);
    this.confirmedMarkers.push(marker);
  }

  _cleanup() {
    this.active = false;
    this.picked = [];
    this.downPos = null;
    this._setHint(null);

    if (this.hoverMarker) {
      this.sceneManager.pickMarkersGroup.remove(this.hoverMarker);
      this.hoverMarker.geometry.dispose();
      this.hoverMarker.material.dispose();
      this.hoverMarker = null;
    }
    this.confirmedMarkers.forEach((marker) => {
      this.sceneManager.pickMarkersGroup.remove(marker);
      marker.geometry.dispose();
      marker.material.dispose();
    });
    this.confirmedMarkers = [];

    const dom = this.sceneManager.renderer.domElement;
    dom.removeEventListener('pointermove', this._onPointerMove);
    dom.removeEventListener('pointerdown', this._onPointerDown);
    dom.removeEventListener('pointerup', this._onPointerUp);
    window.removeEventListener('keydown', this._onKeyDown);
  }
}
