// Modal simples pra escolher um P-point (usado pelo botao "PPnt" dos campos
// de eixo - PAXI de PTAXI/PTMIX, PAAX/PBAX de extrusao - ver
// utils/axisExpression.js). Resolve com o P-point escolhido (objeto de
// dados completo), ou null se cancelado.
export function openPointPickerDialog(points) {
  return new Promise((resolve) => {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.innerHTML = `
      <div class="modal">
        <h2>Escolher P-point (usa a direcao dele)</h2>
        <div class="point-picker-list">
          ${
            points.length === 0
              ? '<div class="empty-state">Nenhum P-point na cena.</div>'
              : points.map((p) => `<button type="button" class="point-picker-item" data-id="${p.id}">${p.name} (NUMB ${p.number})</button>`).join('')
          }
        </div>
        <div class="modal-actions">
          <button id="point-picker-cancel">Cancelar</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);

    function close(result) {
      document.body.removeChild(backdrop);
      resolve(result);
    }

    backdrop.querySelectorAll('.point-picker-item').forEach((btn) => {
      btn.addEventListener('click', () => {
        const point = points.find((p) => p.id === btn.dataset.id);
        close(point ?? null);
      });
    });
    backdrop.querySelector('#point-picker-cancel').addEventListener('click', () => close(null));
    backdrop.addEventListener('click', (event) => {
      if (event.target === backdrop) close(null);
    });
  });
}
