// Persistencia da cena em JSON. O dataURL de cada referencia (fileData) e
// incluido para que o "Carregar cena" restaure as texturas sem depender dos
// arquivos originais. `source`/`page` sao mantidos separadamente para que, no
// futuro, seja possivel reassociar o arquivo original em vez de usar o dataURL.
// Primitivas (Caixa/Cilindro), P-points, definicoes de parametro, variantes
// (Componentes) e entradas de Dataset sao salvos junto, em
// `primitives`/`points`/`parameters`/`variants`/`datasets`. `camera` guarda
// posicao/zoom/target (ver SceneManager.getCameraState) pra "Carregar cena"
// devolver o enquadramento exato de quando foi salva, nao so os objetos.
// `cotas` sao anotacoes de medida (ver core/CotaStore.js) - persistem aqui
// para sobreviver a um reload, mas NAO tem equivalente no catalogo do E3D:
// se um export de DATAL vier a existir neste app, `cotas` deve ficar de fora
// dele (marca de intencao - esse exportador ainda nao existe).
// `category` guarda os metadados da CATEGORY do catalogo (ver
// core/CategoryStore.js) - nome/descricao usados tanto pelo exportador de
// DATAL (persistence/DatalExporter.js) quanto para reabrir a cena depois.
const SCENE_FORMAT_VERSION = 10;

export function serializeScene(referenceStore, primitiveStore, pointStore, parameterStore, variantStore, datasetStore, cameraState, cotaStore, categoryStore) {
  const scene = {
    version: SCENE_FORMAT_VERSION,
    createdAt: new Date().toISOString(),
    objects: referenceStore.list(),
    primitives: primitiveStore.list(),
    points: pointStore.list(),
    parameters: parameterStore.list(),
    variants: variantStore.list(),
    // BUG REAL corrigido (versao < 10): faltava salvar QUAL variante estava
    // ativa - toda expressao "PARAM n" (direta ou via "RPRO <dkey>") so
    // resolve contra a variante ativa (ver VariantStore.resolveParam), entao
    // toda cena recarregada perdia a selecao e TODA geometria parametrica
    // caia pro fallback minimo, mesmo com Dataset/Parametro/Variante
    // corretos - parecia "o dataset nao calcula", mas a causa raiz era essa,
    // rio acima na cadeia (nenhuma variante ativa pra resolver PARAM nenhum).
    activeVariantId: variantStore.activeVariantId,
    datasets: datasetStore.list(),
    camera: cameraState ?? null,
    cotas: cotaStore ? cotaStore.list() : [],
    category: categoryStore ? categoryStore.get() : null
  };
  return JSON.stringify(scene, null, 2);
}

export function deserializeScene(json) {
  const parsed = JSON.parse(json);
  if (!parsed || !Array.isArray(parsed.objects)) {
    throw new Error('Arquivo de cena invalido.');
  }
  return {
    objects: parsed.objects,
    primitives: Array.isArray(parsed.primitives) ? parsed.primitives : [],
    points: Array.isArray(parsed.points) ? parsed.points : [],
    parameters: Array.isArray(parsed.parameters) ? parsed.parameters : [],
    variants: Array.isArray(parsed.variants) ? parsed.variants : [],
    // Cenas salvas antes desta correcao (versao < 10) nao tem esse campo -
    // fica null (nenhuma variante ativa), mesmo comportamento de antes.
    activeVariantId: parsed.activeVariantId ?? null,
    datasets: Array.isArray(parsed.datasets) ? parsed.datasets : [],
    camera: parsed.camera ?? null,
    cotas: Array.isArray(parsed.cotas) ? parsed.cotas : [],
    category: parsed.category ?? null
  };
}

export function downloadSceneJSON(json, filename = 'cena-e3d-support.json') {
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

export function readSceneFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Falha ao ler o arquivo de cena.'));
    reader.onload = () => resolve(reader.result);
    reader.readAsText(file);
  });
}
