import { createCollapsibleSection } from './CollapsibleSection.js';

// Painel lateral esquerdo (primeiro da lista, acima de Parametros): os 2
// campos da CATEGORY do catalogo (ver core/CategoryStore.js) - nome (vira
// /<name>, /<name>-D, /<name>-PT, /<name>-GM, /<name>-DTS no DATAL
// exportado) e descricao (DESC da CATEGORY, reaproveitada como RTEX do
// SDTEXT). GTYP/PURP nao aparecem aqui - ficam fixos (ver CATEGORY_GTYPE/
// CATEGORY_PURPOSE), este app e sempre voltado a suportes.
export class CategoryPanel {
  constructor({ container, categoryStore }) {
    this.categoryStore = categoryStore;

    const { bodyEl } = createCollapsibleSection({ container, title: 'Categoria', defaultExpanded: false });
    this.container = bodyEl;

    this.container.innerHTML = `
      <div class="prop-group">
        <label class="prop-label">Nome (ex.: XYZ_SDE-37-005)</label>
        <input type="text" class="full" id="category-name" placeholder="XYZ_XXX-NNN-NNN" />
      </div>
      <div class="prop-group">
        <label class="prop-label">Descricao</label>
        <input type="text" class="full" id="category-description" placeholder="SUPORTE ESPECIAL TIPO XXX" />
      </div>
    `;

    this.nameInput = this.container.querySelector('#category-name');
    this.descriptionInput = this.container.querySelector('#category-description');

    this.nameInput.addEventListener('input', () => this.categoryStore.update({ name: this.nameInput.value }));
    this.descriptionInput.addEventListener('input', () => this.categoryStore.update({ description: this.descriptionInput.value }));

    categoryStore.on('category:updated', (data) => this._refresh(data));
    this._refresh(categoryStore.get());
  }

  _refresh(data) {
    if (document.activeElement !== this.nameInput) this.nameInput.value = data.name;
    if (document.activeElement !== this.descriptionInput) this.descriptionInput.value = data.description;
  }
}
