import * as THREE from 'three';
import { DEG2RAD } from './transformMath.js';

// Expressao de eixo/direcao no estilo PDMS (ver capitulo 5.5.8 do manual de
// referencia - PTCDIR): uma letra de eixo base (X/Y/Z, com sinal opcional),
// seguida de zero ou mais pares (angulo, eixo-alvo) que giram o vetor
// PROGRESSIVAMENTE em direcao a cada eixo-alvo, na ordem em que aparecem.
// Exemplos: "Y" (eixo Y puro), "-Y" (Y negativo), "Y45X" (Y girado 45 graus
// em direcao a X), "X30Y-20Z" (X girado 30 graus em direcao a Y, resultado
// girado -20 graus em direcao a Z).
//
// O sinal de um passo pode vir antes do ANGULO ("Z-45X") OU antes da LETRA
// alvo ("Z45-X", sintaxe AVEVA - "45 graus em direcao a -X") - as duas
// formas sao aceitas e dao o MESMO resultado matematico (girar `angulo`
// graus em direcao a `-alvo` e identico a girar `-angulo` graus em direcao a
// `alvo`: rotateTowards(v, -alvo, angulo) === rotateTowards(v, alvo,
// -angulo), ja que o eixo de rotacao usado - v x alvo - so troca de sinal).
//
// TAMBEM aceita uma referencia a um P-point em vez de uma expressao: "P n"
// (o correto - "PP n"/"PPOINT n" continuam aceitos como alias, pra nao
// quebrar dados ja salvos, mas "P n" e a forma certa do catalogo real) usa a
// direcao (PAXI/PTCDIR ja resolvida) do P-point cujo NUMB seja n -
// normalmente inserido pelo botao "PPnt" da UI, nao digitado a mao (ver
// ui/PropertiesPanel.js e ui/PointPickerDialog.js). Aceita sinal de menos
// opcional ("-P4") pra pegar a direcao OPOSTA do ponto, igual a um eixo
// composto normal ("-Y"), sem espaco obrigatorio entre a letra e o numero
// ("P4" ou "P 4", ambos validos). Isso cria uma dependencia circular em
// potencial (P-point A referencia P-point B que referencia A de volta) - a
// protecao contra ciclo fica em objects/PPointObject.js
// (resolvePointDirection), que e quem de fato chama de volta pro P-point
// referenciado.
//
// Uma referencia a P-point tambem devolve a POSICAO dele (`origin` no
// retorno de resolveAxisExpression) - usado por PAAX/PBAX de extrusao (ver
// objects/PrimitiveObject.js: resolvePrimitiveOrigin) para tratar a posicao
// do P-point como a origem (0,0,0) local da extrusao, nao so a orientacao.
// O sinal de menos NAO afeta essa posicao (so a direcao) - inverter a
// origem nao faria sentido nenhum.
const BASE_AXIS_VECTORS = {
  X: () => new THREE.Vector3(1, 0, 0),
  Y: () => new THREE.Vector3(0, 1, 0),
  Z: () => new THREE.Vector3(0, 0, 1)
};

const AXIS_EXPR_RE = /^(-?)([XYZ])((?:-?\d+(?:\.\d+)?-?[XYZ])*)$/;
const AXIS_STEP_RE = /(-?\d+(?:\.\d+)?)(-?)([XYZ])/g;
const POINT_REF_RE = /^(-?)(?:PP(?:OINT)?|P)\s*(\d+(?:\.\d+)?)$/i;

// Gira `v` por `angleRad` EM DIRECAO a `target` (nao ao redor de um eixo
// arbitrario) - formula de Rodrigues com o eixo de rotacao = v x target
// (perpendicular aos dois, entao o termo k*(k.v) do produto completo
// desaparece, ja que k.v=0 por construcao). Se v e target forem
// (anti)paralelos, o produto vetorial e degenerado (k indefinido) - nesse
// caso devolve v sem alteracao, ja que nao ha "em direcao a" bem definido
// pra algo que ja esta na mesma linha.
function rotateTowards(v, target, angleRad) {
  const axis = new THREE.Vector3().crossVectors(v, target);
  if (axis.lengthSq() < 1e-10) return v.clone();
  axis.normalize();
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);
  return v.clone().multiplyScalar(cos).add(axis.clone().cross(v).multiplyScalar(sin));
}

function parseCompoundAxis(trimmedUpper) {
  // Aceita espacos/parenteses em volta do angulo ("Z ( 45 ) Y", sintaxe real
  // confirmada pelo usuario em REFERENCIAS/SUP.pmlmac: `PTCDI Z ( 45 ) -Y`)
  // como equivalente a forma compacta "Z45Y" - os parenteses aqui so
  // decoram o angulo, nunca mudam o significado da expressao, entao remover
  // TODO espaco/parenteses antes de casar contra AXIS_EXPR_RE e seguro.
  const normalized = trimmedUpper.replace(/[\s()]/g, '');
  const match = normalized.match(AXIS_EXPR_RE);
  if (!match) return null;
  const [, sign, baseLetter, rest] = match;
  let vector = BASE_AXIS_VECTORS[baseLetter]();
  if (sign === '-') vector.negate();

  AXIS_STEP_RE.lastIndex = 0; // regex global - sempre resetar antes de reusar (ver utils/expressionEvaluator.js)
  let stepMatch;
  while ((stepMatch = AXIS_STEP_RE.exec(rest))) {
    // Sinal antes do angulo ("Z-45X") e sinal antes da letra alvo
    // ("Z45-X") sao equivalentes - ver comentario no topo do arquivo -
    // entao combina os dois num unico angulo com sinal antes de girar.
    let angleDeg = Number(stepMatch[1]);
    const targetSign = stepMatch[2];
    const targetVector = BASE_AXIS_VECTORS[stepMatch[3]]();
    if (targetSign === '-') angleDeg = -angleDeg;
    vector = rotateTowards(vector, targetVector, angleDeg * DEG2RAD);
  }
  return vector.normalize();
}

// Ligado por main.js (ver PPointObject.resolvePointDirection) - so existe UM
// PointStore no app inteiro, entao fica como estado de modulo em vez de mais
// um parametro threaded por toda funcao que hoje resolve eixo/direcao
// (mesmo raciocinio de utils/expressionEvaluator.js:setDatasetResolver).
let pointDirectionLookup = () => undefined;
let pointPositionLookup = () => undefined;

export function setPointDirectionLookup(fn) {
  pointDirectionLookup = fn;
}

export function setPointPositionLookup(fn) {
  pointPositionLookup = fn;
}

export function hasPointRef(raw) {
  return POINT_REF_RE.test(String(raw ?? '').trim());
}

// Resolve uma expressao de eixo pro vetor direcao (THREE.Vector3, unitario)
// correspondente. Devolve {direction, origin, error} - nunca lanca excecao,
// pra UI poder mostrar o erro como dica (mesmo padrao de
// utils/expressionEvaluator.js). `origin` so vem preenchido quando a
// expressao e uma referencia a P-point ("PP n") - a posicao (THREE.Vector3)
// desse P-point; null pra uma expressao de eixo composto normal ("Y45X"),
// que nao tem posicao nenhuma associada.
export function resolveAxisExpression(raw) {
  const trimmed = String(raw ?? '').trim();
  if (trimmed === '') return { direction: null, origin: null, error: 'Vazio' };

  const pointMatch = trimmed.match(POINT_REF_RE);
  if (pointMatch) {
    const negate = pointMatch[1] === '-';
    const number = Number(pointMatch[2]);
    const direction = pointDirectionLookup(number);
    if (!direction) return { direction: null, origin: null, error: `P-point NUMB ${number} nao encontrado` };
    const origin = pointPositionLookup(number) ?? null;
    return { direction: negate ? direction.clone().negate() : direction, origin, error: null };
  }

  const direction = parseCompoundAxis(trimmed.toUpperCase());
  if (!direction) return { direction: null, origin: null, error: `Expressao de eixo invalida: "${trimmed}"` };
  return { direction, origin: null, error: null };
}
