// Wrapper reutilizado por todos os paineis da barra lateral esquerda
// (Parametros, Cena, Primitivas, Pontos): um cabecalho clicavel que
// expande/colapsa o corpo, para dar espaco a novos paineis que forem
// surgindo sem esmagar os existentes. `nested: true` aplica um estilo mais
// discreto, para sub-secoes dentro de um painel (ex.: Definicoes de
// parametro / Variantes dentro do painel Parametros).
let idCounter = 0;

export function createCollapsibleSection({ container, title, defaultExpanded = false, nested = false }) {
  const id = `collapsible-${++idCounter}`;
  const wrapper = document.createElement('div');
  wrapper.className = nested ? 'collapsible-section collapsible-section-nested' : 'collapsible-section';
  wrapper.innerHTML = `
    <button type="button" class="collapsible-header" aria-expanded="${defaultExpanded}" aria-controls="${id}">
      <span class="collapsible-arrow${defaultExpanded ? ' expanded' : ''}"></span>
      <span class="collapsible-title">${title}</span>
    </button>
    <div class="collapsible-body" id="${id}" ${defaultExpanded ? '' : 'hidden'}></div>
  `;
  container.appendChild(wrapper);

  const header = wrapper.querySelector('.collapsible-header');
  const arrow = wrapper.querySelector('.collapsible-arrow');
  const bodyEl = wrapper.querySelector('.collapsible-body');
  let expanded = defaultExpanded;

  header.addEventListener('click', () => {
    expanded = !expanded;
    bodyEl.hidden = !expanded;
    arrow.classList.toggle('expanded', expanded);
    header.setAttribute('aria-expanded', String(expanded));
  });

  return { wrapper, bodyEl };
}
