import { convertInchLiterals } from '../utils/expressionEvaluator.js';
import { CATEGORY_GTYPE, CATEGORY_PURPOSE } from '../core/CategoryStore.js';

// Exportador de "DATAL" - o texto de macro PML (.pmlmac) que cria uma
// CATEGORY inteira no catalogo do E3D (DTSET + TEXT de parametro + PTSET +
// GMSET + um SCOMPONENT por variante), no MESMO formato dos 2 exemplos reais
// em REFERENCIAS/*.pmlmac. As referencias usadas para construir este
// tradutor:
//   - REFERENCIAS/SUPORTE_SDE-37-005.pmlmac e
//     REFERENCIAS/SUPORTE COM DATASET.pmlmac - 2 arquivos reais, ja
//     importados com sucesso no PARAGON - confirmam CATEGORY/SDTEXT/DTSET/
//     DATA/TEXT/PTSET/PTAXIS/PTCAR/GMSET/SBOX/SCYLINDER/SCOMPONENT e o bloco
//     final OLD/PTRE/GMRE/DTRE/INPUT END/INPUT FINISH.
//   - REFERENCIAS/172166728-Catalogues-and-Specifications-Reference-Manual.pdf,
//     capitulo 7 (nomes de atributo de cada primitiva/P-point) e capitulo 8
//     (DTSET/DATA, RPROP).
//
// IMPORTANTE: nem tudo aqui tem um exemplo real confirmado - ver os
// comentarios "NAO CONFIRMADO" em cada builder de primitiva/P-point sem
// exemplo real (Cone/Esfera/Disco/Piramide/Snout/Toro/Extrusao,
// PTMIX/PTPOS). Esses usam os nomes de atributo exatamente como documentados
// no manual, mas a GRAFIA do elemento (ex.: "SCON" vs algum sinonimo mais
// longo, como aconteceu com "SCYLINDER" vs "SCYL") no e garantida sem testar
// um import de verdade no PARAGON. `generateDatal` devolve uma lista de
// avisos (`warnings`) sinalizando essas partes nao confirmadas e outras
// simplificacoes conhecidas (ver comentario de cada builder).
//
// Ponto crucial: a exportacao usa as EXPRESSOES BRUTAS de cada campo (nunca
// o valor resolvido contra a variante ativa) - o mesmo GMSET/PTSET/DTSET tem
// que servir para TODOS os SCOMPONENTs (variantes), exatamente como nos
// exemplos reais (uma unica SBOX com "ATTRIB PARA[12]" e reaproveitada por
// JJ/LL/NN, cada uma com seus proprios valores de PARA).

// "P n"/"PP n"/"PPOINT n" (ver utils/axisExpression.js) normaliza para a
// forma confirmada pelo exemplo real ("PAXI P3", sem espaco antes do
// numero) na hora de exportar, independente de como o usuario digitou.
const POINT_REF_RE = /^(-?)(?:PP(?:OINT)?|P)\s*(\d+(?:\.\d+)?)$/i;

// Referencia isolada a parametro (nada mais na expressao) - os exemplos reais
// usam a palavra "PARAM"/"PARA" direto (ex.: "PCON PARAM 3"), sem o
// pseudo-atributo ATTRIB - diferente de quando o parametro entra numa
// aritmetica maior (ver pmlExpr abaixo).
const BARE_PARAM_RE = /^PARA(?:M)?\s*\[?\s*(\d+)\s*\]?$/i;
// Sem "\s*" antes do "\]?" final (diferente do PARAM_TOKEN do
// expressionEvaluator.js) - aqui o resultado e TEXTO final exportado, nao
// reavaliado por um parser tolerante a espaco depois; sem essa mudanca, um
// espaco legitimo entre o numero e o proximo operador (ex.: "PARAM 1 / 2")
// seria engolido junto (virando "ATTRIB PARA[1 ]/ 2", sem espaco antes da barra).
const PARAM_TOKEN_G = /PARA(?:M)?\s*\[?\s*(\d+)\]?/gi;
const RPRO_TOKEN_G = /RPRO(?:P)?\s+([A-Za-z][A-Za-z0-9_]*)/gi;
const OPERATOR_OR_TOKEN_TEST = /[+\-*/()]|PARA(?:M)?\s*\[?\s*\d+|RPRO(?:P)?\s+[A-Za-z]|\d+(?:\.\d+)?\s*in(?:ch(?:es)?)?\b/i;

function escapeQuote(text) {
  return String(text ?? '').replace(/'/g, "''");
}

// Traduz UMA expressao do app (numero, "PARAM n", aritmetica, "RPRO/RPROP
// <dkey>", "2.5in") para o texto PML equivalente - NUNCA avalia/resolve o
// valor (isso destruiria a parametrizacao: o mesmo GMSET tem que valer para
// todas as variantes). Ver cabecalho do arquivo.
function pmlExpr(raw) {
  const trimmed = String(raw ?? '').trim();
  if (trimmed === '') return '0';

  const bareParam = trimmed.match(BARE_PARAM_RE);
  if (bareParam) return `PARAM ${bareParam[1]}`; // ex.: "PCON PARAM 3" nos exemplos reais

  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return trimmed; // numero puro - sem parenteses, ex.: "PY 0"

  if (!OPERATOR_OR_TOKEN_TEST.test(trimmed)) return trimmed; // palavra solta (eixo, "WELD", "ATT", ...)

  let working = convertInchLiterals(trimmed);
  working = working.replace(RPRO_TOKEN_G, (_m, dkey) => `RPROP ${dkey.toUpperCase()}`);
  working = working.replace(PARAM_TOKEN_G, (_m, n) => `ATTRIB PARA[${n} ]`);
  return `( ${working} )`;
}

// So para PPRO/DPRO de uma entrada de Dataset - os exemplos reais SEMPRE
// envolvem em parenteses E expandem PARAM pra "ATTRIB PARA[n ]", mesmo numa
// referencia isolada (ex.: "PPRO ( ATTRIB DESP[1 ] )") - diferente do
// PCON/PBOR de um P-point, que usa a forma curta "PARAM n" sem parenteses
// nesse caso (ver pmlExpr acima, e o proprio exemplo real: "PCON PARAM 3").
// Por isso NAO reusa o atalho de referencia isolada de pmlExpr aqui.
function pmlExprForDataset(raw) {
  const trimmed = String(raw ?? '').trim();
  if (trimmed === '') return '( 0 )';
  let working = convertInchLiterals(trimmed);
  working = working.replace(RPRO_TOKEN_G, (_m, dkey) => `RPROP ${dkey.toUpperCase()}`);
  working = working.replace(PARAM_TOKEN_G, (_m, n) => `ATTRIB PARA[${n} ]`);
  return `( ${working} )`;
}

// Eixo/direcao (PAXI/PAAX/PBAX/PTCDIR/etc. - ver utils/axisExpression.js) -
// passa direto (ja esta na sintaxe PTCDIR real), so normaliza uma referencia
// a P-point pra forma confirmada "P3" (sem espaco).
function pmlAxis(raw) {
  const trimmed = String(raw ?? '').trim();
  if (trimmed === '') return null;
  const m = trimmed.match(POINT_REF_RE);
  if (m) return `${m[1]}P${m[2]}`;
  return trimmed;
}

function exprLine(name, raw) {
  return `${name} ${pmlExpr(raw)}`;
}

function axisLine(name, raw) {
  const value = pmlAxis(raw);
  return value === null ? null : `${name} ${value}`;
}

function isZeroLiteral(raw) {
  return String(raw ?? '').trim() === '0';
}

// Monta um bloco `NEW <header> ... END ` (com filhos opcionais, cada um ja
// sendo um array de linhas de um `block()` aninhado) - ver comentario no
// topo sobre a convencao NEW/END uniforme do PML (mesmo elementos "folha",
// sem membros, usam esse par).
function block(header, attrLines, innerBlocks = []) {
  const lines = [`NEW ${header}`, ...attrLines.filter((line) => line !== null && line !== undefined)];
  innerBlocks.forEach((inner) => {
    lines.push('');
    lines.push(...inner);
  });
  lines.push('');
  lines.push('END ');
  return lines;
}

// ---------------------------------------------------------------------------
// Primitivas (GMSET) - ver capitulo 7.4 do manual. CONFIRMADO por exemplo
// real: Caixa (SBOX) e Cilindro (SCYLINDER). Os outros 6 usam os nomes de
// atributo do manual, sem confirmacao de import real - ver aviso no topo.
// ---------------------------------------------------------------------------

// `negative: true` acrescenta NAPP E troca o nome do elemento (capitulo 7.5
// do manual: elemento negativo tem PALAVRA-CHAVE PROPRIA, nao e "o mesmo
// elemento positivo com uma flag" - lista oficial de mnemonicos curtos:
// NSBO/NSCY/NLPY/etc.). Sem exemplo real confirmando a grafia do NEGATIVO
// especificamente, seguimos a mesma convencao ja comprovada pro POSITIVO
// nesta base (PARAGON aceita o nome "longo" em vez do mnemonico curto do
// manual - SCYLINDER em vez de SCYL, LPYRAMID em vez de LPYR, ambos
// confirmados por import real) - decisao explicita do usuario: "N" + nome
// longo do positivo (NSBOX, NSCYLINDER, NLPYRAMID), nao o mnemonico curto do
// manual (NSBO/NSCY/NLPY) nem o nome do positivo sem prefixo. Os demais
// atributos sao IDENTICOS ao positivo (mesmo capitulo: "Negative Primitives
// have the same attributes as the corresponding positive primitives"), por
// isso reaproveita a mesma funcao em vez de duplicar.
// `childBlocks` (ver comentario em buildPrimitiveBlock/generateDatal mais
// abaixo): blocos de elemento(s) NEGATIVO(s) vinculado(s) a esta primitiva
// (`parentId`) - ficam ANINHADOS dentro do NEW/END desta primitiva (mesma
// convencao NEW/END aninhada ja usada por SLOO/SVER da extrusao), NAO como
// item irmao na lista do GMSET - sintaxe confirmada pelo usuario contra o
// E3D de verdade.
function buildBoxBlock(data, { negative = false, childBlocks = [] } = {}) {
  return block(
    negative ? 'NSBOX' : 'SBOX',
    [
      'TUFL true',
      exprLine('PX', data.position.x),
      exprLine('PY', data.position.y),
      exprLine('PZ', data.position.z),
      exprLine('PXLE', data.dimensions.width),
      exprLine('PYLE', data.dimensions.depth),
      exprLine('PZLE', data.dimensions.height),
      negative ? 'NAPP 4' : null
    ],
    childBlocks
  );
}

function buildCylinderBlock(data, { negative = false, childBlocks = [] } = {}) {
  return block(
    negative ? 'NSCYLINDER' : 'SCYLINDER',
    [
      'CLFL true',
      'TUFL true',
      exprLine('PDIS', data.distance),
      exprLine('PDIA', data.dimensions.diameter),
      exprLine('PHEI', data.dimensions.height),
      axisLine('PAXI', data.axis),
      negative ? 'NAPP 4' : null
    ],
    childBlocks
  );
}

// NAO CONFIRMADO (so manual, cap. 7.4.3) - PDIS aqui e a altura do apice
// acima da base (dims.height JA E o PDIS - ver core/PrimitiveObject.js:
// resolveConeOrigin - o cone nao tem offset separado da base).
function buildConeBlock(data, { childBlocks = [] } = {}) {
  return block(
    'SCON',
    ['TUFL true', axisLine('PAXI', data.axis), exprLine('PDIS', data.dimensions.height), exprLine('PDIA', data.dimensions.diameter)],
    childBlocks
  );
}

// NAO CONFIRMADO (so manual, cap. 7.4.15). LIMITACAO: SSPH so tem PAXI+PDIS
// no catalogo real (sem posicao livre X/Y) - PAXI fica fixo em Z e so
// position.z vira PDIS; position.x/position.y da primitiva (que o app
// permite editar livremente) NAO tem equivalente real e sao descartados -
// ver o aviso emitido em buildPrimitiveBlock quando x/y != 0.
function buildSphereBlock(data, { childBlocks = [] } = {}) {
  return block('SSPH', ['TUFL true', 'PAXI Z', exprLine('PDIS', data.position.z), exprLine('PDIA', data.dimensions.diameter)], childBlocks);
}

// NAO CONFIRMADO (so manual, cap. 7.4.7) - mesma limitacao do SSPH acima
// (sem posicao livre X/Y no catalogo real).
function buildDiscBlock(data, { childBlocks = [] } = {}) {
  return block('SDIS', ['PAXI Z', exprLine('PDIS', data.position.z), exprLine('PDIA', data.dimensions.diameter)], childBlocks);
}

// Mapeamento B<->X, C<->Y ja documentado em core/PrimitiveStore.js:
// PBAX/PCAX/PAAX = axisX/axisY/axisZ.
// CONFIRMADO por exemplo real (REFERENCIAS/PYRA.PMLMAC): o elemento se
// chama "LPYRAMID" no PML de verdade, nao "LPYR" (nome curto do capitulo
// 7.4.11 do manual - PARAGON aceita o nome longo no export). O mesmo
// arquivo tambem confirma que PBAX/PCAX ficam DE FORA do export quando
// valem o padrao (X/Y) - PARAGON so escreve o que difere do default. Aqui
// exportamos sempre os 3 eixos explicitamente por simplicidade (um valor
// explicito igual ao padrao e inofensivo pro PARAGON reimportar), mas se
// algum dia isso causar problema, e essa a diferenca a investigar primeiro.
// `negative: true` -> NLPYRAMID (elemento negativo - ver capitulo 7.5 do
// manual e o comentario de buildBoxBlock/buildCylinderBlock acima sobre a
// convencao "N" + nome longo do positivo) + NAPP. Nome NAO confirmado por
// exemplo real (so LPYRAMID positivo foi confirmado).
function buildPyramidBlock(data, { negative = false, childBlocks = [] } = {}) {
  const d = data.dimensions;
  return block(
    negative ? 'NLPYRAMID' : 'LPYRAMID',
    [
      'TUFL true',
      axisLine('PAAX', data.axisZ),
      axisLine('PBAX', data.axisX),
      axisLine('PCAX', data.axisY),
      exprLine('PBBT', d.bottomWidth),
      exprLine('PCBT', d.bottomDepth),
      exprLine('PBTP', d.topWidth),
      exprLine('PCTP', d.topDepth),
      // `dimensions.distBottom` agora E a coordenada com sinal do PBDI real
      // (ver objects/PrimitiveObject.js: buildPyramidGeometry) - passthrough
      // direto, sem negar.
      exprLine('PBDI', d.distBottom),
      exprLine('PTDI', d.distTop),
      exprLine('PBOF', d.offsetX),
      exprLine('PCOF', d.offsetY),
      negative ? 'NAPP 4' : null
    ],
    childBlocks
  );
}

// NAO CONFIRMADO (so manual, cap. 7.4.14).
function buildSnoutBlock(data, { childBlocks = [] } = {}) {
  const d = data.dimensions;
  return block(
    'LSNO',
    [
      'TUFL true',
      axisLine('PAAX', data.axisA),
      axisLine('PBAX', data.axisB),
      exprLine('PBDM', d.bottomDiameter),
      exprLine('PTDM', d.topDiameter),
      // Mesma convencao da piramide acima - `distBottom` ja e a coordenada
      // com sinal, passthrough direto.
      exprLine('PBDI', d.distBottom),
      exprLine('PTDI', d.distTop),
      exprLine('POFF', d.offset)
    ],
    childBlocks
  );
}

// NAO CONFIRMADO (so manual, cap. 7.4.12) - PAAX/PBAX aqui SEMPRE
// referenciam um P-point cada no app (exigido pela ferramenta - ver
// core/PrimitiveObject.js: resolveTorusArc), entao pmlAxis normaliza pra
// "Pn"/"-Pn" igual aos outros eixos.
function buildTorusBlock(data, { childBlocks = [] } = {}) {
  return block(
    'SCTO',
    ['TUFL true', axisLine('PAAX', data.axisA), axisLine('PBAX', data.axisB), exprLine('PDIA', data.dimensions.diameter)],
    childBlocks
  );
}

// CONFIRMADO por exemplo real (REFERENCIAS/SUP.pmlmac, adicionado
// 2026-09-27): o elemento se chama "SRTORUS" no PML de verdade (nao "SRTO"
// nem "RTOR", os 2 nomes so-por-manual usados antes disso) - mesmos
// atributos ja assumidos (PAAX/PBAX referenciando um P-point cada, PDIA,
// PHEI), confirmados pelo exemplo: `PAAX P3` / `PBAX P4` / `PDIA PARAM 4` /
// `PHEI PARAM 5`.
function buildTorusRectBlock(data, { childBlocks = [] } = {}) {
  return block(
    'SRTORUS',
    [
      'TUFL true',
      axisLine('PAAX', data.axisA),
      axisLine('PBAX', data.axisB),
      exprLine('PDIA', data.dimensions.diameter),
      exprLine('PHEI', data.dimensions.height)
    ],
    childBlocks
  );
}

// NAO CONFIRMADO (so manual, cap. 7.4.17) - SLOO/SVER sao filhos aninhados
// dentro do SEXT (mesma convencao NEW/END dos demais elementos) - qualquer
// elemento NEGATIVO vinculado (`childBlocks`) entra na MESMA lista de filhos,
// depois do SLOO.
function buildExtrusionBlock(data, { childBlocks = [] } = {}) {
  const vertexBlocks = (data.vertices ?? []).map((v) =>
    block('SVER', [exprLine('PX', v.x), exprLine('PY', v.y), exprLine('PRAD', v.radius)])
  );
  const slooBlock = block('SLOO', [], vertexBlocks);
  return block(
    'SEXT',
    [
      'TUFL true',
      exprLine('PX', data.position.x),
      exprLine('PY', data.position.y),
      exprLine('PZ', data.position.z),
      axisLine('PAAX', data.axisA),
      axisLine('PBAX', data.axisB),
      exprLine('PHEI', data.dimensions.height)
    ],
    [slooBlock, ...childBlocks]
  );
}

const PRIMITIVE_BUILDERS = {
  box: buildBoxBlock,
  cylinder: buildCylinderBlock,
  cone: buildConeBlock,
  sphere: buildSphereBlock,
  disc: buildDiscBlock,
  pyramid: buildPyramidBlock,
  snout: buildSnoutBlock,
  torus: buildTorusBlock,
  torusRect: buildTorusRectBlock,
  extrusion: buildExtrusionBlock,
  // Elemento negativo (ver core/PrimitiveStore.js: NEGATIVE_PRIMITIVE_TYPES) -
  // MESMOS atributos do positivo correspondente + NAPP (ver comentario em
  // buildBoxBlock acima sobre a convencao de nome negativo). Um negativo
  // nunca tem filhos (nao pode ser pai de outro negativo), mas `opts` e
  // repassado por uniformidade.
  negBox: (data, opts) => buildBoxBlock(data, { ...opts, negative: true }),
  negCylinder: (data, opts) => buildCylinderBlock(data, { ...opts, negative: true }),
  negPyramid: (data, opts) => buildPyramidBlock(data, { ...opts, negative: true })
};

// Tipos sem exemplo real confirmado (ver cabecalho do arquivo) - usado so
// para agrupar um unico aviso por tipo realmente presente na cena, em vez de
// repetir o aviso por primitiva.
// 'pyramid' CONFIRMADO por exemplo real (REFERENCIAS/PYRA.PMLMAC) e
// 'torusRect' CONFIRMADO por exemplo real (REFERENCIAS/SUP.pmlmac,
// "SRTORUS" - ver buildTorusRectBlock) - os 2 sairam desta lista. Os outros
// continuam so pelo manual, sem exemplo real.
const UNVERIFIED_PRIMITIVE_TYPES = new Set(['cone', 'sphere', 'disc', 'snout', 'torus', 'extrusion']);
const UNVERIFIED_POINT_TYPES = new Set(['PTMIX', 'PTPOS']);

function buildPrimitiveBlock(data, warnings, childBlocks = []) {
  if ((data.type === 'sphere' || data.type === 'disc') && (!isZeroLiteral(data.position.x) || !isZeroLiteral(data.position.y))) {
    const kw = data.type === 'sphere' ? 'SSPH' : 'SDIS';
    warnings.push(
      `Primitiva "${data.name}" (${data.type}): X/Y da posicao foram IGNORADOS na exportacao - ${kw} do catalogo real so tem PAXI+PDIS (sem posicao livre). So a distancia ao longo de Z foi exportada.`
    );
  }
  // `data.parentId` (elemento negativo - ver core/PrimitiveStore.js) e SO
  // vinculo organizacional (agrupamento/aninhamento no GMSET, ver
  // buildGeomSetMemberBlocks mais abaixo) - posicao/eixo de `data` ja sao
  // ABSOLUTOS (mesma convencao de um positivo comum, ver
  // objects/PrimitiveObject.js: resolvePrimitiveOrigin), entao exportar TAL
  // COMO DIGITADOS ja bate com o catalogo real sem nenhum ajuste manual.
  //
  // `childBlocks`: blocos (ja montados, um array de linhas cada) de
  // elemento(s) NEGATIVO(s) vinculados a ESTA primitiva - ficam ANINHADOS
  // dentro do NEW/END dela (sintaxe confirmada pelo usuario contra o E3D de
  // verdade: o NEW do positivo so fecha com END DEPOIS do NEW/END de cada
  // negativo seu, nao antes).
  const builder = PRIMITIVE_BUILDERS[data.type] ?? buildBoxBlock;
  return builder(data, { childBlocks });
}

// ---------------------------------------------------------------------------
// P-points (PTSET) - ver capitulo 7.1 do manual. CONFIRMADO por exemplo
// real: PTAXI (grafia real do elemento: "PTAXIS", com S) e PTCAR. PTMIX/
// PTPOS usam a grafia exata do manual, sem confirmacao real.
// ---------------------------------------------------------------------------

function buildPointBlock(data) {
  const common = ['PCON', 'PBOR'].map((attr) =>
    attr === 'PCON' ? exprLine('PCON', data.connectionType) : exprLine('PBOR', data.bore)
  );
  const tail = [
    data.description ? `DESC '${escapeQuote(data.description)}'` : null,
    data.purpose ? `PURP ${data.purpose.trim()}` : null
  ];

  if (data.pointType === 'PTAXI') {
    return block('PTAXIS', [`NUMB ${data.number}`, ...common, exprLine('PDIS', data.distance), axisLine('PAXI', data.axis), ...tail]);
  }
  if (data.pointType === 'PTMIX') {
    return block('PTMIX', [
      `NUMB ${data.number}`,
      ...common,
      exprLine('PX', data.position.x),
      exprLine('PY', data.position.y),
      exprLine('PZ', data.position.z),
      axisLine('PAXI', data.axis),
      ...tail
    ]);
  }
  if (data.pointType === 'PTPOS') {
    return block('PTPOS', [
      `NUMB ${data.number}`,
      ...common,
      data.positionExpr && data.positionExpr.trim() !== '' ? `PTCPOS ${data.positionExpr.trim()}` : null,
      data.directionExpr && data.directionExpr.trim() !== '' ? `PTCD ${data.directionExpr.trim()}` : null,
      ...tail
    ]);
  }
  // PTCAR (default) - PTCDIR usa a MESMA expressao de eixo composta do PAXI
  // (ver utils/axisExpression.js e objects/PPointObject.js), so muda o nome
  // do atributo. "PTCDI" (sem R) e a grafia confirmada pelo exemplo real
  // (REFERENCIAS/SUPORTE COM DATASET.pmlmac: `PTCDI X`/`PTCDI Z`).
  return block('PTCAR', [
    `NUMB ${data.number}`,
    ...common,
    exprLine('PX', data.position.x),
    exprLine('PY', data.position.y),
    exprLine('PZ', data.position.z),
    axisLine('PTCDI', data.axis),
    ...tail
  ]);
}

// ---------------------------------------------------------------------------
// Dataset (DTSET/DATA) - ver capitulo 8.1. Mapeamento 1:1 com
// core/DatasetStore.js, confirmado pelos 2 exemplos reais.
// ---------------------------------------------------------------------------

// PURP DESP (parametro de projetista, capitulo 8.1 do manual): no PARAGON de
// verdade o PPRO desse tipo de entrada e GERADO a partir do NUMB
// ("ATTRIB DESP[n ]", mesmo padrao de "ATTRIB PARA[n ]") - decisao explicita
// do usuario. O `ppro` GUARDADO no store, porem, e o valor que o app usa pra
// PREVIEW em tempo real (via "RPRO <dkey>" - ver utils/expressionEvaluator.js)
// - nao ha um "valor de DESP" de verdade resolvivel neste app (o projetista
// so digita isso ao posicionar o componente no design real). Por isso essa
// geracao acontece SO AQUI, na hora de exportar, sem tocar/sobrescrever o
// `ppro` do store - ver comentario em ui/DatasetsPanel.js sobre o bug real
// que isso corrige (uma versao anterior escrevia o texto PML bruto direto no
// `ppro` e desabilitava o campo, quebrando qualquer primitiva que
// referenciava essa entrada via RPRO).
function despPproOverride(entry) {
  if (entry.purp !== 'DESP') return null;
  const number = entry.number;
  return number === null || number === undefined || number === '' ? null : `ATTRIB DESP[${number} ]`;
}

function buildDatasetEntryBlock(entry, warnings) {
  const despOverride = despPproOverride(entry);
  if (entry.purp === 'DESP' && despOverride === null) {
    warnings.push(
      `Entrada de Dataset "${entry.dkey}": PURP=DESP mas NUMB esta vazio - PPRO nao foi exportado (deveria virar "ATTRIB DESP[n ]", preencha NUMB).`
    );
  }
  const pproLine = despOverride
    ? `PPRO ( ${despOverride} )`
    : entry.ppro && entry.ppro.trim() !== ''
      ? `PPRO ${pmlExprForDataset(entry.ppro)}`
      : null;
  return block('DATA', [
    `DKEY ${entry.dkey.trim().toUpperCase()}`,
    entry.ptyp && entry.ptyp.trim() !== '' ? `PTYP ${entry.ptyp.trim()}` : null,
    pproLine,
    entry.dpro && entry.dpro.trim() !== '' ? `DPRO ${pmlExprForDataset(entry.dpro)}` : null,
    entry.purp && entry.purp.trim() !== '' ? `PURP ${entry.purp.trim()}` : null,
    entry.number !== null && entry.number !== undefined && entry.number !== '' ? `NUMB ${entry.number}` : null,
    entry.dtit && entry.dtit.trim() !== '' ? `DTIT '${escapeQuote(entry.dtit)}'` : null
  ]);
}

// ---------------------------------------------------------------------------
// Montagem final: CATEGORY -> SDTEXT, DTSET, TEXT (parametros + PTSE/GMSE),
// PTSET, GMSET, um SCOMPONENT por variante - depois o bloco OLD/PTRE/GMRE/
// DTRE e o rodape INPUT END/INPUT FINISH, exatamente na ordem dos 2
// exemplos reais.
// ---------------------------------------------------------------------------

function buildComponentBlock(variant, parameterDefs) {
  const values = parameterDefs.map((p) => {
    const raw = variant.values[p.number];
    return raw === undefined || raw === null || String(raw).trim() === '' ? '0' : String(raw).trim();
  });
  const name = variant.name.startsWith('/') ? variant.name : `/${variant.name}`;
  return block(`SCOMPONENT ${name}`, [`GTYP ${CATEGORY_GTYPE}`, `PARA ${values.join(' ')}`]);
}

// Monta os blocos-membro do GMSET: cada positivo com os blocos dos seus
// proprios negativos (`parentId`) ANINHADOS dentro do seu NEW/END (ver
// comentario em buildPrimitiveBlock sobre `childBlocks` - sintaxe
// confirmada pelo usuario contra o E3D de verdade: nao existe NGMSET
// separado, o NEW do positivo so fecha DEPOIS do NEW/END de cada negativo
// seu). Um negativo orfao (parentId aponta pra algo que sumiu - nao deveria
// acontecer, removePrimitive cascateia, mas por seguranca) cai solto no
// final, no nivel do GMSET.
function buildGeomSetMemberBlocks(all, warnings) {
  const byParent = new Map();
  const positives = [];
  for (const item of all) {
    if (item.parentId) {
      if (!byParent.has(item.parentId)) byParent.set(item.parentId, []);
      byParent.get(item.parentId).push(item);
    } else {
      positives.push(item);
    }
  }
  const seenParents = new Set();
  const memberBlocks = [];
  for (const positive of positives) {
    seenParents.add(positive.id);
    const childBlocks = (byParent.get(positive.id) ?? []).map((child) => buildPrimitiveBlock(child, warnings));
    memberBlocks.push(buildPrimitiveBlock(positive, warnings, childBlocks));
  }
  for (const [parentId, children] of byParent) {
    if (!seenParents.has(parentId)) {
      children.forEach((child) => memberBlocks.push(buildPrimitiveBlock(child, warnings)));
    }
  }
  return memberBlocks;
}

export function generateDatal({ categoryStore, parameterStore, variantStore, datasetStore, pointStore, primitiveStore }) {
  const warnings = [];
  const category = categoryStore.get();
  const name = category.name.trim();
  if (name === '') {
    warnings.push('Nome da Categoria esta vazio - preencha o painel "Categoria" antes de exportar (o DATAL abaixo tera referencias como "/-PT" invalidas).');
  }
  const description = category.description.trim();

  const parameterDefs = parameterStore.list().slice().sort((a, b) => a.number - b.number);
  const variants = variantStore.list();
  if (variants.length === 0) {
    warnings.push('Nenhuma variante (Componente) definida - o DATAL exportado nao tera nenhum SCOMPONENT.');
  }
  if (primitiveStore.list().length === 0) {
    warnings.push('Nenhuma primitiva na cena - o GMSET exportado ficara vazio.');
  }

  // Elemento negativo (`parentId` - ver core/PrimitiveStore.js) NAO vai pra
  // um NGMSET separado - instrucao explicita do usuario, confirmada contra o
  // E3D de verdade: DATAL nao tem um bloco NGMSET proprio, os negativos sao
  // membros do MESMO GMSET do positivo, ANINHADOS dentro do NEW/END dele -
  // o NEW do positivo so fecha com END DEPOIS do NEW/END de cada negativo
  // seu (a palavra-chave do elemento - NSBOX/NSCYLINDER/NLPYRAMID, ver
  // buildBoxBlock/buildCylinderBlock/buildPyramidBlock acima - e o NAPP e
  // que marcam que e negativo, nao um bloco/lista separada).
  // `buildGeomSetMemberBlocks` monta esse aninhamento.
  const negativePrimitives = primitiveStore.list().filter((p) => p.parentId);
  if (negativePrimitives.length > 0) {
    warnings.push(
      `A palavra-chave dos elementos negativos (NSBOX/NSCYLINDER/NLPYRAMID) e o atributo NAPP nao tem exemplo real confirmado neste app - so o capitulo 7.5 do manual + convencao acordada com o usuario. Valide com atencao extra no PARAGON.`
    );
  }

  const usedUnverifiedPrimitives = new Set(primitiveStore.list().map((p) => p.type).filter((t) => UNVERIFIED_PRIMITIVE_TYPES.has(t)));
  if (usedUnverifiedPrimitives.size > 0) {
    warnings.push(
      `Tipos de primitiva sem exemplo real confirmado usados nesta cena: ${[...usedUnverifiedPrimitives].join(', ')} (mapeados so pelo capitulo 7.4 do manual) - valide o import no PARAGON antes de confiar no resultado.`
    );
  }
  const usedUnverifiedPoints = new Set(pointStore.list().map((p) => p.pointType).filter((t) => UNVERIFIED_POINT_TYPES.has(t)));
  if (usedUnverifiedPoints.size > 0) {
    warnings.push(`Subtipos de P-point sem exemplo real confirmado usados nesta cena: ${[...usedUnverifiedPoints].join(', ')} (mapeados so pelo capitulo 7.1 do manual).`);
  }

  const sdtextBlock = block(`SDTEXT /${name}-D`, [`RTEX '${escapeQuote(description)}'`]);
  const datasetBlock = block(`DTSET /${name}-DTS`, [], datasetStore.list().map((entry) => buildDatasetEntryBlock(entry, warnings)));
  const parameterTextBlocks = parameterDefs.map((p) => block(`TEXT /${name}-PA${p.number}`, [`STEX '${escapeQuote(p.description)}'`]));
  const ptseTextBlock = block(`TEXT /${name}-PTSE`, [`STEX '${name}-PT'`]);
  const gmseTextBlock = block(`TEXT /${name}-GMSE`, [`STEX '${name}-GM'`]);
  const pointSetBlock = block(`PTSET /${name}-PT`, [], pointStore.list().map((p) => buildPointBlock(p)));
  const geomSetBlock = block(`GMSET /${name}-GM`, [], buildGeomSetMemberBlocks(primitiveStore.list(), warnings));
  const componentBlocks = variants.map((v) => buildComponentBlock(v, parameterDefs));

  const categoryBlock = block(
    `CATEGORY /${name}`,
    [`DESC '${escapeQuote(description)}'`, `PURP ${CATEGORY_PURPOSE}`, `GTYP ${CATEGORY_GTYPE}`],
    [sdtextBlock, datasetBlock, ...parameterTextBlocks, ptseTextBlock, gmseTextBlock, pointSetBlock, geomSetBlock, ...componentBlocks]
  );

  const trailerLines = [`OLD CATEGORY /${name}`, `CDET SDTEXT /${name}-D `, ''];
  variants.forEach((v) => {
    const vname = v.name.startsWith('/') ? v.name : `/${v.name}`;
    trailerLines.push(`OLD SCOMPONENT ${vname}`, `PTRE PTSET /${name}-PT `, `GMRE GMSET /${name}-GM `, `DTRE DTSET /${name}-DTS `, '');
  });

  const lines = ['INPUT BEGIN', ...categoryBlock, ...trailerLines, `INPUT END  CATEGORY /${name}`, 'INPUT FINISH'];

  return { text: lines.join('\n'), warnings };
}

export function downloadDatalFile(text, filename = 'datal-export.pmlmac') {
  const blob = new Blob([text], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
