// Botao "+ Adicionar X" que abre um pequeno menu suspenso com as opcoes
// disponiveis, em vez de um botao por opcao. Pensado para o painel de
// Primitivas, que vai crescer de 2 para varios tipos (Cone, Esfera, Snout,
// Toro, Piramide...) - ver capitulo 7.4 do manual de referencia - sem virar
// uma parede de botoes.
export function createAddMenu({ container, label, items, onSelect }) {
  const wrapper = document.createElement('div');
  wrapper.className = 'add-menu';
  wrapper.innerHTML = `
    <button type="button" class="add-entity-btn full-add-btn add-menu-trigger">
      <span>${label}</span>
      <span class="add-menu-caret"></span>
    </button>
    <div class="add-menu-list" hidden></div>
  `;
  container.appendChild(wrapper);

  const trigger = wrapper.querySelector('.add-menu-trigger');
  const list = wrapper.querySelector('.add-menu-list');

  function close() {
    list.hidden = true;
    document.removeEventListener('click', onDocumentClick, true);
  }

  function open() {
    list.hidden = false;
    document.addEventListener('click', onDocumentClick, true);
  }

  function onDocumentClick(event) {
    if (!wrapper.contains(event.target)) close();
  }

  trigger.addEventListener('click', (event) => {
    event.stopPropagation();
    if (list.hidden) open();
    else close();
  });

  items.forEach((item) => {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'add-menu-item';
    row.innerHTML = `<span class="add-menu-icon">${item.icon}</span><span>${item.label}</span>`;
    row.addEventListener('click', (event) => {
      // Sem isso, um menu instanciado DENTRO de uma linha clicavel (ex.: o
      // botao "+ negativo" de uma linha da arvore de primitivas - ver
      // ui/PrimitivesPanel.js) deixa o clique "vazar" pro onClick da propria
      // linha logo em seguida, revertendo qualquer selecao que `onSelect`
      // tenha acabado de fazer.
      event.stopPropagation();
      close();
      onSelect(item.type);
    });
    list.appendChild(row);
  });

  return { wrapper, close };
}
