import { parseDatal } from '../persistence/DatalImporter.js';

// Dialogo "Importar DATAL" - cola/carrega um texto de macro PML (.pmlmac) e
// tenta reconstruir os stores da aplicacao (ver persistence/DatalImporter.js).
// Fluxo em 2 passos, igual um "preview antes de aplicar": 1) colar/carregar
// texto + "Analisar" -> mostra um resumo do que foi encontrado + avisos; 2)
// "Importar" (so aparece depois de analisar com sucesso) de fato substitui a
// cena atual - mesmo padrao destrutivo de "Carregar cena" (SceneSerializer),
// so que a partir de DATAL em vez do JSON proprio do app. Resolve com o
// resultado de `parseDatal` (pronto pra aplicar nos stores) ou `null` se
// cancelado.
export function openDatalImportDialog() {
  return new Promise((resolve) => {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.innerHTML = `
      <div class="modal modal-wide">
        <div class="modal-header-row">
          <h2>Importar DATAL (.pmlmac)</h2>
        </div>
        <p class="datal-import-hint">
          Cole abaixo o texto de macro PML de uma CATEGORY (o mesmo formato gerado por
          "Exportar DATAL"/"Copiar DATAL", ou um arquivo real exportado do PARAGON), ou carregue um
          arquivo .pmlmac/.txt. So o subconjunto declarativo (NEW/END, sem macro PML de verdade) e
          suportado - qualquer coisa fora disso vira um aviso, nao trava a importacao.
        </p>
        <div class="datal-import-file-row">
          <input type="file" id="datal-import-file" accept=".pmlmac,.txt" />
        </div>
        <textarea id="datal-import-textarea" class="datal-import-textarea" placeholder="Cole aqui o texto do DATAL (.pmlmac)..."></textarea>
        <div id="datal-import-result" class="datal-import-result" hidden></div>
        <div class="modal-actions">
          <button id="datal-import-cancel">Cancelar</button>
          <button id="datal-import-analyze">Analisar</button>
          <button id="datal-import-confirm" hidden>Importar (substitui Parametros/Variantes/Dataset/Pontos/Primitivas)</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);

    const textarea = backdrop.querySelector('#datal-import-textarea');
    const fileInput = backdrop.querySelector('#datal-import-file');
    const resultEl = backdrop.querySelector('#datal-import-result');
    const analyzeBtn = backdrop.querySelector('#datal-import-analyze');
    const confirmBtn = backdrop.querySelector('#datal-import-confirm');

    let parsed = null;

    function close(result) {
      document.body.removeChild(backdrop);
      resolve(result);
    }

    fileInput.addEventListener('change', async () => {
      const file = fileInput.files?.[0];
      if (!file) return;
      textarea.value = await file.text();
      resultEl.hidden = true;
      confirmBtn.hidden = true;
      parsed = null;
    });

    // Qualquer edicao manual do texto invalida uma analise anterior - evita
    // importar um resumo que nao corresponde mais ao texto na caixa.
    textarea.addEventListener('input', () => {
      if (parsed) {
        parsed = null;
        resultEl.hidden = true;
        confirmBtn.hidden = true;
      }
    });

    analyzeBtn.addEventListener('click', () => {
      const text = textarea.value;
      if (text.trim() === '') {
        resultEl.hidden = false;
        confirmBtn.hidden = true;
        resultEl.innerHTML = '<div class="datal-import-error">Cole ou carregue um texto antes de analisar.</div>';
        return;
      }
      const result = parseDatal(text);
      resultEl.hidden = false;
      if (result.error) {
        parsed = null;
        confirmBtn.hidden = true;
        resultEl.innerHTML = `<div class="datal-import-error">${result.error}</div>`;
        return;
      }
      parsed = result;
      confirmBtn.hidden = false;
      const negatives = result.primitives.filter((p) => p.parentId).length;
      const positives = result.primitives.length - negatives;
      const summaryItems = [
        `Categoria: <strong>${result.category.name || '(sem nome)'}</strong>`,
        `${result.parameters.length} parametro(s)`,
        `${result.variants.length} variante(s)/componente(s)`,
        `${result.datasets.length} entrada(s) de Dataset`,
        `${result.points.length} P-point(s)`,
        `${positives} primitiva(s) positiva(s) + ${negatives} negativa(s)`
      ];
      const warningsHtml =
        result.warnings.length === 0
          ? '<div class="datal-import-ok">Nenhum aviso.</div>'
          : `<div class="datal-import-warnings-title">${result.warnings.length} aviso(s) - revise antes de confiar 100% no resultado:</div>
             <ul class="datal-import-warnings">${result.warnings.map((w) => `<li>${w}</li>`).join('')}</ul>`;
      resultEl.innerHTML = `
        <ul class="datal-import-summary">${summaryItems.map((s) => `<li>${s}</li>`).join('')}</ul>
        ${warningsHtml}
      `;
    });

    confirmBtn.addEventListener('click', () => {
      if (!parsed) return;
      close(parsed);
    });
    backdrop.querySelector('#datal-import-cancel').addEventListener('click', () => close(null));
    backdrop.addEventListener('click', (event) => {
      if (event.target === backdrop) close(null);
    });
  });
}
