import * as THREE from 'three';

const DRAG_THRESHOLD_PX = 5;

// Detecta cliques (nao arrastos de orbita/zoom) sobre os objetos selecionaveis
// da cena (referencias e primitivas) e converte em selecao no SelectionModel.
// Um clique em espaco vazio limpa a selecao.
export class SelectionManager {
  constructor({ sceneManager, selectionModel, domElement }) {
    this.sceneManager = sceneManager;
    this.selectionModel = selectionModel;
    this.domElement = domElement;
    this.raycaster = new THREE.Raycaster();
    this.pointer = new THREE.Vector2();
    this.downPos = null;
    this.suspended = false; // desativado enquanto o TransformControls esta arrastando

    domElement.addEventListener('pointerdown', this._onPointerDown);
    domElement.addEventListener('pointerup', this._onPointerUp);
  }

  setSuspended(value) {
    this.suspended = value;
  }

  _onPointerDown = (event) => {
    if (event.button !== 0) return;
    this.downPos = { x: event.clientX, y: event.clientY };
  };

  _onPointerUp = (event) => {
    if (event.button !== 0 || !this.downPos || this.suspended) {
      this.downPos = null;
      return;
    }
    const dx = event.clientX - this.downPos.x;
    const dy = event.clientY - this.downPos.y;
    this.downPos = null;
    if (Math.hypot(dx, dy) > DRAG_THRESHOLD_PX) return; // foi um arrasto de camera

    this._pick(event);
  };

  _pick(event) {
    const rect = this.domElement.getBoundingClientRect();
    this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

    this.raycaster.setFromCamera(this.pointer, this.sceneManager.camera);
    const targets = [
      ...this.sceneManager.planesGroup.children,
      ...this.sceneManager.primitivesGroup.children,
      ...this.sceneManager.pointsGroup.children
    ];
    const intersects = this.raycaster.intersectObjects(targets, false);

    const hit = intersects.find((i) => i.object.visible);
    if (hit) {
      this.selectionModel.select(hit.object.userData.objType, hit.object.userData.refId);
    } else {
      this.selectionModel.clear();
    }
  }

  dispose() {
    this.domElement.removeEventListener('pointerdown', this._onPointerDown);
    this.domElement.removeEventListener('pointerup', this._onPointerUp);
  }
}
