import * as THREE from 'three';

const MARKER_RADIUS = 20; // mm, indicador visual do ponto clicado
const DRAG_THRESHOLD_PX = 5;
const MARKER_COLOR = 0xff3fd8;

const HINT_FIRST_POINT = 'Clique no primeiro ponto do desenho (Esc para cancelar)';
const HINT_SECOND_POINT = 'Clique no segundo ponto do desenho (Esc para cancelar)';

// Ferramenta "Escalonar por 2 pontos", equivalente ao SCALE -> Reference do
// AutoCAD: o usuario clica 2 pontos sobre o plano de uma referencia e informa
// a distancia real que esses pontos devem representar; o fator resultante
// (distancia informada / distancia medida) multiplica o `scale` atual da
// referencia (so X/Y - a referencia e um plano sem espessura, Z fica como
// esta). `requestValue(measuredDistanceMm)` e injetado de fora (ui/) porque
// core/ nao importa nada de ui/ - deve devolver uma Promise<number|null>.
export class ReferenceScaleTool {
  constructor({ sceneManager, referenceStore, getMeshForReference, requestValue }) {
    this.sceneManager = sceneManager;
    this.referenceStore = referenceStore;
    this.getMeshForReference = getMeshForReference;
    this.requestValue = requestValue;

    this.active = false;
    this.referenceId = null;
    this.points = [];
    this.markers = [];
    this.line = null;
    this.downPos = null;

    this.raycaster = new THREE.Raycaster();
    this.pointer = new THREE.Vector2();

    this.hintEl = document.createElement('div');
    this.hintEl.className = 'pick-hint';
    this.hintEl.style.display = 'none';
    sceneManager.container.appendChild(this.hintEl);
  }

  isActive() {
    return this.active;
  }

  // Inicia a captura dos 2 pontos sobre o plano da referencia `referenceId`.
  start(referenceId) {
    if (this.active) this._cleanup();
    const mesh = this.getMeshForReference(referenceId);
    if (!mesh) return;

    this.active = true;
    this.referenceId = referenceId;
    this.points = [];
    this._setHint(HINT_FIRST_POINT);

    // De proposito SEM stopPropagation: o OrbitControls prende o pointerup
    // num listener separado (document, so anexado apos o pointerdown) - se a
    // gente bloqueasse esse pointerup, ele nunca saberia que o arrasto
    // acabou e a camera ficaria "grudada" no mouse. Deixar o clique tambem
    // chegar no SelectionManager e inofensivo: ele so re-seleciona a mesma
    // referencia que ja esta selecionada (SelectionModel.select ja e no-op
    // nesse caso).
    const dom = this.sceneManager.renderer.domElement;
    dom.addEventListener('pointerdown', this._onPointerDown);
    dom.addEventListener('pointerup', this._onPointerUp);
    window.addEventListener('keydown', this._onKeyDown);
  }

  cancel() {
    this._cleanup();
  }

  _setHint(text) {
    this.hintEl.textContent = text ?? '';
    this.hintEl.style.display = text ? 'block' : 'none';
  }

  _onKeyDown = (event) => {
    if (event.key === 'Escape') this.cancel();
  };

  _onPointerDown = (event) => {
    if (event.button !== 0) return;
    this.downPos = { x: event.clientX, y: event.clientY };
  };

  _onPointerUp = (event) => {
    if (event.button !== 0 || !this.downPos) return;
    const dx = event.clientX - this.downPos.x;
    const dy = event.clientY - this.downPos.y;
    this.downPos = null;
    if (Math.hypot(dx, dy) > DRAG_THRESHOLD_PX) return; // foi um arrasto de orbita, nao um clique

    const mesh = this.getMeshForReference(this.referenceId);
    if (!mesh) {
      this.cancel();
      return;
    }
    if (!mesh.visible) return; // referencia oculta - nao ha o que clicar

    const rect = this.sceneManager.renderer.domElement.getBoundingClientRect();
    this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    this.raycaster.setFromCamera(this.pointer, this.sceneManager.camera);
    const hit = this.raycaster.intersectObject(mesh, false)[0];
    if (!hit) return; // clique fora do plano - ignora

    this._addPoint(hit.point.clone());
  };

  _addPoint(point) {
    this.points.push(point);
    this._addMarker(point);

    if (this.points.length < 2) {
      this._setHint(HINT_SECOND_POINT);
      return;
    }

    this._addLine(this.points[0], this.points[1]);
    const measured = this.points[0].distanceTo(this.points[1]);
    this._setHint(null);
    this._finish(measured);
  }

  async _finish(measuredDistanceMm) {
    const referenceId = this.referenceId;
    const value = await this.requestValue(measuredDistanceMm);
    this._cleanup();
    if (value === null || !(measuredDistanceMm > 0)) return;

    const data = this.referenceStore.get(referenceId);
    if (!data) return;
    const factor = value / measuredDistanceMm;
    this.referenceStore.updateReference(referenceId, {
      scale: {
        x: data.scale.x * factor,
        y: data.scale.y * factor,
        z: data.scale.z
      }
    });
  }

  _addMarker(point) {
    const geometry = new THREE.SphereGeometry(MARKER_RADIUS, 12, 8);
    const material = new THREE.MeshBasicMaterial({ color: MARKER_COLOR, depthTest: false });
    const marker = new THREE.Mesh(geometry, material);
    marker.position.copy(point);
    marker.renderOrder = 999;
    this.sceneManager.scene.add(marker);
    this.markers.push(marker);
  }

  _addLine(a, b) {
    const geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
    const material = new THREE.LineBasicMaterial({ color: MARKER_COLOR, depthTest: false });
    this.line = new THREE.Line(geometry, material);
    this.line.renderOrder = 999;
    this.sceneManager.scene.add(this.line);
  }

  _cleanup() {
    this.active = false;
    this.referenceId = null;
    this.points = [];
    this.downPos = null;
    this._setHint(null);

    this.markers.forEach((marker) => {
      this.sceneManager.scene.remove(marker);
      marker.geometry.dispose();
      marker.material.dispose();
    });
    this.markers = [];

    if (this.line) {
      this.sceneManager.scene.remove(this.line);
      this.line.geometry.dispose();
      this.line.material.dispose();
      this.line = null;
    }

    const dom = this.sceneManager.renderer.domElement;
    dom.removeEventListener('pointerdown', this._onPointerDown);
    dom.removeEventListener('pointerup', this._onPointerUp);
    window.removeEventListener('keydown', this._onKeyDown);
  }
}
