import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Estrutura de dados central de uma referencia (plano). Toda a aplicacao le/escreve
// o estado atraves do ReferenceStore, nunca diretamente nas propriedades dos
// objetos Three.js - isso mantem um unico "source of truth" e facilita futuras
// funcionalidades (geracao de geometria, exportacao, etc).
export function createDefaultReferenceData(overrides = {}) {
  return {
    id: createId(),
    name: 'Referencia',
    type: 'image', // 'image' | 'pdf'
    source: '', // nome do arquivo original
    page: null, // numero da pagina, quando type === 'pdf'
    width: 1000, // dimensao do plano no mundo 3D (mm)
    height: 1000,
    fileData: null, // dataURL usado para reconstruir a textura (persistencia local)
    // Posicao e expressao (ver utils/expressionEvaluator.js) - um numero
    // literal ("0") e so uma expressao trivial; tambem aceita "PARAM n".
    position: { x: '0', y: '0', z: '0' },
    // PlaneGeometry nasce deitada no plano XY (normal +Z); com Z para cima
    // (convencao CAD/E3D), rotacionar 90 graus em X deixa o plano de pe por
    // padrao (como uma elevacao/vista frontal), em vez de deitado no chao.
    rotation: { x: 90, y: 0, z: 0 }, // graus
    scale: { x: 1, y: 1, z: 1 },
    opacity: 1,
    visible: true,
    locked: false,
    whiteAsAlpha: false, // branco vira transparente, demais cores viram preto (ver ReferencePlane.buildTexture)
    // Reservado para uma funcionalidade futura: associar dimensoes reais do
    // desenho (diferentes da dimensao do plano usada apenas para visualizacao).
    realDimensions: {
      width: null,
      height: null,
      unit: 'mm',
      drawingScale: null
    },
    ...overrides
  };
}

export class ReferenceStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map(); // id -> data
    this.order = []; // preserva a ordem de criacao/exibicao
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  addReference(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('reference:added', data);
    return data;
  }

  updateReference(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('reference:updated', updated);
    return updated;
  }

  removeReference(id) {
    if (!this.items.has(id)) return;
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('reference:removed', id);
  }

  duplicateReference(id) {
    const source = this.items.get(id);
    if (!source) return null;
    // Nasce na MESMA posicao do original (sem deslocar) - reposicionar fica a
    // cargo de quem modela.
    const copy = createDefaultReferenceData({
      ...structuredClone(source),
      id: createId(),
      // Sem espacos/parenteses: nomes no E3D nao aceitam esses caracteres.
      name: `${source.name}_copy`
    });
    return this.addReference(copy);
  }

  clear() {
    [...this.order].forEach((id) => this.removeReference(id));
  }
}
