import { DEG2RAD } from './transformMath.js';

// Avalia expressoes de dimensao/parametro no estilo do catalogo do E3D:
// numeros, operadores + - * /, parenteses, referencias a parametros da
// variante ATIVA via "PARAM n" ou "PARA n" / "PARA[n]" (ver capitulo 8 do
// manual de referencia: `ATTRIB PARA[12]`, `PCON PARAM 3`, e o exemplo
// REFERENCIAS/SUPORTE_SDE-37-005.pmlmac), referencias a Dataset via
// "RPRO <dkey>" / "RPROP <dkey>" (capitulo 8.3 "Real Properties" do manual -
// ver core/DatasetStore.js), funcoes trigonometricas COS/SIN/TAN (ver
// TRIG_FUNCTIONS abaixo) e numeros em polegadas ("2.5in", "3 inches")
// convertidos para mm - tudo no app trabalha em mm, entao a conversao
// acontece uma unica vez, no comeco da avaliacao.
//
// Todo campo que aceita expressao (dimensoes de primitiva, PCON/PBOR de
// P-point) guarda sempre uma STRING - um numero literal como "200" e apenas
// uma expressao trivial (sem referencias a parametro), avaliada pelo mesmo
// caminho.
// `PARAM_TOKEN` tem a flag global (usada com .replace() em substituteParams,
// que precisa trocar TODAS as ocorrencias). Regex globais guardam
// `lastIndex` entre chamadas de .test()/.exec(), entao NUNCA reusar essa
// mesma instancia com .test() - da resultados errados de forma intermitente
// (o motivo de `isParametric` usar uma regex separada, sem "g", abaixo).
const PARAM_TOKEN = /PARA(?:M)?\s*\[?\s*(\d+)\s*\]?/gi;
const PARAM_TOKEN_TEST = /PARA(?:M)?\s*\[?\s*\d+\s*\]?/i;
const BARE_PARAM = /^PARA(?:M)?\s*\[?\s*(\d+)\s*\]?$/i;

// Numero seguido de "in"/"inch"/"inches" (com ou sem espaco, case-insensitive)
// e convertido para mm - "2.5in" vira "63.5" antes de qualquer outra coisa
// (parametro/aritmetica), entao funciona tanto sozinho quanto dentro de uma
// expressao maior ("2.5in + PARAM 3"). So esse sufixo e suportado (o resto
// do app trabalha inteiramente em mm). Mesmo aviso de regex global do
// PARAM_TOKEN acima se aplica aqui - `INCH_LITERAL_TEST` e a copia sem "g"
// usada com .test() em `hasInchLiteral`.
export const INCH_TO_MM = 25.4;
const INCH_LITERAL = /(-?\d+(?:\.\d+)?)\s*in(?:ch(?:es)?)?\b/gi;
const INCH_LITERAL_TEST = /-?\d+(?:\.\d+)?\s*in(?:ch(?:es)?)?\b/i;

// Exportado para o tradutor de expressao -> PML (persistence/DatalExporter.js)
// reaproveitar a MESMA conversao de polegada, sem duplicar a regex.
// Arredonda pra no MAXIMO 2 casas decimais - BUG REAL corrigido: multiplicar
// por 25.4 direto gera ruido de ponto flutuante em varios casos (ex.: `14 *
// 25.4` = `355.59999999999997` em JS, nao `355.6`) - decisao explicita do
// usuario, confirmada com um caso real (14in aparecia como
// "3565.5999999999..."-like em vez de "355.6").
export function convertInchLiterals(text) {
  return text.replace(INCH_LITERAL, (_match, numStr) => {
    const mm = Number(numStr) * INCH_TO_MM;
    return String(Math.round(mm * 100) / 100);
  });
}

export function hasInchLiteral(raw) {
  return typeof raw === 'string' && INCH_LITERAL_TEST.test(raw);
}

// "RPRO <dkey>" ou "RPROP <dkey>" (o manual usa RPROP como pseudo-atributo;
// aceitamos as duas grafias) referencia uma entrada de Dataset pelo DKEY
// (uma palavra, ex.: "A", "DBOR") - ver core/DatasetStore.js. So um estado de
// modulo (setado uma vez em main.js via setDatasetResolver) em vez de mais
// um parametro `resolveDataset` threaded por toda funcao que hoje recebe
// `resolveParam`, porque so existe UM DatasetStore no app inteiro.
const RPRO_TOKEN = /RPRO(?:P)?\s+([A-Za-z][A-Za-z0-9_]*)/gi;
const RPRO_TOKEN_TEST = /RPRO(?:P)?\s+[A-Za-z][A-Za-z0-9_]*/i;

let datasetLookup = () => ({ expr: null, error: 'Dataset resolver nao configurado' });

export function setDatasetResolver(fn) {
  datasetLookup = fn;
}

export function hasDatasetReference(raw) {
  return typeof raw === 'string' && RPRO_TOKEN_TEST.test(raw);
}

// Para campos numericos simples que nao passam pelo avaliador de expressao
// completo (sem PARAM, ex.: o valor digitado no dialogo de "Escalonar por 2
// pontos") mas ainda devem aceitar "2.5in" - so a conversao de unidade, sem
// aritmetica/parametro.
export function parseNumberWithUnits(raw) {
  return Number(convertInchLiterals(String(raw ?? '').trim()));
}

// Uma expressao "de verdade" referencia pelo menos um parametro. Um numero
// puro (ex.: "200" ou "-12.5") nao precisa passar pelo avaliador para ser
// exibido como literal, mas `evaluateExpression` lida com ambos os casos.
export function isParametric(raw) {
  return typeof raw === 'string' && PARAM_TOKEN_TEST.test(raw);
}

const TRIG_FUNCTION_TEST = /\b(COS|SIN|TAN)\s*\(/i;

// Usado pela UI pra decidir se mostra a dica de valor resolvido - uma
// expressao so com COS/SIN/TAN (sem PARAM/RPRO/polegada) tambem tem um valor
// "de bastidores" calculado, diferente do texto digitado.
export function hasTrigFunction(raw) {
  return typeof raw === 'string' && TRIG_FUNCTION_TEST.test(raw);
}

// Usado pela UI para decidir se mostra a dica de valor resolvido abaixo de um
// campo: referencia a parametro, conversao de unidade (polegada), referencia
// a Dataset e funcao trigonometrica tem todos um valor "de bastidores"
// diferente do texto digitado.
export function needsExpressionHint(raw) {
  return isParametric(raw) || hasInchLiteral(raw) || hasDatasetReference(raw) || hasTrigFunction(raw);
}

// Resolve um campo de posicao (X/Y/Z) - ao contrario das dimensoes, posicao
// pode legitimamente ser negativa ou zero, entao nao ha "minimo": se a
// expressao nao resolver para numero, cai para `fallback` (0 por padrao).
export function resolveNumber(raw, resolveParam, fallback = 0) {
  const { value, isNumber } = evaluateExpression(raw, resolveParam);
  return isNumber ? value : fallback;
}

// Usado ao duplicar um objeto: desloca um campo posicao/dimensao por
// `offset` SE ele for um numero literal; se for uma expressao ("PARAM 3"),
// nao ha como somar um deslocamento fixo a um valor simbolico, entao
// mantem a expressao original sem alterar.
// resolveParam(numero) deve devolver o valor BRUTO (string) daquele
// parametro na variante ativa, ou undefined se nao existir/nao houver
// variante ativa.
//
// Retorna { value, isNumber, error }:
// - Se a expressao inteira for uma unica referencia PARAM n (nada mais),
//   `value` e o valor bruto da variante (pode ser texto, ex.: 'ATT') e
//   `isNumber` reflete se aquele texto e numerico.
// - Caso contrario (numero puro ou aritmetica), `value` e sempre number.
// - Em erro (sintaxe invalida, parametro inexistente, divisao por zero),
//   `error` traz uma mensagem e `value` e null.
export function evaluateExpression(raw, resolveParam) {
  const rawTrimmed = String(raw ?? '').trim();
  if (rawTrimmed === '') {
    return { value: null, isNumber: false, error: 'Vazio' };
  }
  let working = convertInchLiterals(rawTrimmed);

  // RPRO expande primeiro (uma unica camada - a expressao do Dataset pode
  // conter "PARAM n", que a substituicao normal logo abaixo resolve; nao
  // suporta um Dataset referenciando outro Dataset). Igual ao numero puro,
  // so o caminho NUMERICO e suportado: RPRO sempre entra entre parenteses
  // na aritmetica, mesmo se for o campo inteiro (sem caso especial de
  // "bare" como o PARAM tem, ao contrario de PARAM que pode devolver texto
  // cru quando referenciado sozinho).
  let missingDataset = null;
  working = working.replace(RPRO_TOKEN, (_match, dkey) => {
    const dkeyUpper = dkey.toUpperCase();
    // `resolveParam` repassado pro resolvedor do Dataset - precisa dele pra
    // TESTAR se PPRO de fato resolve (ver core/DatasetStore.js: resolveDkey)
    // antes de decidir usar PPRO ou cair pro DPRO. `resolveDkey` ja devolve
    // a mensagem de erro mais especifica disponivel (dataset nao encontrado,
    // ou o motivo real de PPRO/DPRO nao resolverem), entao so repassa.
    const { expr, error } = datasetLookup(dkeyUpper, resolveParam);
    if (error) {
      missingDataset = error;
      return '0';
    }
    return `(${convertInchLiterals(String(expr).trim())})`;
  });
  if (missingDataset) {
    return { value: null, isNumber: false, error: missingDataset };
  }
  const trimmed = working;

  const bareMatch = trimmed.match(BARE_PARAM);
  if (bareMatch) {
    const num = Number(bareMatch[1]);
    const value = resolveParam(num);
    if (value === undefined) {
      return { value: null, isNumber: false, error: `Parametro ${num} nao encontrado na variante ativa` };
    }
    const numeric = Number(value);
    return { value, isNumber: value !== '' && !Number.isNaN(numeric), error: null };
  }

  let missing = null;
  const substituted = trimmed.replace(PARAM_TOKEN, (_match, numStr) => {
    const num = Number(numStr);
    const rawValue = resolveParam(num);
    if (rawValue === undefined) {
      missing = `Parametro ${num} nao encontrado na variante ativa`;
      return '0';
    }
    const numeric = Number(rawValue);
    if (Number.isNaN(numeric)) {
      missing = `Parametro ${num} ('${rawValue}') nao e numerico`;
      return '0';
    }
    return `(${numeric})`;
  });
  if (missing) {
    return { value: null, isNumber: false, error: missing };
  }

  try {
    const value = parseArithmetic(substituted);
    if (!Number.isFinite(value)) throw new Error('Resultado invalido');
    return { value, isNumber: true, error: null };
  } catch (err) {
    return { value: null, isNumber: false, error: err.message };
  }
}

// Funcoes trigonometricas do catalogo real - argumento SEMPRE em GRAUS (nao
// radianos), confirmado pelo usuario contra o E3D de verdade: `COS(45)` =
// 0.7071, `SIN(60)` = 0.866, `TAN(45)` = 1. Usadas em expressoes reais tipo
// `( PARAM 2 / 2 + PARAM 4 / 2 ) * COS ( 45 )` (P-point PTCAR de
// REFERENCIAS/SUP.pmlmac).
const TRIG_FUNCTIONS = {
  COS: (deg) => Math.cos(deg * DEG2RAD),
  SIN: (deg) => Math.sin(deg * DEG2RAD),
  TAN: (deg) => Math.tan(deg * DEG2RAD)
};

// Parser recursivo simples: expr := term (('+'|'-') term)*
//                            term := factor (('*'|'/') factor)*
//                            factor := number | '(' expr ')' | '-' factor
//                                    | FUNC '(' expr ')'  (COS/SIN/TAN)
function parseArithmetic(text) {
  let pos = 0;

  function skipSpace() {
    while (text[pos] === ' ') pos++;
  }

  function parseExpr() {
    let value = parseTerm();
    skipSpace();
    while (text[pos] === '+' || text[pos] === '-') {
      const op = text[pos++];
      const rhs = parseTerm();
      value = op === '+' ? value + rhs : value - rhs;
      skipSpace();
    }
    return value;
  }

  function parseTerm() {
    let value = parseFactor();
    skipSpace();
    while (text[pos] === '*' || text[pos] === '/') {
      const op = text[pos++];
      const rhs = parseFactor();
      if (op === '/') {
        if (rhs === 0) throw new Error('Divisao por zero');
        value = value / rhs;
      } else {
        value = value * rhs;
      }
      skipSpace();
    }
    return value;
  }

  function parseFactor() {
    skipSpace();
    if (text[pos] === '(') {
      pos++;
      const value = parseExpr();
      skipSpace();
      if (text[pos] !== ')') throw new Error('Parenteses desbalanceados');
      pos++;
      return value;
    }
    if (text[pos] === '-') {
      pos++;
      return -parseFactor();
    }
    if (text[pos] === '+') {
      pos++;
      return parseFactor();
    }
    const identStart = pos;
    while (pos < text.length && /[A-Za-z]/.test(text[pos])) pos++;
    if (pos > identStart) {
      const name = text.slice(identStart, pos).toUpperCase();
      const fn = TRIG_FUNCTIONS[name];
      if (!fn) throw new Error(`Funcao desconhecida: "${name}"`);
      skipSpace();
      if (text[pos] !== '(') throw new Error(`Funcao "${name}" espera parenteses`);
      pos++;
      const argDeg = parseExpr();
      skipSpace();
      if (text[pos] !== ')') throw new Error('Parenteses desbalanceados');
      pos++;
      return fn(argDeg);
    }
    const start = pos;
    while (pos < text.length && /[0-9.]/.test(text[pos])) pos++;
    if (start === pos) throw new Error('Expressao invalida');
    return Number(text.slice(start, pos));
  }

  skipSpace();
  const result = parseExpr();
  skipSpace();
  if (pos !== text.length) throw new Error('Caracteres inesperados na expressao');
  return result;
}
