import { createCollapsibleSection } from './CollapsibleSection.js';
import { resolveAnchorPosition } from '../objects/SnapPoints.js';

// Painel lateral esquerdo: Cotas - anotacoes de medida (distancia entre 2
// pontos colados a vertices/cantos de outros objetos), ferramenta de
// conferencia visual do proprio app, sem equivalente no catalogo do E3D (ver
// core/CotaStore.js). "+ Adicionar cota" ativa o modo de captura (ver
// core/CotaPickTool.js) - clique perto de um ponto colavel duas vezes.
export class CotasPanel {
  constructor({ container, cotaStore, referenceStore, primitiveStore, pointStore, variantStore, onStartPicking }) {
    this.cotaStore = cotaStore;
    this.stores = { referenceStore, primitiveStore, pointStore };
    this.variantStore = variantStore;
    this.resolveParam = (number) => this.variantStore.resolveParam(number);
    this.onStartPicking = onStartPicking;

    const { bodyEl } = createCollapsibleSection({ container, title: 'Cotas', defaultExpanded: false });
    this.container = bodyEl;

    this.container.innerHTML = `
      <button id="add-cota-btn" class="add-entity-btn full-add-btn">+ Adicionar cota</button>
      <div id="cota-list"></div>
      <div id="cota-empty" class="empty-state">
        Nenhuma cota. Clique em "Adicionar cota" e depois em 2 pontos da cena
        (vertices, cantos, quadrantes) para medir a distancia entre eles.
      </div>
    `;
    this.listEl = this.container.querySelector('#cota-list');
    this.emptyEl = this.container.querySelector('#cota-empty');

    this.container.querySelector('#add-cota-btn').addEventListener('click', () => this.onStartPicking());

    cotaStore.on('cota:added', () => this.render());
    cotaStore.on('cota:updated', () => this.render());
    cotaStore.on('cota:removed', () => this.render());

    // A distancia mostrada depende do estado ATUAL dos objetos referenciados
    // - qualquer mudanca que afete posicao/dimensao/variante ativa precisa
    // re-renderizar a lista (mesma ideia do painel de Datasets).
    referenceStore.on('reference:updated', () => this.render());
    primitiveStore.on('primitive:updated', () => this.render());
    pointStore.on('point:updated', () => this.render());
    variantStore.on('active-changed', () => this.render());
    variantStore.on('variant:updated', () => this.render());

    this.render();
  }

  render() {
    const items = this.cotaStore.list();
    this.emptyEl.style.display = items.length ? 'none' : 'block';
    this.listEl.innerHTML = '';
    items.forEach((item) => this.listEl.appendChild(this._buildRow(item)));
  }

  _buildRow(item) {
    const row = document.createElement('div');
    row.className = 'cota-row';

    const posA = item.pointA ? resolveAnchorPosition(item.pointA, this.stores, this.resolveParam) : null;
    const posB = item.pointB ? resolveAnchorPosition(item.pointB, this.stores, this.resolveParam) : null;
    const ok = posA && posB;
    const valueText = ok ? `${Math.round(posA.distanceTo(posB) * 1000) / 1000} mm` : '⚠ ponto de origem nao encontrado';

    row.innerHTML = `
      <div class="cota-row-main">
        <input type="text" class="full cota-name-input" value="${item.name}" />
        <button type="button" class="icon-btn" data-action="toggle-visible" title="Mostrar/ocultar no viewport">${item.visible ? '\u{1F441}' : '\u{1F648}'}</button>
        <button type="button" class="icon-btn" data-action="delete" title="Excluir cota">✕</button>
      </div>
      <div class="cota-row-value${ok ? '' : ' expr-error'}">${valueText}</div>
    `;

    row.querySelector('.cota-name-input').addEventListener('change', (e) => {
      const value = e.target.value.trim();
      if (value) this.cotaStore.updateCota(item.id, { name: value });
    });
    row.querySelector('[data-action="toggle-visible"]').addEventListener('click', () => {
      this.cotaStore.updateCota(item.id, { visible: !item.visible });
    });
    row.querySelector('[data-action="delete"]').addEventListener('click', () => this.cotaStore.removeCota(item.id));

    return row;
  }
}
