import { createCollapsibleSection } from './CollapsibleSection.js';
import { createDefaultParameterData } from '../core/ParameterStore.js';
import { openVariantsDialog } from './VariantsDialog.js';

// Painel lateral esquerdo (primeiro da lista):
// 1) Definicoes de parametro (numero + descricao) - o "cabecalho de coluna",
//    pequena o bastante para caber confortavelmente na barra lateral.
// 2) Variantes (Componentes): a grade de valores (Nome/Gtype/PA1/PA2/...)
//    abre numa janela externa (VariantsDialog.js) - com muitas colunas ela
//    fica dificil de enxergar espremida nos ~260px da barra lateral.
export class ParametersPanel {
  constructor({ container, parameterStore, variantStore, categoryStore }) {
    this.parameterStore = parameterStore;
    this.variantStore = variantStore;
    this.categoryStore = categoryStore;

    const { bodyEl } = createCollapsibleSection({ container, title: 'Parametros', defaultExpanded: false });
    this.container = bodyEl;

    this._buildStaticLayout();

    parameterStore.on('parameter:added', () => this.render());
    parameterStore.on('parameter:removed', () => this.render());
    parameterStore.on('parameter:updated', () => this.render());
    variantStore.on('variant:added', () => this._renderVariantsSummary());
    variantStore.on('variant:updated', () => this._renderVariantsSummary());
    variantStore.on('variant:removed', () => this._renderVariantsSummary());
    variantStore.on('active-changed', () => this._renderVariantsSummary());

    this.render();
  }

  _buildStaticLayout() {
    const definitionsSection = createCollapsibleSection({
      container: this.container,
      title: 'Definicoes de parametro',
      defaultExpanded: false,
      nested: true
    });
    definitionsSection.bodyEl.innerHTML = `
      <button id="add-parameter-btn" class="add-entity-btn full-add-btn">+ Adicionar parametro</button>
      <table class="parameters-table">
        <thead>
          <tr><th>No</th><th>Descricao</th><th></th></tr>
        </thead>
        <tbody id="parameters-tbody"></tbody>
      </table>
      <div id="parameters-empty" class="empty-state"></div>
    `;

    const variantsSection = createCollapsibleSection({
      container: this.container,
      title: 'Variantes (Componentes)',
      defaultExpanded: false,
      nested: true
    });
    variantsSection.bodyEl.innerHTML = `
      <div class="prop-group" style="padding:0 12px">
        <label class="prop-label">Variante ativa</label>
        <select id="active-variant-select" class="full"></select>
      </div>
      <div id="variants-summary" class="params-variants-summary"></div>
      <button id="open-variants-btn" class="add-entity-btn full-add-btn">Abrir tabela de variantes</button>
    `;

    this.paramTbodyEl = definitionsSection.bodyEl.querySelector('#parameters-tbody');
    this.paramEmptyEl = definitionsSection.bodyEl.querySelector('#parameters-empty');
    this.paramEmptyEl.textContent = 'Nenhum parametro definido. Use "Adicionar parametro" para comecar.';

    this.activeVariantSelect = variantsSection.bodyEl.querySelector('#active-variant-select');
    this.variantsSummaryEl = variantsSection.bodyEl.querySelector('#variants-summary');

    definitionsSection.bodyEl.querySelector('#add-parameter-btn').addEventListener('click', () => {
      const nextNumber = this.parameterStore.list().length + 1;
      this.parameterStore.addParameter(createDefaultParameterData({ number: nextNumber }));
    });

    variantsSection.bodyEl.querySelector('#open-variants-btn').addEventListener('click', () => {
      openVariantsDialog({ parameterStore: this.parameterStore, variantStore: this.variantStore, categoryStore: this.categoryStore });
    });

    this.activeVariantSelect.addEventListener('change', () => {
      this.variantStore.setActive(this.activeVariantSelect.value || null);
    });

    this._renderVariantsSummary();
  }

  render() {
    this._renderParameters();
  }

  _renderParameters() {
    const items = this.parameterStore.list();
    this.paramTbodyEl.innerHTML = '';
    this.paramEmptyEl.style.display = items.length ? 'none' : 'block';
    for (const item of items) {
      this.paramTbodyEl.appendChild(this._buildParameterRow(item));
    }
  }

  _buildParameterRow(item) {
    const tr = document.createElement('tr');

    const numberCell = this._buildCell(item.number, 'number', '1', (value) => {
      const num = Number(value);
      if (!Number.isNaN(num)) this.parameterStore.updateParameter(item.id, { number: num });
    });
    numberCell.querySelector('input').classList.add('param-cell-number');
    tr.appendChild(numberCell);
    tr.appendChild(
      this._buildCell(item.description, 'text', 'Descricao', (value) => {
        this.parameterStore.updateParameter(item.id, { description: value });
      })
    );

    const actionsTd = document.createElement('td');
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'icon-btn';
    deleteBtn.textContent = '✕';
    deleteBtn.title = 'Excluir definicao de parametro';
    deleteBtn.addEventListener('click', () => this.parameterStore.removeParameter(item.id));
    actionsTd.appendChild(deleteBtn);
    tr.appendChild(actionsTd);

    return tr;
  }

  _renderVariantsSummary() {
    const variants = this.variantStore.list();
    const activeId = this.variantStore.activeVariantId;

    this.activeVariantSelect.innerHTML = '<option value="">(nenhuma)</option>';
    for (const variant of variants) {
      const opt = document.createElement('option');
      opt.value = variant.id;
      opt.textContent = variant.name;
      if (variant.id === activeId) opt.selected = true;
      this.activeVariantSelect.appendChild(opt);
    }

    this.variantsSummaryEl.textContent =
      variants.length === 0
        ? 'Nenhuma variante definida.'
        : `${variants.length} variante(s) definida(s).`;
  }

  _buildCell(value, type, placeholder, onChange) {
    const td = document.createElement('td');
    const input = document.createElement('input');
    input.type = type;
    input.className = 'param-cell';
    input.value = value;
    if (placeholder) input.placeholder = placeholder;
    if (type === 'number') input.step = '1';
    input.addEventListener('change', () => onChange(input.value));
    td.appendChild(input);
    return td;
  }
}
