import { renderEntityList } from './EntityTree.js';
import { createCollapsibleSection } from './CollapsibleSection.js';
import { createAddMenu } from './AddMenu.js';
import { isNegativePrimitiveType } from '../core/PrimitiveStore.js';

// Tipos de primitiva disponiveis (ver capitulo 7.4 do manual de referencia -
// GMSET/3D Geomset Primitives). Adicionar um novo tipo e so acrescentar uma
// entrada aqui (e o caso correspondente em objects/PrimitiveObject.js e
// ui/PropertiesPanel.js) - o menu "+ Adicionar primitiva" e a lista ja se
// adaptam sozinhos.
const PRIMITIVE_TYPES = [
  { type: 'box', label: 'Caixa', icon: '\u{1F4E6}' },
  { type: 'cylinder', label: 'Cilindro', icon: '\u{1F6E2}' },
  { type: 'cone', label: 'Cone', icon: '\u{1F53A}' },
  // Esfera/Disco removidos do menu por enquanto: no catalogo real os dois
  // sao representados pelo elemento DISH (ex.: esfera = 2 DISH espelhados),
  // que este app ainda nao implementa - fica pra uma proxima etapa. O
  // objects/PrimitiveObject.js e o resto do suporte a 'sphere'/'disc'
  // continuam intactos, entao uma cena salva que ja tenha um desses tipos
  // continua carregando e renderizando normalmente - so nao da mais pra
  // CRIAR um novo por aqui.
  { type: 'pyramid', label: 'Piramide', icon: '\u{1F53B}' },
  { type: 'snout', label: 'Snout', icon: '\u{1F964}' },
  { type: 'torus', label: 'Toro', icon: '\u{1F369}' },
  { type: 'torusRect', label: 'Toro Retangular', icon: '\u{1F9F0}' },
  { type: 'extrusion', label: 'Extrusao', icon: '\u{1F4D0}' }
];

// Elementos NEGATIVOS (buracos/rebaixos - ver capitulo 7.5 do manual e
// core/PrimitiveStore.js: NEGATIVE_PRIMITIVE_TYPES) - tem seu PROPRIO botao
// "+ Adicionar negativo" (ver _buildStaticLayout), ao lado do "+ Adicionar
// primitiva" - o pai vinculado e sempre o elemento POSITIVO selecionado no
// momento do clique (ver _handleAddNegativeSelect); sem selecao valida, avisa
// em vez de criar. Tambem podem ser movidos pra outro pai por arrastar (ver
// render: isDraggable/isDropTarget/onReparent) ou pelo dropdown "vinculado a"
// no painel de propriedades.
const NEGATIVE_PRIMITIVE_TYPES = [
  { type: 'negBox', label: 'Caixa Negativa', icon: '\u{1F573}\u{FE0F}' },
  { type: 'negCylinder', label: 'Cilindro Negativo', icon: '\u{26AB}' },
  { type: 'negPyramid', label: 'Piramide Negativa', icon: '\u{1F53B}' }
];

const ICONS = Object.fromEntries([...PRIMITIVE_TYPES, ...NEGATIVE_PRIMITIVE_TYPES].map((t) => [t.type, t.icon]));

// Painel lateral esquerdo: lista de primitivas (Caixa/Cilindro, e mais
// tipos no futuro) da cena. Estes sao os elementos basicos que futuramente
// serao convertidos em geometria e DATAL do E3D.
export class PrimitivesPanel {
  constructor({ container, store, selectionModel, onAddPrimitive, onAddNegative }) {
    this.container = container;
    this.store = store;
    this.selectionModel = selectionModel;
    this.onAddPrimitive = onAddPrimitive;
    this.onAddNegative = onAddNegative;
    this.renamingId = null;

    this._buildStaticLayout();
    store.on('primitive:added', () => this.render());
    store.on('primitive:removed', () => this.render());
    store.on('primitive:updated', () => this.render());
    selectionModel.on('changed', () => this.render());

    this.render();
  }

  _buildStaticLayout() {
    const { bodyEl } = createCollapsibleSection({ container: this.container, title: 'Primitivas', defaultExpanded: false });
    this.container = bodyEl;

    createAddMenu({
      container: this.container,
      label: '+ Adicionar primitiva',
      items: PRIMITIVE_TYPES,
      onSelect: (type) => this.onAddPrimitive(type)
    });

    createAddMenu({
      container: this.container,
      label: '+ Adicionar negativo',
      items: NEGATIVE_PRIMITIVE_TYPES,
      onSelect: (type) => this._handleAddNegativeSelect(type)
    });

    this.container.insertAdjacentHTML('beforeend', '<ul id="primitives-tree" class="entity-tree"></ul>');
    this.treeEl = this.container.querySelector('#primitives-tree');
  }

  // O pai de um negativo novo e sempre o elemento POSITIVO selecionado no
  // momento (ver core/SelectionModel.js: `current`) - sem uma selecao
  // valida, avisa em vez de criar (nao ha como um negativo existir sem pai -
  // ver core/PrimitiveStore.js).
  _handleAddNegativeSelect(type) {
    const sel = this.selectionModel.current;
    const target = sel?.type === 'primitive' ? this.store.get(sel.id) : null;
    if (!target || isNegativePrimitiveType(target.type)) {
      alert('Selecione um elemento POSITIVO na lista de Primitivas antes de adicionar um negativo - ele sempre fica vinculado ao que estiver selecionado.');
      return;
    }
    this.onAddNegative(target.id, type);
  }

  // Cada negativo aparece logo apos o positivo dono (ver `parentId` em
  // core/PrimitiveStore.js) - EntityTree.js so sabe desenhar uma lista plana
  // com recuo (`isNested`), entao quem decide a ORDEM (positivo, seus
  // negativos, proximo positivo...) e este metodo. Um negativo orfao (nao
  // deveria acontecer - removePrimitive cascateia - mas por seguranca contra
  // estado inconsistente) cai no final, sem recuo.
  _orderedItems() {
    const all = this.store.list();
    const byParent = new Map();
    const positives = [];
    for (const item of all) {
      if (item.parentId) {
        if (!byParent.has(item.parentId)) byParent.set(item.parentId, []);
        byParent.get(item.parentId).push(item);
      } else {
        positives.push(item);
      }
    }
    const ordered = [];
    const seenParents = new Set();
    for (const positive of positives) {
      ordered.push(positive);
      seenParents.add(positive.id);
      (byParent.get(positive.id) ?? []).forEach((child) => ordered.push(child));
    }
    for (const [parentId, children] of byParent) {
      if (!seenParents.has(parentId)) ordered.push(...children); // pai sumiu - nao deveria, ver comentario acima
    }
    return ordered;
  }

  render() {
    renderEntityList({
      treeEl: this.treeEl,
      items: this._orderedItems(),
      isSelected: (id) => this.selectionModel.isSelected('primitive', id),
      iconFor: (item) => ICONS[item.type] ?? '■',
      isNested: (item) => Boolean(item.parentId),
      // Arrastar e soltar (ver ui/EntityTree.js) - so negativo pode ser
      // arrastado, so positivo aceita ser largado em cima (reatribui
      // `parentId`, ver core/PrimitiveStore.js). Mesma acao do dropdown
      // "vinculado a" no painel de propriedades - so um jeito a mais de
      // fazer a mesma coisa.
      isDraggable: (item) => isNegativePrimitiveType(item.type),
      isDropTarget: (item) => !isNegativePrimitiveType(item.type),
      onReparent: (draggedId, targetId) => this.store.updatePrimitive(draggedId, { parentId: targetId }),
      renamingId: this.renamingId,
      onSelect: (id) => this.selectionModel.select('primitive', id),
      onStartRename: (id) => {
        this.renamingId = id;
        this.render();
      },
      onCommitRename: (id, value) => this._commitRename(id, value),
      onCancelRename: () => {
        this.renamingId = null;
        this.render();
      },
      onToggleVisible: (item) => this.store.updatePrimitive(item.id, { visible: !item.visible }),
      onDuplicate: (id) => {
        const copy = this.store.duplicatePrimitive(id);
        if (copy) this.selectionModel.select('primitive', copy.id);
      },
      onDelete: (id) => this.store.removePrimitive(id),
      emptyMessage: 'Nenhuma primitiva na cena. Use "Adicionar primitiva" para comecar.'
    });
  }

  _commitRename(id, value) {
    this.renamingId = null;
    const name = value.trim();
    if (name) {
      this.store.updatePrimitive(id, { name });
    } else {
      this.render();
    }
  }
}
