import { createDefaultVariantData } from '../core/VariantStore.js';
import { PDMS_DIAMETER_CODES } from '../core/pdmsDiameterCodes.js';
import { hasInchLiteral, convertInchLiterals } from '../utils/expressionEvaluator.js';

// Normaliza um literal em polegada (ex.: "16in") pro numero em mm assim que
// o campo perde o foco OU quando aperta Enter - mesma logica de
// ui/PropertiesPanel.js: _attachInchNormalization (ver o comentario la pra
// detalhes completos). Ligado nas celulas de VALOR de PARAM da tabela de
// Variantes (`buildVariantRow` abaixo) - faltava aqui, so tinha sido ligado
// em PropertiesPanel/DatasetsPanel na 1a rodada dessa funcionalidade.
function _attachInchNormalization(input) {
  if (!input) return;
  const normalize = () => {
    if (hasInchLiteral(input.value)) {
      input.value = convertInchLiterals(input.value);
      input.dispatchEvent(new Event('change', { bubbles: true }));
    }
  };
  input.addEventListener('change', normalize);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      normalize();
    }
  });
}

// Janela externa (modal) com a grade de Variantes (Componentes) - Nome /
// Gtype / PA1 / PA2 / ... Existe separada do painel lateral porque a grade
// pode ter muitas colunas (uma por parametro) e a barra lateral e estreita
// demais para ser confortavel de editar ali.
//
// `categoryStore` (novo) - so pra ler o nome da CATEGORY na hora de montar o
// nome de cada variante do range de diametros (ver
// _handleAddDiameterRange abaixo).
export function openVariantsDialog({ parameterStore, variantStore, categoryStore }) {
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  const diameterOptions = PDMS_DIAMETER_CODES.map((d, i) => `<option value="${i}">${d.label} (${d.code})</option>`).join('');
  backdrop.innerHTML = `
    <div class="modal modal-wide">
      <div class="modal-header-row">
        <h2>Variantes (Componentes)</h2>
        <button type="button" id="variants-dialog-close" class="icon-btn" title="Fechar">✕</button>
      </div>

      <div class="prop-group">
        <label class="prop-label">Variante ativa (usada para resolver expressoes "PARAM n")</label>
        <select id="active-variant-select" class="full"></select>
      </div>

      <button id="add-variant-btn" class="add-entity-btn full-add-btn">+ Adicionar variante</button>

      <div class="prop-group diameter-range-group">
        <label class="prop-label">+ Adicionar range de diametros (codificacao PDMS de diametro)</label>
        <div class="prop-row">
          <div class="axis-field">
            <span class="axis-tag">De</span>
            <select id="diameter-range-from">${diameterOptions}</select>
          </div>
          <div class="axis-field">
            <span class="axis-tag">Ate</span>
            <select id="diameter-range-to">${diameterOptions}</select>
          </div>
        </div>
        <button id="add-diameter-range-btn" class="add-entity-btn full-add-btn">Criar variantes do range</button>
        <div class="expr-hint" style="color:var(--text-dim)">
          Uma variante por diametro: nome = CATEGORIA + codigo repetido 2x (ex.: 2" = "J" -> "...JJ"),
          PARAM 1 = diametro nominal (DN) - 25=1", 50=2", etc.
        </div>
      </div>

      <div class="variants-table-scroll variants-table-scroll-modal">
        <table class="parameters-table variants-table variants-table-modal">
          <thead>
            <tr id="variants-head-row"><th>Nome</th><th>Gtype</th></tr>
          </thead>
          <tbody id="variants-tbody"></tbody>
        </table>
      </div>
      <div id="variants-empty" class="empty-state"></div>
    </div>
  `;
  document.body.appendChild(backdrop);

  const activeSelect = backdrop.querySelector('#active-variant-select');
  const headRow = backdrop.querySelector('#variants-head-row');
  const tbodyEl = backdrop.querySelector('#variants-tbody');
  const emptyEl = backdrop.querySelector('#variants-empty');
  emptyEl.textContent = 'Nenhuma variante definida. Use "Adicionar variante" para comecar (ex.: um tamanho de suporte).';

  function render() {
    // Qualquer re-render troca o DOM inteiro da tabela - um menu de
    // contexto aberto ficaria com a referencia de `input` apontando pra um
    // elemento ja removido (ver showValueContextMenu).
    closeContextMenu();
    const parameters = parameterStore.list().slice().sort((a, b) => a.number - b.number);
    const variants = variantStore.list();

    // Seletor de variante ativa
    const activeId = variantStore.activeVariantId;
    activeSelect.innerHTML = '<option value="">(nenhuma)</option>';
    for (const variant of variants) {
      const opt = document.createElement('option');
      opt.value = variant.id;
      opt.textContent = variant.name;
      if (variant.id === activeId) opt.selected = true;
      activeSelect.appendChild(opt);
    }

    // Cabecalho
    headRow.innerHTML = '<th>Nome</th><th>Gtype</th>';
    for (const param of parameters) {
      const th = document.createElement('th');
      th.textContent = `PA${param.number}`;
      th.title = param.description || `Parametro ${param.number}`;
      headRow.appendChild(th);
    }
    headRow.appendChild(document.createElement('th'));

    // Linhas
    tbodyEl.innerHTML = '';
    emptyEl.style.display = variants.length ? 'none' : 'block';
    for (const variant of variants) {
      tbodyEl.appendChild(buildVariantRow(variant, parameters, activeId));
    }
  }

  function buildVariantRow(variant, parameters, activeId) {
    const tr = document.createElement('tr');
    if (variant.id === activeId) tr.classList.add('variant-row-active');

    const nameCell = buildCell(variant.name, 'text', 'Nome', (value) => {
      variantStore.updateVariant(variant.id, { name: value });
    });
    nameCell.querySelector('input').classList.add('param-cell-name');
    tr.appendChild(nameCell);

    const gtypeCell = buildCell(variant.gtype, 'text', 'Gtype', (value) => {
      variantStore.updateVariant(variant.id, { gtype: value });
    });
    gtypeCell.querySelector('input').classList.add('param-cell-gtype');
    tr.appendChild(gtypeCell);

    for (const param of parameters) {
      const value = variant.values[param.number] ?? '';
      const cell = buildCell(value, 'text', '', (newValue) => {
        variantStore.updateVariant(variant.id, { values: { [param.number]: newValue } });
      });
      const input = cell.querySelector('input');
      input.classList.add('param-cell-value-modal');
      _attachInchNormalization(input);
      // Botao direito - ver showValueContextMenu abaixo (decisao explicita
      // do usuario: precisava de um jeito rapido de propagar/sugerir valores
      // de PARAM entre variantes, em vez de digitar tudo a mao linha a
      // linha).
      input.addEventListener('contextmenu', (event) => {
        event.preventDefault();
        showValueContextMenu(event, variant.id, param.number, input);
      });
      tr.appendChild(cell);
    }

    const actionsTd = document.createElement('td');
    actionsTd.className = 'variant-actions';

    const activateBtn = document.createElement('button');
    activateBtn.className = 'icon-btn';
    activateBtn.textContent = variant.id === activeId ? '★' : '☆';
    activateBtn.title = 'Definir como variante ativa';
    activateBtn.addEventListener('click', () => variantStore.setActive(variant.id));

    const duplicateBtn = document.createElement('button');
    duplicateBtn.className = 'icon-btn';
    duplicateBtn.textContent = '⧉';
    duplicateBtn.title = 'Duplicar variante';
    duplicateBtn.addEventListener('click', () => variantStore.duplicateVariant(variant.id));

    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'icon-btn';
    deleteBtn.textContent = '✕';
    deleteBtn.title = 'Excluir variante';
    deleteBtn.addEventListener('click', () => variantStore.removeVariant(variant.id));

    actionsTd.appendChild(activateBtn);
    actionsTd.appendChild(duplicateBtn);
    actionsTd.appendChild(deleteBtn);
    tr.appendChild(actionsTd);

    return tr;
  }

  function buildCell(value, type, placeholder, onChange) {
    const td = document.createElement('td');
    const input = document.createElement('input');
    input.type = type;
    input.className = 'param-cell';
    input.value = value;
    if (placeholder) input.placeholder = placeholder;
    input.addEventListener('change', () => onChange(input.value));
    td.appendChild(input);
    return td;
  }

  // Menu de contexto (botao direito) numa celula de valor de PARAM - 2
  // acoes, decisao explicita do usuario:
  // 1) "Preencher X abaixo com..." - copia o valor da celula clicada pra
  //    TODAS as variantes ABAIXO dela na tabela (ordem de
  //    `variantStore.list()`, buscada NA HORA do clique - nunca um array
  //    capturado antes, mesmo cuidado de CLAUDE.md ponto 3 sobre nao fechar
  //    sobre um snapshot velho).
  // 2) Sugestoes - lista os valores DISTINTOS que esse MESMO parametro ja
  //    tem em OUTRAS variantes (mais usados primeiro), pra escolher um em
  //    vez de redigitar.
  let openContextMenu = null;
  function closeContextMenu() {
    if (openContextMenu) {
      openContextMenu.remove();
      openContextMenu = null;
    }
  }

  function showValueContextMenu(event, variantId, paramNumber, input) {
    closeContextMenu();

    const allVariants = variantStore.list();
    const currentIndex = allVariants.findIndex((v) => v.id === variantId);
    const belowVariants = currentIndex >= 0 ? allVariants.slice(currentIndex + 1) : [];
    const currentValue = input.value;

    const counts = new Map();
    allVariants.forEach((v) => {
      if (v.id === variantId) return;
      const val = String(v.values[paramNumber] ?? '').trim();
      if (val === '' || val === currentValue) return;
      counts.set(val, (counts.get(val) ?? 0) + 1);
    });
    const suggestions = [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([val]) => val);

    const menu = document.createElement('ul');
    menu.className = 'context-menu';

    function addItem(label, onClick, disabled = false) {
      const li = document.createElement('li');
      li.className = disabled ? 'context-menu-item context-menu-item-disabled' : 'context-menu-item';
      li.textContent = label;
      if (!disabled) {
        li.addEventListener('click', () => {
          onClick();
          closeContextMenu();
        });
      }
      menu.appendChild(li);
    }

    addItem(
      belowVariants.length > 0 ? `Preencher ${belowVariants.length} abaixo com "${currentValue || '(vazio)'}"` : 'Nada abaixo pra preencher',
      () => {
        belowVariants.forEach((v) => {
          variantStore.updateVariant(v.id, { values: { [paramNumber]: currentValue } });
        });
      },
      belowVariants.length === 0
    );

    if (suggestions.length > 0) {
      const sep = document.createElement('li');
      sep.className = 'context-menu-separator';
      sep.textContent = 'Sugestoes (outras variantes)';
      menu.appendChild(sep);
      suggestions.forEach((val) => {
        addItem(val, () => {
          input.value = val;
          variantStore.updateVariant(variantId, { values: { [paramNumber]: val } });
        });
      });
    }

    document.body.appendChild(menu);
    openContextMenu = menu;

    // Posiciona no cursor, depois recua se estourar a borda direita/inferior
    // da janela (o menu pode ser bem largo com sugestoes longas).
    const rect = menu.getBoundingClientRect();
    const maxLeft = window.innerWidth - rect.width - 8;
    const maxTop = window.innerHeight - rect.height - 8;
    menu.style.left = `${Math.max(8, Math.min(event.clientX, maxLeft))}px`;
    menu.style.top = `${Math.max(8, Math.min(event.clientY, maxTop))}px`;

    // Fecha ao clicar fora - proximo tick, senao o mesmo clique que ABRIU
    // (contextmenu) tambem fecharia na hora em navegadores que emitem um
    // 'click' logo em seguida.
    setTimeout(() => document.addEventListener('click', closeContextMenu, { once: true }), 0);
  }

  activeSelect.addEventListener('change', () => {
    variantStore.setActive(activeSelect.value || null);
  });

  backdrop.querySelector('#add-variant-btn').addEventListener('click', () => {
    variantStore.addVariant(createDefaultVariantData());
  });

  // "+ Adicionar range de diametros" (decisao explicita do usuario, ver
  // core/pdmsDiameterCodes.js) - cria uma variante por diametro do range
  // [De, Ate] (inclusive, nos 2 sentidos - o usuario pode escolher De >
  // Ate, o range e sempre normalizado pelo indice na tabela). Cada variante
  // nasce com `name` = nome da CATEGORY + o codigo PDMS daquele diametro
  // repetido 2x (ex.: categoria "AGT_SIE-38-002" + diametro 2" (codigo "J")
  // -> "AGT_SIE-38-002JJ" - mesmo padrao dos 2 exemplos reais em
  // REFERENCIAS/*.pmlmac) e `values[1]` = o DN daquele diametro (PARAM 1 -
  // decisao explicita do usuario: "25 = 1in, 50 = 2in").
  backdrop.querySelector('#add-diameter-range-btn').addEventListener('click', () => {
    const fromIdx = Number(backdrop.querySelector('#diameter-range-from').value);
    const toIdx = Number(backdrop.querySelector('#diameter-range-to').value);
    const lo = Math.min(fromIdx, toIdx);
    const hi = Math.max(fromIdx, toIdx);
    const categoryName = categoryStore?.get()?.name?.trim() ?? '';
    for (let i = lo; i <= hi; i++) {
      const { code, dn } = PDMS_DIAMETER_CODES[i];
      variantStore.addVariant(
        createDefaultVariantData({
          name: `${categoryName}${code}${code}`,
          values: { 1: String(dn) }
        })
      );
    }
  });

  const unsubscribers = [
    variantStore.on('variant:added', render),
    variantStore.on('variant:updated', render),
    variantStore.on('variant:removed', render),
    variantStore.on('active-changed', render),
    parameterStore.on('parameter:added', render),
    parameterStore.on('parameter:updated', render),
    parameterStore.on('parameter:removed', render)
  ];

  function close() {
    unsubscribers.forEach((unsubscribe) => unsubscribe());
    closeContextMenu();
    document.body.removeChild(backdrop);
  }

  backdrop.querySelector('#variants-dialog-close').addEventListener('click', close);
  backdrop.addEventListener('click', (event) => {
    if (event.target === backdrop) close();
  });

  render();
}
