const KEY_TO_MODE = { KeyG: 'translate', KeyR: 'rotate', KeyS: 'scale' };

// Atalhos de teclado G/R/S pra trocar o modo do gizmo (TransformControls) -
// substituem os antigos botoes Mover/Rotacionar/Escalar da toolbar (removidos
// por serem redundantes com o gizmo ja visivel na tela - mesmo padrao do
// editor do three.js/Blender, e o mesmo G/R/S que os antigos titulos dos
// botoes ja prometiam mas nunca chegaram a implementar).
//
// So troca de modo se ele fizer sentido pro objeto selecionado no momento -
// nem toda primitiva/P-point tem rotacao ou escala livre (ver
// core/PrimitiveStore.js e core/PointStore.js) - quem chama setAllowedModes()
// em main.js decide isso a cada troca de selecao.
export class TransformModeShortcuts {
  constructor({ setMode }) {
    this.setModeCallback = setMode;
    this.currentMode = 'translate';
    this.allowedModes = new Set(['translate', 'rotate', 'scale']);

    window.addEventListener('keydown', this._onKeyDown);
  }

  setAllowedModes(allowed) {
    this.allowedModes = new Set(allowed);
    if (!this.allowedModes.has(this.currentMode)) {
      this._setMode([...this.allowedModes][0] ?? 'translate');
    }
  }

  _setMode(mode) {
    this.currentMode = mode;
    this.setModeCallback(mode);
  }

  _onKeyDown = (event) => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    const target = event.target;
    // Nao rouba a tecla de quem esta digitando num campo de texto/numero
    // (varios campos do app sao letras/numeros livres, ex.: "PARAM 3").
    if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT' || target.isContentEditable)) {
      return;
    }
    const mode = KEY_TO_MODE[event.code];
    if (!mode || !this.allowedModes.has(mode)) return;
    this._setMode(mode);
  };
}
