import { createId } from '../utils/id.js';
import { EventBus } from '../utils/EventBus.js';
import { deepMerge } from '../utils/deepMerge.js';

// Tipos de primitiva disponiveis, com nome padrao e dimensoes iniciais. Os
// nomes de `dimensions` seguem os atributos reais do catalogo do E3D (ver
// capitulo 7.4 do manual de referencia - GMSET/3D Geomset Primitives):
//   Caixa (SBOX)      -> PXLE/PYLE/PZLE = width/depth/height
//   Cilindro (SCYL)   -> PDIA/PHEI = diameter/height; SEM PX/PY/PZ - a
//                        posicao vem inteiramente de PAXI (`axis`) + PDIS
//                        (`distance`, distancia da origem ate a BASE do
//                        cilindro, medida ao longo do proprio eixo) - mesmo
//                        principio de um P-point PTAXI (ver
//                        objects/PPointObject.js). Aceita eixo composto ou
//                        "PP n" (ver utils/axisExpression.js), igual as
//                        extrusoes abaixo.
//   Cone (SCON)       -> PDIA/PDIS = diameter/height; SEM PX/PY/PZ, igual ao
//                        cilindro (PAXI = `axis`), mas SEM offset separado
//                        (sem `distance`) - a base fica SEMPRE exatamente na
//                        origem/P-point de PAXI. PDIS aqui e so a altura
//                        (base ate o apice), ja coberto por `dimensions.height`.
//   Esfera (SSPH)     -> PDIA           = diameter
//   Disco (SDIS)      -> PDIA           = diameter (espessura zero)
//   Piramide (LPYR)   -> SEM PX/PY/PZ, igual ao cone. PBAX/PCAX/PAAX =
//                        `axisX`/`axisY`/`axisZ`, cada um aceitando eixo
//                        composto ou "P n" (ver utils/axisExpression.js), MAS
//                        NAO sao 3 vetores livres: PAAX e a normal (autoritativo,
//                        "pra onde a piramide aponta") e PBAX/PCAX sao
//                        ORTOGONALIZADOS contra ele (Gram-Schmidt) - as faces
//                        ficam SEMPRE perpendiculares a PAAX, confirmado pelo
//                        usuario contra o E3D de verdade (ver
//                        objects/PrimitiveObject.js: resolvePyramidBasis).
//                        PBBT/PCBT (`bottomWidth`/`bottomDepth`) e PBTP/PCTP
//                        (`topWidth`/`topDepth`, 0x0 = piramide "de ponta")
//                        sao as dimensoes de cada face; PBDI/PTDI
//                        (`distBottom`/`distTop`) sao a COORDENADA (com
//                        sinal, igual ao catalogo real - nao uma distancia
//                        sempre positiva) de cada face ao longo de PAAX,
//                        medida a partir da ORIGEM (podem ser diferentes -
//                        a origem nao precisa ficar no meio do solido);
//                        confirmado por REFERENCIAS/PYRA.PMLMAC: `PBDI
//                        ( -150 )` bota a base ANTES da origem, `PTDI 150`
//                        bota o topo DEPOIS - mesma convencao nos 2 campos,
//                        base tipicamente negativa e topo positivo, mas o
//                        app nao forca isso. PBOF/PCOF (`offsetX`/`offsetY`) deslocam
//                        o CENTRO do topo em relacao ao centro da base, no
//                        plano local - um tronco "torto", nao so um taper
//                        concentrico.
//   Snout (LSNO)      -> SEM PX/PY/PZ, igual ao cone/piramide. PAAX/PBAX =
//                        `axisA`/`axisB` - MESMA regra de eixo da extrusao (2
//                        eixos explicitos + normal = axisA x axisB - ver
//                        objects/PrimitiveObject.js: resolveExtrusionBasis,
//                        reaproveitada sem duplicar). PBDM/PTDM
//                        (`bottomDiameter`/`topDiameter`, topo 0 = cone "de
//                        ponta") sao os diametros de cada face; PBDI/PTDI
//                        (`distBottom`/`distTop`) sao a COORDENADA (com
//                        sinal - mesma convencao da piramide acima) de cada
//                        face ao longo da normal, medida a partir da
//                        origem; POFF
//                        (`offset`) desloca o CENTRO do topo ao longo do
//                        eixo A em relacao ao centro da base - so 1 eixo de
//                        excentricidade (ao contrario da piramide, que tem
//                        PBOF/PCOF separados).
//   Toro (SCTO/RTOR)  -> SEM PX/PY/PZ e SEM campo de raio/angulo - e uma
//                        curva de tubo ligando 2 pontos: PAAX/PBAX = mesmos
//                        `axisA`/`axisB` da extrusao/snout, mas aqui os 2
//                        TEM que referenciar um P-point cada ("PP n") - a
//                        POSICAO de cada ponto vira a extremidade do arco
//                        (as faces ficam EXATAMENTE nos P-points) e a
//                        DIRECAO vira a tangente do tubo naquela ponta. O
//                        raio da curva e o UNICO raio que faz o arco
//                        tangente as 2 direcoes (calculado, nao editavel -
//                        ver objects/PrimitiveObject.js: resolveTorusArc).
//                        LIMITACAO: os 2 pontos tem que compartilhar uma
//                        coordenada (X, Y ou Z) - o arco fica no plano
//                        perpendicular a esse eixo. `diameter` (PDIA) e o
//                        diametro (torus 'torus', secao redonda) ou a
//                        largura ao longo do raio (torus 'torusRect', secao
//                        retangular - PDIA/PHEI, essa com `height`
//                        adicional pra altura ao longo do eixo compartilhado).
//   Extrusao (SEXT)   -> PHEI = altura da extrusao (dimensions.height); PX/PY
//                        + PRAD de cada SVER = `vertices` (lista separada,
//                        nao cabe no formato fixo de `dimensions` - ver
//                        capitulo 7.4.17: o perfil 2D e um Loop/SLOO de
//                        Vertices/SVER). PAAX/PBAX = `axisA`/`axisB` -
//                        definem os eixos LOCAIS do plano do SLOO (onde
//                        PX/PY dos vertices sao medidos); a extrusao (PHEI)
//                        vai ao longo do eixo perpendicular aos dois
//                        (axisA x axisB) - ver objects/PrimitiveObject.js.
//                        Aceitam eixo composto ("Y45X") ou referencia a um
//                        P-point ("PP n") - ver utils/axisExpression.js.
//                        Padrao PAAX=Y/PBAX=Z (igual ao PARAGON real),
//                        entao a extrusao "de fabrica" vai ao longo de X.
// Toda primitiva usa sempre DIAMETRO, nunca raio, para partes de revolucao -
// igual ao catalogo real.
//
// Elementos NEGATIVOS (NSBO/NLCY-NSCY/NLPYRAMID - ver capitulo 7.5 do
// manual: "Negative 3D Geomsets (NGMSET) and Negative Primitives")
// representam buracos/rebaixos - tem EXATAMENTE os mesmos atributos do
// positivo correspondente (por isso `negBox`/`negCylinder`/`negPyramid`
// reaproveitam sem duplicar
// os presets/campos/geometria de `box`/`cylinder`/`pyramid` - ver
// objects/PrimitiveObject.js: basePositiveType), mas cada um SEMPRE fica
// vinculado a um elemento POSITIVO especifico via `parentId` (nunca solto
// nem filho de outro negativo) - um positivo pode ter varios negativos.
// `parentId` e SO vinculo organizacional (agrupamento na arvore/UI e ordem
// de emissao no GMSET do DATAL exportado - ver
// persistence/DatalExporter.js) - a posicao/eixo do negativo e SEMPRE
// ABSOLUTA, igual a de um positivo comum (ver
// PrimitiveObject.resolvePrimitiveOrigin), sem nenhuma soma/transform vinda
// do pai: decisao explicita do usuario, confirmada contra o E3D de verdade
// (GMSET real e uma lista plana - cap. 7.5 do manual - sem vinculo
// hierarquico de coordenada entre membros). So podem ser criados vinculados
// a um positivo ja existente e selecionado (botao "+ Adicionar negativo" no
// topo do painel - ver ui/PrimitivesPanel.js), nunca pelo menu geral
// "+ Adicionar primitiva".
const PRIMITIVE_DEFAULTS = {
  box: { name: 'Caixa', dimensions: { width: '200', depth: '200', height: '200' } },
  negBox: { name: 'Caixa Negativa', dimensions: { width: '100', depth: '100', height: '100' } },
  // PAXI (eixo unico de orientacao, igual ao de um P-point PTAXI/PTMIX - ver
  // utils/axisExpression.js): aceita eixo composto ("Y45X") ou referencia a
  // um P-point ("PP n"). SO UM eixo (ao contrario de PAAX/PBAX da extrusao,
  // que sao dois - ver comentario mais abaixo) porque o cilindro e
  // rotacionalmente simetrico ao redor do proprio eixo - nao ha "segundo
  // eixo" que faca diferenca visual. Padrao Z (cilindro "de pe"). PDIS
  // (`distance`) padrao 0 - base exatamente na origem (ou no P-point, se
  // PAXI referenciar um).
  cylinder: { name: 'Cilindro', dimensions: { diameter: '200', height: '200' }, axis: 'Z', distance: '0' },
  negCylinder: { name: 'Cilindro Negativo', dimensions: { diameter: '100', height: '200' }, axis: 'Z', distance: '0' },
  // Mesmo PAXI do cilindro acima, mas SEM PDIS de offset - a base do cone
  // fica sempre exatamente na origem/P-point (ver PrimitiveObject.resolveConeOrigin).
  cone: { name: 'Cone', dimensions: { diameter: '200', height: '300' }, axis: 'Z' },
  sphere: { name: 'Esfera', dimensions: { diameter: '200' } },
  disc: { name: 'Disco', dimensions: { diameter: '200' } },
  pyramid: {
    name: 'Piramide',
    dimensions: {
      bottomWidth: '200',
      bottomDepth: '200',
      topWidth: '0',
      topDepth: '0',
      // Base na origem (distBottom=0) e topo 300mm acima (distTop=300) -
      // mesma convencao "nasce da base" do cilindro/cone, nao centrada.
      distBottom: '0',
      distTop: '300',
      offsetX: '0',
      offsetY: '0'
    },
    // PBAX/PCAX/PAAX padrao (igual ao PARAGON real - ver comentario acima).
    axisX: 'X',
    axisY: 'Y',
    axisZ: 'Z'
  },
  negPyramid: {
    name: 'Piramide Negativa',
    dimensions: {
      bottomWidth: '100',
      bottomDepth: '100',
      topWidth: '0',
      topDepth: '0',
      distBottom: '0',
      distTop: '150',
      offsetX: '0',
      offsetY: '0'
    },
    axisX: 'X',
    axisY: 'Y',
    axisZ: 'Z'
  },
  snout: {
    name: 'Snout',
    dimensions: {
      bottomDiameter: '200',
      topDiameter: '100',
      // Base na origem (distBottom=0) e topo 200mm acima (distTop=200) -
      // mesma convencao "nasce da base" do cilindro/cone/piramide.
      distBottom: '0',
      distTop: '200',
      offset: '0'
    }
    // axisA/axisB nao precisam de preset proprio - o padrao generico Y/Z
    // (ver createDefaultPrimitiveData abaixo) ja bate com o PARAGON real.
  },
  // axisA/axisB nao precisam de preset proprio - o padrao generico Y/Z (ver
  // createDefaultPrimitiveData abaixo) ja bate com o PARAGON real. So
  // funciona de verdade quando os 2 referenciam um P-point (ver
  // PrimitiveObject.resolveTorusArc) - sem isso fica com uma geometria de
  // fallback ate o usuario usar o botao "PPnt" nos 2 campos.
  torus: { name: 'Toro', dimensions: { diameter: '100' } },
  torusRect: { name: 'Toro Retangular', dimensions: { diameter: '100', height: '100' } },
  extrusion: {
    name: 'Extrusao',
    dimensions: { height: '300' },
    // PAAX/PBAX padrao (igual ao PARAGON real - ver o dialogo de SEXT).
    axisA: 'Y',
    axisB: 'Z',
    // Retangulo simples por padrao (quinas vivas, PRAD 0) - um ponto de
    // partida seguro pro usuario editar (ver 7.4.17: SVER = PX/PY/PRAD).
    vertices: [
      { x: '-100', y: '-100', radius: '0' },
      { x: '100', y: '-100', radius: '0' },
      { x: '100', y: '100', radius: '0' },
      { x: '-100', y: '100', radius: '0' }
    ]
  }
};

// Estrutura de dados central de uma primitiva. Estas sao os elementos
// basicos que, numa etapa futura, serao convertidos em geometria e DATAL do
// E3D. Segue o mesmo padrao do ReferenceStore: estado centralizado +
// eventos, nada acessa o Three.js diretamente.
export function createDefaultPrimitiveData(type, overrides = {}) {
  const preset = PRIMITIVE_DEFAULTS[type] ?? PRIMITIVE_DEFAULTS.box;
  const base = {
    id: createId(),
    name: preset.name,
    type,
    // Posicao tambem e expressao (mesma regra de `dimensions` abaixo) - ver
    // utils/expressionEvaluator.js. NAO USADA por type==='cylinder' (SCYL
    // nao tem PX/PY/PZ no catalogo real - ver `axis`/`distance` abaixo);
    // mantida no formato comum so pra nao especializar toda a UI/persistencia
    // genericas de primitiva por causa de um unico tipo.
    position: { x: '0', y: '0', z: '0' },
    // SEM rotacao por enquanto: nem toda primitiva do catalogo real tem um
    // atributo de rotacao generico (SBOX, por exemplo, so tem PX/PY/PZ e
    // PXLE/PYLE/PZLE - a orientacao de primitivas de revolucao vem de PAXI,
    // um unico eixo, nao de uma rotacao X/Y/Z livre). Ate isso ser modelado
    // direito, a primitiva fica sempre com eixos alinhados ao mundo.
    //
    // SEM escala tambem: no catalogo real o tamanho de uma primitiva e
    // definido inteiramente pelos atributos de dimensao (PXLE/PYLE/PZLE,
    // PDIA, etc.) - nao existe um atributo de escala generico separado.
    color: '#8fb8d8',
    opacity: 1,
    visible: true,
    locked: false,
    // Cada dimensao e sempre uma STRING avaliada por
    // utils/expressionEvaluator.js: um numero literal ("200") e so uma
    // expressao trivial; tambem aceita referencias a parametro da variante
    // ativa, como "PARAM 12" ou aritmetica "PARAM 10 / 4 - PARAM 12 / 2"
    // (ver REFERENCIAS/SUPORTE_SDE-37-005.pmlmac).
    dimensions: { ...preset.dimensions },
    // So usado por type==='extrusion' (SEXT) - lista de vertices do perfil
    // 2D (SVER: PX/PY/PRAD), cada campo uma expressao. Ids frescos a cada
    // chamada (nunca reusar os objetos do preset entre primitivas diferentes).
    vertices: (preset.vertices ?? []).map((v) => ({ id: createId(), ...v })),
    // So usado por type==='extrusion' - PAAX/PBAX, eixos locais do plano do
    // SLOO (expressao de eixo composto ou "PP n" - ver utils/axisExpression.js).
    axisA: preset.axisA ?? 'Y',
    axisB: preset.axisB ?? 'Z',
    // So usado por type==='cylinder'|'cone' - PAXI, eixo unico de orientacao
    // (mesma expressao de eixo composto ou "PP n" - ver comentario no preset
    // acima).
    axis: preset.axis ?? 'Z',
    // So usado por type==='cylinder' - PDIS, distancia (mm, expressao) da
    // origem ate a BASE do cilindro, medida ao longo de `axis`.
    distance: preset.distance ?? '0',
    // So usado por type==='pyramid' - PBAX/PCAX/PAAX, os 3 eixos LOCAIS
    // independentes (ver comentario no preset acima e
    // objects/PrimitiveObject.js: resolvePyramidBasis).
    axisX: preset.axisX ?? 'X',
    axisY: preset.axisY ?? 'Y',
    axisZ: preset.axisZ ?? 'Z',
    // So usado por elementos NEGATIVOS (negBox/negCylinder - ver comentario
    // em PRIMITIVE_DEFAULTS acima) - id do elemento POSITIVO ao qual este
    // negativo esta vinculado. null para qualquer elemento positivo (nunca
    // tem pai). SO vinculo organizacional - `position`/`axis`/`distance` de
    // um negativo continuam ABSOLUTOS (ao mundo), igual a um positivo comum
    // (ver objects/PrimitiveObject.js: resolvePrimitiveOrigin).
    parentId: overrides.parentId ?? null,
    parameters: {} // reservado para uso futuro (vinculo com a biblioteca de tipos de suporte)
  };
  return { ...base, ...overrides };
}

// Tipos negativos disponiveis (ver comentario em PRIMITIVE_DEFAULTS) - usado
// por ui/PrimitivesPanel.js (menu "+ negativo" por linha) e
// objects/PrimitiveObject.js (aparencia distinta + geometria reaproveitada
// do positivo correspondente).
export const NEGATIVE_PRIMITIVE_TYPES = new Set(['negBox', 'negCylinder', 'negPyramid']);

export function isNegativePrimitiveType(type) {
  return NEGATIVE_PRIMITIVE_TYPES.has(type);
}

export class PrimitiveStore {
  constructor() {
    this.bus = new EventBus();
    this.items = new Map();
    this.order = [];
  }

  on(event, cb) {
    return this.bus.on(event, cb);
  }

  list() {
    return this.order.map((id) => this.items.get(id));
  }

  get(id) {
    return this.items.get(id) ?? null;
  }

  addPrimitive(data) {
    this.items.set(data.id, data);
    this.order.push(data.id);
    this.bus.emit('primitive:added', data);
    return data;
  }

  updatePrimitive(id, patch) {
    const current = this.items.get(id);
    if (!current) return null;
    const updated = deepMerge(current, patch);
    this.items.set(id, updated);
    this.bus.emit('primitive:updated', updated);
    return updated;
  }

  // Apagar um elemento POSITIVO leva junto todos os negativos vinculados a
  // ele (ver `parentId` em createDefaultPrimitiveData) - um negativo orfao
  // (pai apagado, ele continua existindo) nao faz sentido nenhum.
  removePrimitive(id) {
    if (!this.items.has(id)) return;
    this.list()
      .filter((p) => p.parentId === id)
      .forEach((child) => this.removePrimitive(child.id));
    this.items.delete(id);
    this.order = this.order.filter((itemId) => itemId !== id);
    this.bus.emit('primitive:removed', id);
  }

  duplicatePrimitive(id) {
    const source = this.items.get(id);
    if (!source) return null;
    // Nasce na MESMA posicao do original (sem deslocar) - reposicionar fica a
    // cargo de quem modela.
    const copy = createDefaultPrimitiveData(source.type, {
      ...structuredClone(source),
      id: createId(),
      // Sem espacos/parenteses: nomes no E3D nao aceitam esses caracteres.
      name: `${source.name}_copy`
    });
    return this.addPrimitive(copy);
  }

  clear() {
    [...this.order].forEach((id) => this.removePrimitive(id));
  }
}
