import { parseNumberWithUnits } from '../utils/expressionEvaluator.js';

// Modal que pede a distancia real (mm) que os 2 pontos escolhidos na
// referencia devem representar - mostra tambem a distancia atualmente
// medida entre eles, para contexto (equivalente ao "Reference length" do
// SCALE -> Reference do AutoCAD). Resolve com o valor digitado (numero > 0),
// ou null se cancelado.
//
// O campo e type="text" (nao "number") de proposito: aceita "2.5in" (ver
// utils/expressionEvaluator.js) - um <input type="number"> nativo bloqueia
// letras e nunca deixaria digitar isso.
export function openScaleReferenceDialog(measuredDistanceMm) {
  return new Promise((resolve) => {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.innerHTML = `
      <div class="modal">
        <h2>Escalonar por 2 pontos</h2>
        <div class="prop-group">
          <label class="prop-label">Distancia medida atual (mm)</label>
          <input type="text" class="full" value="${measuredDistanceMm.toFixed(3)}" disabled />
        </div>
        <div class="prop-group">
          <label class="prop-label">Nova distancia real entre os pontos (mm) - aceita polegadas, ex.: "2.5in"</label>
          <input type="text" id="scale-ref-value" class="full" />
        </div>
        <div class="modal-actions">
          <button id="scale-ref-cancel">Cancelar</button>
          <button id="scale-ref-confirm" class="active">Aplicar</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);

    const input = backdrop.querySelector('#scale-ref-value');
    input.focus();

    function close(result) {
      document.body.removeChild(backdrop);
      resolve(result);
    }

    function confirm() {
      const value = parseNumberWithUnits(input.value);
      if (!Number.isFinite(value) || value <= 0) {
        input.focus();
        return;
      }
      close(value);
    }

    backdrop.querySelector('#scale-ref-cancel').addEventListener('click', () => close(null));
    backdrop.querySelector('#scale-ref-confirm').addEventListener('click', confirm);
    input.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') confirm();
      if (event.key === 'Escape') close(null);
    });
    backdrop.addEventListener('click', (event) => {
      if (event.target === backdrop) close(null);
    });
  });
}
